const c=3,n="dao-duc",h="Đạo đức lớp 3",i="internal",t=[{id:"yeu-to-quoc",title:"Em yêu Tổ quốc Việt Nam",lessons:[{id:"dd3-quoc-ki",title:"Quốc kì Việt Nam",weeks:[1,2],learn:[{title:"Quốc kì là gì?",text:"Quốc kì là lá cờ Tổ quốc, là biểu tượng thiêng liêng của nước Việt Nam.",example:"🇻🇳"},{title:"Hình dáng Quốc kì",text:"Quốc kì Việt Nam hình chữ nhật, nền đỏ, chính giữa có ngôi sao vàng năm cánh.",example:"🟥 ⭐"},{title:"Trân trọng Quốc kì",text:"Em giữ lá cờ sạch đẹp, không vẽ bậy, không giẫm lên cờ. Khi chào cờ, em đứng nghiêm, mắt nhìn lá cờ.",example:"🧍 🇻🇳"}],practice:[{questions:[{id:"dd3-quoc-ki-01",type:"mc",q:"Quốc kì Việt Nam có nền màu gì?",emoji:"🇻🇳",explain:"Quốc kì Việt Nam có nền đỏ, chính giữa là ngôi sao vàng.",options:["Màu đỏ","Màu xanh","Màu vàng","Màu trắng"],answer:0},{id:"dd3-quoc-ki-02",type:"mc",q:"Ngôi sao trên Quốc kì Việt Nam có màu gì?",emoji:"⭐",explain:"Ngôi sao trên Quốc kì có màu vàng, nằm giữa nền đỏ.",options:["Màu đỏ","Màu vàng","Màu xanh","Màu trắng"],answer:1},{id:"dd3-quoc-ki-03",type:"mc",q:"Ngôi sao trên Quốc kì có mấy cánh?",explain:"Ngôi sao trên lá cờ Tổ quốc là ngôi sao vàng năm cánh.",options:["Bốn cánh","Sáu cánh","Năm cánh","Ba cánh"],answer:2},{id:"dd3-quoc-ki-04",type:"tf",q:"Quốc kì là lá cờ của Tổ quốc.",explain:"Đúng rồi. Quốc kì là lá cờ Tổ quốc, biểu tượng của nước Việt Nam.",answer:!0},{id:"dd3-quoc-ki-05",type:"tf",q:"Ngôi sao trên Quốc kì nằm ở góc trên bên trái lá cờ.",explain:"Sai. Ngôi sao vàng nằm ở chính giữa lá cờ.",answer:!1},{id:"dd3-quoc-ki-06",type:"mc",q:"Lá cờ Tổ quốc còn được gọi là gì?",explain:"Lá cờ Tổ quốc gọi là Quốc kì. Quốc ca là bài hát của Tổ quốc.",options:["Quốc ca","Quốc kì","Quốc khánh","Quốc ngữ"],answer:1},{id:"dd3-quoc-ki-07",type:"fill",q:"Quốc kì Việt Nam có nền đỏ, ở giữa có ngôi sao màu …",explain:"Quốc kì có nền đỏ, ngôi sao màu vàng.",answer:["vàng"]},{id:"dd3-quoc-ki-08",type:"tf",q:"Quốc kì Việt Nam có hình tròn.",explain:"Sai. Quốc kì Việt Nam có hình chữ nhật.",answer:!1},{id:"dd3-quoc-ki-09",type:"tf",q:"Quốc kì là biểu tượng thiêng liêng của đất nước.",explain:"Đúng rồi. Vì thế chúng ta luôn trân trọng lá cờ Tổ quốc.",answer:!0}]},{questions:[{id:"dd3-quoc-ki-10",type:"multi",q:"Những việc làm nào thể hiện sự tôn trọng Quốc kì?",explain:"Đứng nghiêm khi chào cờ và giữ lá cờ sạch đẹp là tôn trọng Quốc kì.",options:["Đứng nghiêm khi chào cờ","Giữ lá cờ sạch, không làm rách","Vẽ bậy lên lá cờ","Dùng lá cờ để lau bàn"],answers:[0,1]},{id:"dd3-quoc-ki-11",type:"tf",q:"Nam lấy lá cờ nhỏ làm khăn lau bảng. Nam làm đúng.",explain:"Sai. Lá cờ Tổ quốc cần được trân trọng, không dùng để lau chùi.",answer:!1},{id:"dd3-quoc-ki-12",type:"mc",q:"Vì sao chúng ta phải tôn trọng Quốc kì?",explain:"Quốc kì là biểu tượng của Tổ quốc, nên tôn trọng Quốc kì là tôn trọng đất nước.",options:["Vì Quốc kì là biểu tượng của Tổ quốc Việt Nam","Vì lá cờ có màu đỏ và vàng rất đẹp, rất nổi bật","Vì lá cờ được may bằng loại vải rất đắt tiền","Vì lá cờ to hơn tất cả các lá cờ khác ở trường"],answer:0},{id:"dd3-quoc-ki-13",type:"match",q:"Nối mỗi từ với ý nghĩa của nó.",explain:"Quốc kì là lá cờ, Quốc ca là bài hát, Quốc khánh là ngày lễ mừng đất nước vào 2 tháng 9.",pairs:[["Quốc kì","Lá cờ Tổ quốc"],["Quốc ca","Bài hát của Tổ quốc"],["Quốc khánh","Ngày lễ 2 tháng 9"]]},{id:"dd3-quoc-ki-14",type:"tf",q:"Vào ngày Quốc khánh 2 tháng 9, nhiều gia đình treo cờ Tổ quốc trước nhà.",explain:"Đúng rồi. Treo cờ ngày lễ thể hiện niềm vui và tình yêu đất nước.",answer:!0},{id:"dd3-quoc-ki-15",type:"mc",q:"Thấy lá cờ nhỏ của lớp bị rơi xuống đất, em nên làm gì?",explain:"Nhặt lá cờ lên, phủi sạch và cất cẩn thận là trân trọng Quốc kì.",options:["Bước qua lá cờ rồi đi tiếp vào lớp","Lấy chân đá lá cờ sang một bên cho gọn","Lấy lá cờ làm đồ chơi với các bạn","Nhặt lên, phủi sạch và cất đúng chỗ"],answer:3},{id:"dd3-quoc-ki-16",type:"tf",q:"Quốc kì được treo ở sân trường, trụ sở cơ quan và nhiều nơi trong cả nước.",explain:"Đúng rồi. Lá cờ Tổ quốc được treo trang trọng ở nhiều nơi.",answer:!0},{id:"dd3-quoc-ki-17",type:"mc",q:"Hình ảnh lá cờ đỏ sao vàng giúp em nhớ đến điều gì?",explain:"Lá cờ đỏ sao vàng là Quốc kì, tượng trưng cho Tổ quốc Việt Nam.",options:["Một món đồ chơi","Tổ quốc Việt Nam","Một loại bánh","Một con vật"],answer:1},{id:"dd3-quoc-ki-18",type:"tf",q:"Chỉ người lớn mới cần tôn trọng Quốc kì, trẻ em thì không cần.",explain:"Sai. Mọi người, kể cả trẻ em, đều cần tôn trọng Quốc kì.",answer:!1}]},{questions:[{id:"dd3-quoc-ki-19",type:"mc",q:"Giờ ra chơi, Bình thấy mấy bạn lấy lá cờ nhỏ quấn lên đầu để đùa nghịch. Bình nên làm gì?",explain:"Bình nên nhắc nhở bạn nhẹ nhàng để mọi người cùng trân trọng lá cờ.",options:["Cùng quấn cờ lên đầu cho vui với các bạn","Coi như không thấy rồi đi chỗ khác","Giật lá cờ rồi vứt đi","Nhẹ nhàng nhắc các bạn giữ gìn lá cờ"],answer:3},{id:"dd3-quoc-ki-20",type:"mc",q:"Lớp Lan vẽ Quốc kì để trang trí. Lan nên vẽ thế nào cho đúng?",emoji:"🖍️",explain:"Quốc kì có nền đỏ, ngôi sao vàng năm cánh nằm chính giữa.",options:["Nền vàng, ngôi sao đỏ năm cánh ở giữa","Nền đỏ, ngôi sao vàng năm cánh ở giữa","Nền đỏ, ngôi sao vàng năm cánh ở góc trên","Nền xanh, ngôi sao vàng năm cánh ở giữa"],answer:1},{id:"dd3-quoc-ki-21",type:"tf",q:"Thấy lá cờ trước cổng nhà đã bạc màu và rách, Minh nhờ bố mẹ thay lá cờ mới. Minh làm đúng.",explain:"Đúng rồi. Lá cờ treo cần luôn lành lặn, tươi màu.",answer:!0},{id:"dd3-quoc-ki-22",type:"multi",q:"Trong giờ chào cờ, những bạn nào làm chưa đúng?",explain:"Khi chào cờ cần đứng nghiêm, bỏ mũ, không nói chuyện. Chỉ Vy làm đúng.",options:["Khoa nói chuyện riêng","Thảo quay ngang quay ngửa","Vy đứng nghiêm nhìn lá cờ","Tùng vẫn đội mũ"],answers:[0,1,3]},{id:"dd3-quoc-ki-23",type:"order",q:"Sắp xếp các bước vẽ lá cờ Tổ quốc.",explain:"Vẽ khung hình chữ nhật trước, rồi vẽ ngôi sao, sau cùng tô màu.",items:["Vẽ một hình chữ nhật","Vẽ ngôi sao năm cánh ở chính giữa","Tô nền màu đỏ và ngôi sao màu vàng"]},{id:"dd3-quoc-ki-24",type:"mc",q:"Em trai của Hà định lấy bút vẽ bậy lên lá cờ nhà mình. Hà nên làm gì?",explain:"Hà nên ngăn em và giải thích nhẹ nhàng để em biết trân trọng lá cờ.",options:["Đưa thêm bút màu cho em vẽ thêm lên lá cờ","Ngăn em lại và giải thích cần giữ gìn lá cờ","Mặc kệ em muốn vẽ gì thì vẽ vì em còn nhỏ","Khen em vẽ đẹp và rủ em vẽ thêm nhiều hình nữa"],answer:1},{id:"dd3-quoc-ki-25",type:"tf",q:"Ngọc cất lá cờ nhỏ được tặng trong ngày lễ cẩn thận vào hộp. Ngọc đã biết trân trọng Quốc kì.",explain:"Đúng rồi. Giữ lá cờ cẩn thận là trân trọng Quốc kì.",answer:!0},{id:"dd3-quoc-ki-26",type:"fill",q:"Lá cờ đỏ sao vàng là … của nước Việt Nam.",explain:"Lá cờ đỏ sao vàng là Quốc kì Việt Nam.",answer:["Quốc kì","quốc kì","Quốc kỳ","quốc kỳ"]},{id:"dd3-quoc-ki-27",type:"tf",q:"Phúc lấy lá cờ bị ướt làm thảm chùi chân. Phúc làm đúng.",explain:"Sai. Lá cờ Tổ quốc không được dùng làm thảm chùi chân.",answer:!1}]}],challenge:{questions:[{id:"dd3-quoc-ki-28",type:"mc",q:"Đi tham quan, Chi thấy lá cờ trên cột bị tuột dây, rủ xuống. Chi nên làm gì?",explain:"Chi nên báo người lớn. Trèo cột cờ rất nguy hiểm.",options:["Tự trèo lên cột cờ để sửa","Báo cho người lớn ở đó để treo lại","Kéo lá cờ xuống mang về","Không quan tâm vì không phải việc của mình"],answer:1},{id:"dd3-quoc-ki-29",type:"multi",q:"Những câu nào nói đúng về Quốc kì Việt Nam?",explain:"Quốc kì nền đỏ, sao vàng năm cánh, là biểu tượng của Tổ quốc.",options:["Có nền màu đỏ","Có ngôi sao vàng năm cánh","Ngôi sao có sáu cánh","Là biểu tượng của Tổ quốc"],answers:[0,1,3]},{id:"dd3-quoc-ki-30",type:"match",q:"Nối mỗi phần của Quốc kì với đặc điểm của nó.",explain:"Quốc kì có nền đỏ và ngôi sao vàng năm cánh.",pairs:[["Nền cờ","Màu đỏ"],["Ngôi sao","Màu vàng"],["Số cánh sao","Năm cánh"]]},{id:"dd3-quoc-ki-19",type:"mc",q:"Giờ ra chơi, Bình thấy mấy bạn lấy lá cờ nhỏ quấn lên đầu để đùa nghịch. Bình nên làm gì?",explain:"Bình nên nhắc nhở bạn nhẹ nhàng để mọi người cùng trân trọng lá cờ.",options:["Cùng quấn cờ lên đầu cho vui với các bạn","Coi như không thấy rồi đi chỗ khác","Giật lá cờ rồi vứt đi","Nhẹ nhàng nhắc các bạn giữ gìn lá cờ"],answer:3},{id:"dd3-quoc-ki-22",type:"multi",q:"Trong giờ chào cờ, những bạn nào làm chưa đúng?",explain:"Khi chào cờ cần đứng nghiêm, bỏ mũ, không nói chuyện. Chỉ Vy làm đúng.",options:["Khoa nói chuyện riêng","Thảo quay ngang quay ngửa","Vy đứng nghiêm nhìn lá cờ","Tùng vẫn đội mũ"],answers:[0,1,3]},{id:"dd3-quoc-ki-12",type:"mc",q:"Vì sao chúng ta phải tôn trọng Quốc kì?",explain:"Quốc kì là biểu tượng của Tổ quốc, nên tôn trọng Quốc kì là tôn trọng đất nước.",options:["Vì Quốc kì là biểu tượng của Tổ quốc Việt Nam","Vì lá cờ có màu đỏ và vàng rất đẹp, rất nổi bật","Vì lá cờ được may bằng loại vải rất đắt tiền","Vì lá cờ to hơn tất cả các lá cờ khác ở trường"],answer:0}]},summary:["Quốc kì Việt Nam nền đỏ, chính giữa có ngôi sao vàng năm cánh.","Quốc kì là biểu tượng thiêng liêng của Tổ quốc.","Em giữ lá cờ sạch đẹp và đứng nghiêm khi chào cờ."]},{id:"dd3-quoc-ca",title:"Quốc ca và nghi thức chào cờ",weeks:[3,4],learn:[{title:"Quốc ca Việt Nam",text:"Quốc ca Việt Nam là bài “Tiến quân ca” của nhạc sĩ Văn Cao.",example:"🎵"},{title:"Lễ chào cờ",text:"Ở trường, lễ chào cờ thường diễn ra vào sáng thứ Hai đầu tuần. Cả trường cùng hát Quốc ca.",example:"🏫 🇻🇳"},{title:"Tư thế chào cờ",text:"Em đứng nghiêm, bỏ mũ nón, mắt nhìn Quốc kì, hát Quốc ca to, rõ. Em không nói chuyện, không làm việc riêng.",example:"🧍"}],practice:[{questions:[{id:"dd3-quoc-ca-01",type:"mc",q:"Quốc ca Việt Nam là bài hát nào?",emoji:"🎵",explain:"Quốc ca Việt Nam là bài “Tiến quân ca”.",options:["Tiến quân ca","Kìa con bướm vàng","Cả nhà thương nhau","Bắc kim thang"],answer:0},{id:"dd3-quoc-ca-02",type:"mc",q:"Ai là tác giả bài Quốc ca Việt Nam?",explain:"Bài “Tiến quân ca” do nhạc sĩ Văn Cao sáng tác.",options:["Nhạc sĩ Văn Cao","Nhạc sĩ Phạm Tuyên","Nhạc sĩ Hoàng Long"],answer:0},{id:"dd3-quoc-ca-03",type:"tf",q:"Khi chào cờ, em đứng nghiêm, mắt nhìn Quốc kì.",explain:"Đúng rồi. Đó là tư thế đúng khi chào cờ.",answer:!0},{id:"dd3-quoc-ca-04",type:"tf",q:"Khi hát Quốc ca, em có thể vừa hát vừa nói chuyện với bạn.",explain:"Sai. Khi hát Quốc ca phải nghiêm trang, không nói chuyện.",answer:!1},{id:"dd3-quoc-ca-05",type:"multi",q:"Khi chào cờ, em cần làm gì?",explain:"Khi chào cờ, em đứng nghiêm, hát to, rõ, không đội mũ, không cười đùa.",options:["Đứng nghiêm","Đội mũ cho đỡ nắng","Hát Quốc ca to, rõ","Cười đùa với bạn"],answers:[0,2]},{id:"dd3-quoc-ca-06",type:"mc",q:"Khi chào cờ, mắt em nhìn về đâu?",explain:"Khi chào cờ, mắt em hướng về lá Quốc kì.",options:["Nhìn xuống đất","Nhìn lá Quốc kì","Nhìn sang bạn bên cạnh","Nhìn ra cổng trường"],answer:1},{id:"dd3-quoc-ca-07",type:"fill",q:"Bài hát chính thức của nước ta gọi là Quốc …",explain:"Bài hát chính thức của nước ta là Quốc ca.",answer:["ca"]},{id:"dd3-quoc-ca-08",type:"tf",q:"Ở trường, lễ chào cờ thường diễn ra vào sáng thứ Hai đầu tuần.",explain:"Đúng rồi. Buổi chào cờ mở đầu một tuần học mới.",answer:!0},{id:"dd3-quoc-ca-09",type:"tf",q:"Khi đang đội mũ, em cứ để nguyên mũ trên đầu lúc chào cờ.",explain:"Sai. Khi chào cờ, em bỏ mũ nón ra để thể hiện sự trang nghiêm.",answer:!1}]},{questions:[{id:"dd3-quoc-ca-10",type:"order",q:"Sắp xếp các việc em làm khi chuẩn bị chào cờ.",explain:"Em xếp hàng, bỏ mũ, đứng nghiêm rồi cùng hát Quốc ca.",items:["Xếp hàng ngay ngắn","Bỏ mũ nón","Đứng nghiêm, nhìn Quốc kì","Hát Quốc ca to, rõ"]},{id:"dd3-quoc-ca-11",type:"mc",q:"Vì sao khi chào cờ phải đứng nghiêm trang?",explain:"Đứng nghiêm trang khi chào cờ là thể hiện lòng kính trọng Tổ quốc.",options:["Để chân đỡ mỏi khi đứng lâu ngoài sân","Để nhìn thấy các bạn ở hàng trên rõ hơn","Để được cô cho về lớp sớm hơn","Để thể hiện lòng kính trọng Tổ quốc"],answer:3},{id:"dd3-quoc-ca-12",type:"tf",q:"Hát Quốc ca to, rõ, đúng lời là thể hiện tình yêu Tổ quốc.",explain:"Đúng rồi. Hát Quốc ca nghiêm túc là cách em bày tỏ tình yêu đất nước.",answer:!0},{id:"dd3-quoc-ca-13",type:"multi",q:"Những bạn nào làm chưa đúng trong giờ chào cờ?",explain:"Dũng và Hà làm việc riêng trong giờ chào cờ, như vậy là chưa đúng.",options:["Lan đứng nghiêm và hát to","Dũng vừa hát vừa nghịch dây giày","Hà thì thầm kể chuyện với bạn","Nam bỏ mũ cầm trên tay"],answers:[1,2]},{id:"dd3-quoc-ca-14",type:"mc",q:"Lễ chào cờ thể hiện điều gì?",explain:"Lễ chào cờ thể hiện lòng yêu nước và sự kính trọng Tổ quốc.",options:["Một cuộc thi hát giữa các lớp","Một giờ nghỉ giải lao đầu tuần của cả trường","Lòng yêu nước, kính trọng Tổ quốc","Một trò chơi tập thể trên sân trường"],answer:2},{id:"dd3-quoc-ca-15",type:"tf",q:"Chỉ khi có thầy cô nhìn thì mới cần nghiêm trang khi chào cờ.",explain:"Sai. Em nghiêm trang khi chào cờ vì kính trọng Tổ quốc, không phải vì có người nhìn.",answer:!1},{id:"dd3-quoc-ca-16",type:"match",q:"Nối tình huống với cách làm đúng khi chào cờ.",explain:"Khi chào cờ, em bỏ mũ, không nói chuyện và hát Quốc ca to, rõ.",pairs:[["Đang đội mũ","Bỏ mũ xuống"],["Bạn rủ nói chuyện","Lắc đầu, giữ nghiêm trang"],["Khi hát Quốc ca","Hát to, rõ, đúng lời"]]},{id:"dd3-quoc-ca-17",type:"mc",q:"Nếu chưa thuộc hết lời Quốc ca, em nên làm gì?",explain:"Em vẫn đứng nghiêm và chăm tập để lần sau hát thuộc lời.",options:["Bỏ ra ngoài hàng đứng một mình cho đỡ ngại","Vẫn đứng nghiêm và về nhà tập cho thuộc","Nói chuyện với bạn bên cạnh cho qua giờ","Bịt tai lại và chờ mọi người hát xong"],answer:1},{id:"dd3-quoc-ca-18",type:"tf",q:"Khi dự lễ chào cờ ở nơi khác ngoài trường học, em cũng cần đứng nghiêm trang.",explain:"Đúng rồi. Ở đâu chào cờ, em cũng cần nghiêm trang.",answer:!0}]},{questions:[{id:"dd3-quoc-ca-19",type:"mc",q:"Trong giờ chào cờ, bạn bên cạnh trêu chọc Tùng. Tùng nên làm gì?",explain:"Tùng nên giữ nghiêm trang, sau giờ chào cờ mới nhẹ nhàng nhắc bạn.",options:["Trêu lại bạn ngay trong lúc chào cờ cho bạn biết tay","Đẩy bạn ra rồi chạy lên mách cô ngay","Bỏ ra khỏi hàng để đứng chỗ khác","Giữ nghiêm trang, chào cờ xong mới nhắc bạn"],answer:3},{id:"dd3-quoc-ca-20",type:"mc",q:"Minh đến trường đúng lúc cả trường đang hát Quốc ca. Minh nên làm gì?",explain:"Khi Quốc ca vang lên, Minh nên dừng lại và đứng nghiêm.",options:["Chạy thật nhanh qua sân vào lớp cho kịp giờ học","Dừng lại, đứng nghiêm hướng về lá cờ đến khi hát xong","Đứng ở cổng nói chuyện với bác bảo vệ cho đến khi hát xong","Quay về nhà vì đã đến muộn mất rồi"],answer:1},{id:"dd3-quoc-ca-21",type:"tf",q:"Khi xem một trận bóng đá có cử Quốc ca Việt Nam, Khoa đứng dậy nghiêm trang. Khoa làm đúng.",explain:"Đúng rồi. Khi Quốc ca vang lên, ta đứng nghiêm để thể hiện lòng kính trọng.",answer:!0},{id:"dd3-quoc-ca-22",type:"multi",q:"Để chuẩn bị tốt cho lễ chào cờ, em nên làm gì?",explain:"Mặc gọn gàng, thuộc lời Quốc ca, đến đúng giờ giúp buổi chào cờ trang nghiêm.",options:["Mặc đồng phục gọn gàng","Tập hát thuộc lời Quốc ca","Đến trường đúng giờ","Mang đồ chơi ra sân","Đến muộn cho khỏi phải đứng lâu"],answers:[0,1,2]},{id:"dd3-quoc-ca-23",type:"order",q:"Sắp xếp các việc Vy làm khi nghe hiệu lệnh chào cờ.",explain:"Vy dừng việc, quay về phía lá cờ, đứng nghiêm rồi hát Quốc ca.",items:["Dừng ngay việc đang làm","Quay về phía lá cờ","Đứng nghiêm","Hát Quốc ca"]},{id:"dd3-quoc-ca-24",type:"tf",q:"Thảo nghĩ mình hát nhỏ cũng được vì các bạn khác đã hát to. Thảo nghĩ đúng.",explain:"Sai. Mỗi bạn đều cần hát Quốc ca to, rõ để thể hiện tình yêu Tổ quốc.",answer:!1},{id:"dd3-quoc-ca-25",type:"mc",q:"Ở lễ chào cờ của khu phố, em trai của Phúc cứ quay ngang quay dọc. Phúc nên làm gì?",explain:"Phúc nên nhắc em khẽ khàng để em biết cách chào cờ đúng.",options:["Quay ngang quay dọc cùng em cho em vui","Mắng em thật to trước mặt mọi người","Nhẹ nhàng nhắc em đứng nghiêm nhìn lá cờ","Mặc kệ em, mình chỉ cần đứng nghiêm là được"],answer:2},{id:"dd3-quoc-ca-26",type:"fill",q:"Khi chào cờ, em đứng … , mắt nhìn Quốc kì.",explain:"Khi chào cờ, em đứng nghiêm, mắt nhìn Quốc kì.",answer:["nghiêm"]},{id:"dd3-quoc-ca-27",type:"mc",q:"Lớp em được chọn hát Quốc ca trong lễ khai giảng. Em nên làm gì?",explain:"Em nên tập luyện chăm chỉ để hát Quốc ca thật hay và trang nghiêm.",options:["Chăm chỉ tập hát đúng lời, đúng nhạc","Không cần tập vì mình đã biết hát rồi","Chỉ mấp máy môi cho đỡ mệt khi hát","Nhờ bạn khác hát thay phần của mình"],answer:0}]}],challenge:{questions:[{id:"dd3-quoc-ca-28",type:"tf",q:"Chào cờ và hát Quốc ca là cách thể hiện lòng biết ơn và tình yêu Tổ quốc.",explain:"Đúng rồi. Mỗi buổi chào cờ nhắc em nhớ ơn và yêu Tổ quốc.",answer:!0},{id:"dd3-quoc-ca-29",type:"multi",q:"Những bạn nào thực hiện đúng nghi thức chào cờ?",explain:"Ngọc, An và Chi làm đúng. Không ăn uống khi chào cờ.",options:["Ngọc đứng thẳng, hai tay buông xuôi","An bỏ mũ, mắt nhìn lá cờ","Bình vừa hát vừa ăn bánh","Chi hát to, rõ, đúng lời"],answers:[0,1,3]},{id:"dd3-quoc-ca-30",type:"mc",q:"Vì sao khi Quốc ca vang lên ở bất cứ đâu, chúng ta cũng nên đứng nghiêm?",explain:"Quốc ca là bài hát thiêng liêng của Tổ quốc, nên ở đâu ta cũng nghiêm trang.",options:["Vì Quốc ca là bài hát thiêng liêng của Tổ quốc","Vì sợ người xung quanh nhìn thấy và nhắc nhở mình","Vì bài hát rất dài nên phải đứng yên để nghe","Vì muốn được mọi người chụp ảnh khi đứng"],answer:0},{id:"dd3-quoc-ca-20",type:"mc",q:"Minh đến trường đúng lúc cả trường đang hát Quốc ca. Minh nên làm gì?",explain:"Khi Quốc ca vang lên, Minh nên dừng lại và đứng nghiêm.",options:["Chạy thật nhanh qua sân vào lớp cho kịp giờ học","Dừng lại, đứng nghiêm hướng về lá cờ đến khi hát xong","Đứng ở cổng nói chuyện với bác bảo vệ cho đến khi hát xong","Quay về nhà vì đã đến muộn mất rồi"],answer:1},{id:"dd3-quoc-ca-23",type:"order",q:"Sắp xếp các việc Vy làm khi nghe hiệu lệnh chào cờ.",explain:"Vy dừng việc, quay về phía lá cờ, đứng nghiêm rồi hát Quốc ca.",items:["Dừng ngay việc đang làm","Quay về phía lá cờ","Đứng nghiêm","Hát Quốc ca"]},{id:"dd3-quoc-ca-10",type:"order",q:"Sắp xếp các việc em làm khi chuẩn bị chào cờ.",explain:"Em xếp hàng, bỏ mũ, đứng nghiêm rồi cùng hát Quốc ca.",items:["Xếp hàng ngay ngắn","Bỏ mũ nón","Đứng nghiêm, nhìn Quốc kì","Hát Quốc ca to, rõ"]}]},summary:["Quốc ca Việt Nam là bài “Tiến quân ca” của nhạc sĩ Văn Cao.","Khi chào cờ, em đứng nghiêm, bỏ mũ nón, mắt nhìn Quốc kì.","Em hát Quốc ca to, rõ, không nói chuyện, không làm việc riêng."]},{id:"dd3-tu-hao-que-huong",title:"Tự hào quê hương, đất nước",weeks:[5,6],learn:[{title:"Đất nước Việt Nam",text:"Nước ta là nước Cộng hòa xã hội chủ nghĩa Việt Nam. Thủ đô là Hà Nội.",example:"🇻🇳 🏛️"},{title:"Cảnh đẹp, truyền thống",text:"Đất nước ta có nhiều cảnh đẹp như vịnh Hạ Long, cố đô Huế. Người Việt có truyền thống hiếu học, yêu thương, đùm bọc nhau.",example:"🏞️ 📚 🤝"},{title:"Em yêu Tổ quốc",text:"Em chăm học, giữ gìn cảnh đẹp, giới thiệu quê hương với bạn bè và biết ơn người có công với đất nước.",example:"❤️"}],practice:[{questions:[{id:"dd3-tu-hao-que-huong-01",type:"mc",q:"Thủ đô của nước Việt Nam là thành phố nào?",emoji:"🏛️",explain:"Thủ đô của nước Việt Nam là Hà Nội.",options:["Huế","Hà Nội","Đà Nẵng","Cần Thơ"],answer:1},{id:"dd3-tu-hao-que-huong-02",type:"mc",q:"Tên nước ta là gì?",explain:"Tên nước ta là Cộng hòa xã hội chủ nghĩa Việt Nam.",options:["Cộng hòa xã hội chủ nghĩa Việt Nam","Vương quốc Việt Nam thống nhất","Liên bang các vùng đất Việt Nam"],answer:0},{id:"dd3-tu-hao-que-huong-03",type:"match",q:"Nối cảnh đẹp với nơi có cảnh đẹp đó.",explain:"Vịnh Hạ Long ở Quảng Ninh, cố đô ở Huế, Văn Miếu – Quốc Tử Giám ở Hà Nội.",pairs:[["Vịnh Hạ Long","Quảng Ninh"],["Cố đô Huế","Huế"],["Văn Miếu – Quốc Tử Giám","Hà Nội"]]},{id:"dd3-tu-hao-que-huong-04",type:"tf",q:"Ngày Quốc khánh của nước ta là ngày 2 tháng 9.",explain:"Đúng rồi. Ngày 2 tháng 9 là ngày Quốc khánh nước ta.",answer:!0},{id:"dd3-tu-hao-que-huong-05",type:"tf",q:"Việt Nam chỉ có núi, không có biển.",explain:"Sai. Việt Nam có cả núi rừng, đồng bằng và bờ biển dài.",answer:!1},{id:"dd3-tu-hao-que-huong-06",type:"mc",q:"Bánh truyền thống người Việt thường gói vào dịp Tết Nguyên đán là bánh gì?",emoji:"🎍",explain:"Ngày Tết, nhiều gia đình gói bánh chưng, có nơi gói bánh tét.",options:["Bánh mì que","Bánh kem","Bánh chưng","Bánh quy bơ"],answer:2},{id:"dd3-tu-hao-que-huong-07",type:"multi",q:"Những việc làm nào thể hiện tình yêu quê hương, đất nước?",explain:"Chăm học, giữ gìn cảnh đẹp và giới thiệu quê hương là thể hiện tình yêu đất nước.",options:["Chăm chỉ học tập","Giữ gìn cảnh quan sạch đẹp","Vẽ bậy lên di tích","Giới thiệu cảnh đẹp quê mình với bạn"],answers:[0,1,3]},{id:"dd3-tu-hao-que-huong-08",type:"fill",q:"Thủ đô của nước Việt Nam là Hà …",explain:"Thủ đô của nước Việt Nam là Hà Nội.",answer:["Nội"]},{id:"dd3-tu-hao-que-huong-09",type:"tf",q:"Áo dài là trang phục truyền thống của người Việt Nam.",emoji:"👘",explain:"Đúng rồi. Áo dài là trang phục truyền thống, rất đẹp và duyên dáng.",answer:!0}]},{questions:[{id:"dd3-tu-hao-que-huong-10",type:"mc",q:"Vì sao em tự hào về đất nước Việt Nam?",explain:"Em tự hào vì đất nước có cảnh đẹp, con người cần cù và truyền thống tốt đẹp.",options:["Vì nước ta không bao giờ có mưa bão hay lũ lụt suốt cả năm","Vì nước ta là nước rộng lớn nhất trên toàn thế giới","Vì người nước ta không cần đi học mà vẫn biết hết mọi điều","Vì đất nước có cảnh đẹp, con người cần cù và nhiều truyền thống tốt"],answer:3},{id:"dd3-tu-hao-que-huong-11",type:"tf",q:"Tự hào về quê hương mình nghĩa là chê bai quê hương của các bạn khác.",explain:"Sai. Em yêu quê mình và cũng tôn trọng quê hương của các bạn.",answer:!1},{id:"dd3-tu-hao-que-huong-12",type:"multi",q:"Đâu là truyền thống tốt đẹp của người Việt Nam?",explain:"Hiếu học, yêu thương giúp đỡ nhau là truyền thống tốt đẹp.",options:["Hiếu học","Chen lấn nơi đông người","Yêu thương, giúp đỡ nhau","Vứt rác bừa bãi"],answers:[0,2]},{id:"dd3-tu-hao-que-huong-13",type:"match",q:"Nối câu tục ngữ với ý nghĩa của nó.",explain:"Mỗi câu tục ngữ dạy một điều hay: biết ơn, giúp đỡ và đoàn kết.",pairs:[["Uống nước nhớ nguồn","Biết ơn người đi trước"],["Lá lành đùm lá rách","Giúp đỡ người gặp khó khăn"],["Một cây làm chẳng nên non","Đoàn kết tạo nên sức mạnh"]]},{id:"dd3-tu-hao-que-huong-14",type:"mc",q:"Hà Nội là gì của nước ta?",explain:"Hà Nội là Thủ đô của nước Việt Nam.",options:["Thủ đô","Một hòn đảo","Một dòng sông"],answer:0},{id:"dd3-tu-hao-que-huong-15",type:"tf",q:"Giữ gìn di tích lịch sử và cảnh đẹp cũng là cách thể hiện tình yêu đất nước.",explain:"Đúng rồi. Di tích và cảnh đẹp là tài sản chung của đất nước.",answer:!0},{id:"dd3-tu-hao-que-huong-16",type:"mc",q:"Ngày 2 tháng 9 năm 1945, Chủ tịch Hồ Chí Minh đã làm gì?",explain:"Ngày 2 tháng 9 năm 1945, Bác Hồ đọc bản Tuyên ngôn Độc lập. Đó là ngày Quốc khánh.",options:["Tổ chức Tết Trung thu","Khai trương một khu vui chơi","Đọc bản Tuyên ngôn Độc lập"],answer:2},{id:"dd3-tu-hao-que-huong-17",type:"tf",q:"Chỉ người lớn mới có thể làm việc tốt cho quê hương.",explain:"Sai. Trẻ em cũng làm được nhiều việc tốt như học chăm, giữ vệ sinh, trồng cây.",answer:!1},{id:"dd3-tu-hao-que-huong-18",type:"order",q:"Sắp xếp các bước làm tấm thiệp giới thiệu cảnh đẹp quê em.",explain:"Chọn cảnh, vẽ tranh, viết lời giới thiệu rồi mới tặng bạn.",items:["Chọn cảnh đẹp muốn giới thiệu","Vẽ hoặc dán tranh cảnh đẹp","Viết vài câu giới thiệu","Tặng tấm thiệp cho bạn"]}]},{questions:[{id:"dd3-tu-hao-que-huong-19",type:"mc",q:"Bạn mới chuyển đến lớp hỏi Lan về quê hương của Lan. Lan nên làm gì?",explain:"Lan nên vui vẻ giới thiệu quê mình, đó là cách thể hiện niềm tự hào.",options:["Vui vẻ kể về cảnh đẹp và món ngon quê mình","Nói quê mình chẳng có gì hay để kể cho bạn","Không trả lời và quay sang làm việc khác","Chê quê của bạn không đẹp bằng quê mình"],answer:0},{id:"dd3-tu-hao-que-huong-20",type:"mc",q:"Đi tham quan di tích, Nam thấy một bạn định khắc tên lên tường. Nam nên làm gì?",explain:"Nam nên ngăn bạn vì khắc lên di tích làm hỏng tài sản chung của đất nước.",options:["Khắc tên mình bên cạnh tên bạn cho vui","Đứng xem bạn làm rồi đi tiếp cùng đoàn","Ngăn bạn và giải thích cần giữ gìn di tích","Chụp ảnh lại để khoe với các bạn trong lớp"],answer:2},{id:"dd3-tu-hao-que-huong-21",type:"tf",q:"Minh cùng bố mẹ trồng cây, dọn vệ sinh đường làng. Minh góp phần làm quê hương thêm đẹp.",explain:"Đúng rồi. Việc làm nhỏ của Minh giúp quê hương sạch, đẹp hơn.",answer:!0},{id:"dd3-tu-hao-que-huong-22",type:"multi",q:"Ở tuổi em, em có thể làm gì cho quê hương?",explain:"Học tốt, không xả rác, trồng cây đều là việc em làm được cho quê hương.",options:["Học tập tốt","Không xả rác nơi công cộng","Tham gia trồng cây","Bẻ cây ven đường","Khắc tên lên thân cây cổ thụ"],answers:[0,1,2]},{id:"dd3-tu-hao-que-huong-23",type:"tf",q:"Có du khách hỏi đường, Vy lịch sự chỉ đường giúp. Vy góp phần làm đẹp hình ảnh người Việt Nam.",explain:"Đúng rồi. Sự lịch sự, thân thiện của Vy khiến du khách quý mến người Việt.",answer:!0},{id:"dd3-tu-hao-que-huong-24",type:"mc",q:"Dũng thấy vài bạn bắt chước giọng nói của bạn mới đến từ vùng khác để trêu. Dũng nên làm gì?",explain:"Mỗi vùng miền có giọng nói riêng, đều đáng được tôn trọng.",options:["Cười theo các bạn cho vui vì chỉ là đùa thôi","Cùng bắt chước giọng bạn mới cho cả nhóm cười","Nhắc các bạn tôn trọng giọng nói của mọi vùng miền","Không chơi với bạn mới nữa để khỏi bị trêu lây"],answer:2},{id:"dd3-tu-hao-que-huong-25",type:"fill",q:"Câu tục ngữ “Uống nước nhớ …” nhắc em biết ơn người đi trước.",explain:"Câu tục ngữ là “Uống nước nhớ nguồn”.",answer:["nguồn"]},{id:"dd3-tu-hao-que-huong-26",type:"tf",q:"Ngọc nghĩ chỉ nơi nổi tiếng mới đáng tự hào, còn quê mình thì không. Ngọc nghĩ đúng.",explain:"Sai. Quê hương nào cũng có điều đẹp, điều quý đáng tự hào.",answer:!1},{id:"dd3-tu-hao-que-huong-27",type:"match",q:"Nối việc làm với điều mà việc làm đó thể hiện.",explain:"Mỗi việc làm tốt đều thể hiện tình yêu quê hương, đất nước.",pairs:[["Thăm nghĩa trang liệt sĩ","Biết ơn người có công"],["Hát Quốc ca nghiêm trang","Kính trọng Tổ quốc"],["Nhặt rác ở bãi biển","Giữ gìn cảnh đẹp"]]}]}],challenge:{questions:[{id:"dd3-tu-hao-que-huong-28",type:"mc",q:"Lớp em tổ chức “Ngày hội quê em”. Cách nào tốt nhất để giới thiệu quê mình?",explain:"Giới thiệu bằng tranh ảnh và lời kể chân thật giúp các bạn hiểu và yêu quê em.",options:["Nói thật to rằng quê mình hơn hẳn mọi nơi khác","Không tham gia vì ngại phải nói trước cả lớp","Dùng tranh ảnh, kể về cảnh đẹp, món ăn, con người quê mình","Nhờ một bạn khác lên nói hộ, còn mình chỉ ngồi nghe"],answer:2},{id:"dd3-tu-hao-que-huong-29",type:"multi",q:"Những việc nào KHÔNG nên làm khi đi tham quan cảnh đẹp?",explain:"Vứt rác, bẻ cành, viết bậy làm hỏng cảnh đẹp. Em đi đúng lối và giữ vệ sinh.",options:["Vứt rác xuống hồ","Bẻ cành, hái hoa","Đi đúng lối đi","Viết bậy lên đá"],answers:[0,1,3]},{id:"dd3-tu-hao-que-huong-30",type:"tf",q:"Chăm học hôm nay là chuẩn bị để mai sau góp sức xây dựng đất nước.",explain:"Đúng rồi. Học tốt là cách em chuẩn bị để xây dựng quê hương.",answer:!0},{id:"dd3-tu-hao-que-huong-20",type:"mc",q:"Đi tham quan di tích, Nam thấy một bạn định khắc tên lên tường. Nam nên làm gì?",explain:"Nam nên ngăn bạn vì khắc lên di tích làm hỏng tài sản chung của đất nước.",options:["Khắc tên mình bên cạnh tên bạn cho vui","Đứng xem bạn làm rồi đi tiếp cùng đoàn","Ngăn bạn và giải thích cần giữ gìn di tích","Chụp ảnh lại để khoe với các bạn trong lớp"],answer:2},{id:"dd3-tu-hao-que-huong-24",type:"mc",q:"Dũng thấy vài bạn bắt chước giọng nói của bạn mới đến từ vùng khác để trêu. Dũng nên làm gì?",explain:"Mỗi vùng miền có giọng nói riêng, đều đáng được tôn trọng.",options:["Cười theo các bạn cho vui vì chỉ là đùa thôi","Cùng bắt chước giọng bạn mới cho cả nhóm cười","Nhắc các bạn tôn trọng giọng nói của mọi vùng miền","Không chơi với bạn mới nữa để khỏi bị trêu lây"],answer:2},{id:"dd3-tu-hao-que-huong-13",type:"match",q:"Nối câu tục ngữ với ý nghĩa của nó.",explain:"Mỗi câu tục ngữ dạy một điều hay: biết ơn, giúp đỡ và đoàn kết.",pairs:[["Uống nước nhớ nguồn","Biết ơn người đi trước"],["Lá lành đùm lá rách","Giúp đỡ người gặp khó khăn"],["Một cây làm chẳng nên non","Đoàn kết tạo nên sức mạnh"]]}]},summary:["Việt Nam có nhiều cảnh đẹp, con người cần cù và truyền thống tốt đẹp.","Em tự hào về quê hương và tôn trọng quê hương của người khác.","Em chăm học, giữ gìn cảnh đẹp và biết ơn người có công với đất nước."]}]},{id:"hang-xom",title:"Quan tâm hàng xóm láng giềng",lessons:[{id:"dd3-quan-tam-hang-xom",title:"Vì sao cần quan tâm hàng xóm?",weeks:[7,8],learn:[{title:"Hàng xóm láng giềng",text:"Hàng xóm láng giềng là những người sống gần nhà em.",example:"🏘️"},{title:"Vì sao cần quan tâm?",text:"Quan tâm, giúp đỡ nhau làm tình làng nghĩa xóm thêm gắn bó. Khi có việc gấp, hàng xóm có thể giúp nhau ngay.",example:"Bán anh em xa, mua láng giềng gần."},{title:"Biểu hiện quan tâm",text:"Em chào hỏi lễ phép, hỏi thăm khi hàng xóm ốm, giúp việc vừa sức, giữ yên lặng vào giờ nghỉ.",example:"🙋 🤝 🤫"}],practice:[{questions:[{id:"dd3-quan-tam-hang-xom-01",type:"mc",q:"Hàng xóm láng giềng là ai?",emoji:"🏘️",explain:"Hàng xóm láng giềng là những người sống gần nhà em.",options:["Những người sống ở nước ngoài","Những người sống gần nhà em","Những người ở thành phố khác"],answer:1},{id:"dd3-quan-tam-hang-xom-02",type:"tf",q:"Gặp bác hàng xóm, em lễ phép chào hỏi.",explain:"Đúng rồi. Chào hỏi lễ phép là cách đơn giản nhất để quan tâm hàng xóm.",answer:!0},{id:"dd3-quan-tam-hang-xom-03",type:"multi",q:"Việc làm nào thể hiện sự quan tâm hàng xóm?",explain:"Chào hỏi, hỏi thăm là quan tâm hàng xóm. Mở nhạc to buổi trưa, trêu chó nhà bên là làm phiền mọi người.",options:["Chào hỏi lễ phép","Hỏi thăm khi hàng xóm bị ốm","Mở nhạc thật to buổi trưa","Trêu chó nhà hàng xóm cho nó sủa"],answers:[0,1]},{id:"dd3-quan-tam-hang-xom-04",type:"tf",q:"Bật nhạc thật to vào buổi trưa là quan tâm đến hàng xóm.",explain:"Sai. Buổi trưa mọi người nghỉ ngơi, bật nhạc to sẽ làm phiền hàng xóm.",answer:!1},{id:"dd3-quan-tam-hang-xom-05",type:"fill",q:"Hoàn thành câu tục ngữ: “Bán anh em xa, mua láng giềng …”.",explain:"Câu tục ngữ là “Bán anh em xa, mua láng giềng gần”.",answer:["gần"]},{id:"dd3-quan-tam-hang-xom-06",type:"mc",q:"Câu “Bán anh em xa, mua láng giềng gần” khuyên em điều gì?",explain:"Câu tục ngữ nói hàng xóm ở gần có thể giúp nhau lúc cần, nên rất đáng quý.",options:["Hàng xóm gần gũi rất quý, cần giữ tình thân","Nên bán nhà ở đây để chuyển đến nơi thật xa","Không cần quan tâm đến anh em trong nhà","Chỉ nên chơi với những người ở thật xa"],answer:0},{id:"dd3-quan-tam-hang-xom-07",type:"tf",q:"Khi hàng xóm có chuyện buồn, em có thể cùng bố mẹ hỏi thăm, động viên.",explain:"Đúng rồi. Lời hỏi thăm giúp hàng xóm thấy ấm lòng hơn.",answer:!0},{id:"dd3-quan-tam-hang-xom-08",type:"mc",q:"Khi đi qua nhà hàng xóm vào giờ nghỉ trưa, em nên làm gì?",explain:"Đi nhẹ, nói khẽ để hàng xóm được nghỉ ngơi.",options:["Hò hét thật to","Đập cửa nhà hàng xóm cho vui","Đi nhẹ, nói khẽ","Ném sỏi vào cổng"],answer:2},{id:"dd3-quan-tam-hang-xom-09",type:"tf",q:"Hàng xóm không phải người thân nên không cần quan tâm.",explain:"Sai. Hàng xóm sống gần nhau, cần quan tâm và giúp đỡ nhau.",answer:!1}]},{questions:[{id:"dd3-quan-tam-hang-xom-10",type:"mc",q:"Vì sao cần quan tâm, giúp đỡ hàng xóm?",explain:"Quan tâm nhau giúp xóm làng gắn bó, khi khó khăn có người giúp đỡ.",options:["Để được hàng xóm cho thật nhiều quà và bánh kẹo","Để tình làng nghĩa xóm gắn bó, giúp nhau lúc khó khăn","Để được lên ti vi và được mọi người khen ngợi","Vì sợ hàng xóm giận mình rồi không chơi với mình"],answer:1},{id:"dd3-quan-tam-hang-xom-11",type:"tf",q:"Quan tâm hàng xóm làm cho khu phố, xóm làng thêm thân thiện.",explain:"Đúng rồi. Mọi người quan tâm nhau thì nơi ở thêm vui và ấm áp.",answer:!0},{id:"dd3-quan-tam-hang-xom-12",type:"match",q:"Nối tình huống với việc làm quan tâm phù hợp.",explain:"Mỗi tình huống, em chọn việc vừa sức và nhờ người lớn khi cần.",pairs:[["Bà hàng xóm bị ốm","Cùng bố mẹ sang hỏi thăm"],["Trời sắp mưa, nhà bên đi vắng","Báo bố mẹ giúp cất quần áo phơi"],["Em bé nhà bên ngã","Đỡ em dậy và báo người lớn"]]},{id:"dd3-quan-tam-hang-xom-13",type:"multi",q:"Những việc nào làm phiền hàng xóm?",explain:"Gây ồn, vứt rác, chắn lối đi đều làm phiền hàng xóm.",options:["Hát thật to lúc đêm khuya","Vứt rác trước cửa nhà hàng xóm","Chào hỏi khi gặp","Để xe chắn lối đi nhà hàng xóm"],answers:[0,1,3]},{id:"dd3-quan-tam-hang-xom-14",type:"tf",q:"Chỉ khi hàng xóm nhờ thì em mới cần giúp đỡ.",explain:"Sai. Thấy hàng xóm cần giúp, em có thể chủ động giúp việc vừa sức hoặc báo bố mẹ.",answer:!1},{id:"dd3-quan-tam-hang-xom-15",type:"mc",q:"Bạn nào biết quan tâm hàng xóm?",explain:"An giúp hàng xóm việc vừa sức. Các bạn còn lại làm phiền hàng xóm.",options:["Bình đá bóng trúng vào cửa sổ nhà bên","Chi trèo tường sang hái trộm ổi nhà hàng xóm","An giúp bác hàng xóm tưới cây khi bác nhờ","Dũng ném vỏ bánh kẹo sang sân nhà bên"],answer:2},{id:"dd3-quan-tam-hang-xom-16",type:"tf",q:"Quan tâm hàng xóm còn giúp em nhận lại tình cảm quý mến của mọi người.",explain:"Đúng rồi. Khi em quan tâm mọi người, mọi người cũng quý mến em.",answer:!0},{id:"dd3-quan-tam-hang-xom-17",type:"order",q:"Sắp xếp các việc em làm khi cùng mẹ sang thăm bà hàng xóm bị ốm.",explain:"Gõ cửa chào hỏi, hỏi thăm, chúc bà mau khỏe rồi chào ra về.",items:["Gõ cửa và chào bà","Hỏi thăm sức khỏe của bà","Chúc bà mau khỏe","Chào bà ra về"]},{id:"dd3-quan-tam-hang-xom-18",type:"mc",q:"Em có thể làm gì để quan tâm cụ già sống một mình cạnh nhà?",explain:"Hỏi thăm, trò chuyện giúp cụ bớt buồn, thấy được quan tâm.",options:["Sang nhà cụ chơi đùa ồn ào suốt cả buổi","Cùng bố mẹ sang hỏi thăm, trò chuyện với cụ","Không chào hỏi cụ vì mình không quen cụ","Trêu con chó nhà cụ qua hàng rào cho vui"],answer:1}]},{questions:[{id:"dd3-quan-tam-hang-xom-19",type:"mc",q:"Bé Na nhà bên khóc vì quả bóng rơi xuống rãnh nước sâu. Em nên làm gì?",explain:"Rãnh nước sâu rất nguy hiểm. Em gọi người lớn giúp là vừa quan tâm vừa an toàn.",options:["Tự trèo xuống rãnh nước sâu để lấy","Đứng cười vì thấy bé Na khóc","Gọi người lớn đến giúp lấy bóng","Bỏ đi chỗ khác vì không phải bóng của mình"],answer:2},{id:"dd3-quan-tam-hang-xom-20",type:"mc",q:"Trời sắp mưa, nhà hàng xóm đi vắng mà quần áo còn phơi ngoài sân. Hà nên làm gì?",explain:"Hà báo bố mẹ để giúp hàng xóm là biết quan tâm.",options:["Báo bố mẹ để giúp cất quần áo cho hàng xóm","Mặc kệ vì đó không phải là quần áo nhà mình","Đóng cửa nhà mình lại rồi đi ngủ trưa","Đứng ở cửa sổ xem mưa rơi ướt quần áo"],answer:0},{id:"dd3-quan-tam-hang-xom-21",type:"tf",q:"Nhà bác Tư có người ốm cần yên tĩnh, nhưng Khoa vẫn la hét trước cổng nhà bác. Khoa làm đúng.",explain:"Sai. Khoa nên giữ yên lặng để người ốm được nghỉ ngơi.",answer:!1},{id:"dd3-quan-tam-hang-xom-22",type:"multi",q:"Nhà hàng xóm có em bé mới sinh. Em nên làm gì?",explain:"Em giữ yên lặng, cùng bố mẹ chúc mừng và không tự ý bế em bé.",options:["Giữ yên lặng để em bé ngủ","Cùng bố mẹ sang chúc mừng","Bật loa thật to","Không tự ý bế em bé","Đứng ngoài cổng gọi to tên em bé"],answers:[0,1,3]},{id:"dd3-quan-tam-hang-xom-23",type:"order",q:"Thấy bà hàng xóm xách nhiều đồ, Nam nên làm theo thứ tự nào?",explain:"Chào hỏi, hỏi ý bà, giúp việc vừa sức rồi chào ra về.",items:["Chào bà lễ phép","Hỏi bà có cần giúp không","Giúp bà xách đồ nhẹ về nhà","Chào bà rồi về"]},{id:"dd3-quan-tam-hang-xom-24",type:"tf",q:"Lan rủ các bạn trong xóm cùng quét dọn ngõ xóm vào cuối tuần. Lan làm việc tốt.",explain:"Đúng rồi. Ngõ xóm sạch đẹp thì mọi nhà đều vui.",answer:!0},{id:"dd3-quan-tam-hang-xom-25",type:"mc",q:"Bạn hàng xóm cùng tuổi bị ốm phải nghỉ học. Em có thể làm gì?",explain:"Hỏi thăm và giúp bạn theo kịp bài là cách quan tâm thiết thực.",options:["Khoe với bạn là mình được đi chơi","Hỏi thăm và cho bạn mượn vở chép bài","Không hỏi han gì","Nói với cả lớp là bạn lười"],answer:1},{id:"dd3-quan-tam-hang-xom-26",type:"tf",q:"Ngọc nhặt được chìa khóa trước cửa nhà hàng xóm và giữ lại làm đồ chơi. Ngọc làm đúng.",explain:"Sai. Ngọc nên trả lại chìa khóa cho hàng xóm hoặc nhờ bố mẹ trả giúp.",answer:!1},{id:"dd3-quan-tam-hang-xom-27",type:"match",q:"Nối câu nói với tình huống phù hợp.",explain:"Mỗi tình huống cần một lời nói lễ phép, phù hợp.",pairs:[["Cháu chào bác ạ!","Gặp bác hàng xóm"],["Bà đã đỡ mệt chưa ạ?","Bà hàng xóm bị ốm"],["Cháu cảm ơn cô ạ!","Cô hàng xóm cho quà"]]}]}],challenge:{questions:[{id:"dd3-quan-tam-hang-xom-28",type:"mc",q:"Nhà Phúc và nhà bác Hai vừa có chút hiểu lầm. Gặp bác ngoài ngõ, Phúc nên làm gì?",explain:"Dù có hiểu lầm, Phúc vẫn lễ phép chào hỏi. Chuyện của người lớn để người lớn giải quyết.",options:["Vẫn lễ phép chào bác","Quay mặt đi","Nói xấu bác với bạn","Lè lưỡi trêu bác"],answer:0},{id:"dd3-quan-tam-hang-xom-29",type:"multi",q:"Những câu nói nào thể hiện sự quan tâm hàng xóm?",explain:"Lời hỏi thăm, lời chào lễ phép thể hiện sự quan tâm hàng xóm.",options:["“Bác có cần cháu giúp gì không ạ?”","“Ông đã khỏe hơn chưa ạ?”","“Ồn quá, đi chỗ khác đi!”","“Cháu chào cô ạ!”"],answers:[0,1,3]},{id:"dd3-quan-tam-hang-xom-30",type:"tf",q:"Quan tâm hàng xóm là việc của người lớn, trẻ em không làm được.",explain:"Sai. Trẻ em cũng làm được nhiều việc như chào hỏi, giữ yên lặng, giúp việc vừa sức.",answer:!1},{id:"dd3-quan-tam-hang-xom-19",type:"mc",q:"Bé Na nhà bên khóc vì quả bóng rơi xuống rãnh nước sâu. Em nên làm gì?",explain:"Rãnh nước sâu rất nguy hiểm. Em gọi người lớn giúp là vừa quan tâm vừa an toàn.",options:["Tự trèo xuống rãnh nước sâu để lấy","Đứng cười vì thấy bé Na khóc","Gọi người lớn đến giúp lấy bóng","Bỏ đi chỗ khác vì không phải bóng của mình"],answer:2},{id:"dd3-quan-tam-hang-xom-22",type:"multi",q:"Nhà hàng xóm có em bé mới sinh. Em nên làm gì?",explain:"Em giữ yên lặng, cùng bố mẹ chúc mừng và không tự ý bế em bé.",options:["Giữ yên lặng để em bé ngủ","Cùng bố mẹ sang chúc mừng","Bật loa thật to","Không tự ý bế em bé","Đứng ngoài cổng gọi to tên em bé"],answers:[0,1,3]},{id:"dd3-quan-tam-hang-xom-12",type:"match",q:"Nối tình huống với việc làm quan tâm phù hợp.",explain:"Mỗi tình huống, em chọn việc vừa sức và nhờ người lớn khi cần.",pairs:[["Bà hàng xóm bị ốm","Cùng bố mẹ sang hỏi thăm"],["Trời sắp mưa, nhà bên đi vắng","Báo bố mẹ giúp cất quần áo phơi"],["Em bé nhà bên ngã","Đỡ em dậy và báo người lớn"]]}]},summary:["Hàng xóm láng giềng là những người sống gần nhà em.","Quan tâm, giúp đỡ hàng xóm làm tình làng nghĩa xóm thêm gắn bó.","Em chào hỏi, hỏi thăm, giúp việc vừa sức và không làm phiền hàng xóm."]},{id:"dd3-tinh-lang-nghia-xom",title:"Tình làng nghĩa xóm",weeks:[9,10],learn:[{title:"Việc em làm được",text:"Em chào hỏi, giúp việc vừa sức, giữ ngõ xóm sạch đẹp, chơi hòa thuận với các bạn trong xóm.",example:"🧹 🌼"},{title:"Lịch sự với hàng xóm",text:"Muốn vào nhà hàng xóm, em gõ cửa, chào hỏi và chỉ vào khi được mời. Mượn đồ thì giữ gìn và trả đúng hẹn.",example:"🚪 🙏"},{title:"Giữ an toàn",text:"Gặp việc quá sức như cháy, có người ngã đau, em tránh xa chỗ nguy hiểm và gọi người lớn ngay.",example:"📞 114"}],practice:[{questions:[{id:"dd3-tinh-lang-nghia-xom-01",type:"tf",q:"Muốn vào nhà hàng xóm, em gõ cửa, chào hỏi và chờ được mời vào.",emoji:"🚪",explain:"Đúng rồi. Như vậy là lịch sự, tôn trọng hàng xóm.",answer:!0},{id:"dd3-tinh-lang-nghia-xom-02",type:"tf",q:"Em có thể tự ý hái quả trong vườn nhà hàng xóm.",explain:"Sai. Muốn lấy thứ gì của hàng xóm, em phải xin phép.",answer:!1},{id:"dd3-tinh-lang-nghia-xom-03",type:"mc",q:"Mượn đồ của hàng xóm, em cần làm gì?",explain:"Giữ gìn và trả đúng hẹn để hàng xóm tin tưởng em.",options:["Dùng xong thì vứt đi, không cần trả","Giữ luôn ở nhà mình, không trả lại","Giữ gìn cẩn thận và trả đúng hẹn","Cho bạn khác mượn tiếp mà không hỏi"],answer:2},{id:"dd3-tinh-lang-nghia-xom-04",type:"multi",q:"Việc nào giúp ngõ xóm sạch đẹp?",explain:"Bỏ rác đúng chỗ và cùng quét dọn giúp ngõ xóm sạch đẹp.",options:["Bỏ rác đúng nơi quy định","Cùng mọi người quét dọn ngõ xóm","Vứt vỏ bánh ra đường","Đổ nước bẩn ra ngõ"],answers:[0,1]},{id:"dd3-tinh-lang-nghia-xom-05",type:"mc",q:"Thấy khói bốc ra từ nhà hàng xóm đang đi vắng, em nên làm gì?",explain:"Em báo ngay người lớn để kịp xử lí. Không tự chạy vào vì rất nguy hiểm.",options:["Báo ngay cho người lớn","Đứng xem","Một mình chạy vào nhà dập lửa","Đi chỗ khác chơi"],answer:0},{id:"dd3-tinh-lang-nghia-xom-06",type:"fill",q:"Hàng xóm sống gần nhau, giúp đỡ nhau, gọi là tình làng nghĩa …",explain:"Ta gọi đó là tình làng nghĩa xóm.",answer:["xóm"]},{id:"dd3-tinh-lang-nghia-xom-07",type:"tf",q:"Được hàng xóm cho quà, em nói lời cảm ơn.",explain:"Đúng rồi. Nói lời cảm ơn là lễ phép, biết ơn.",answer:!0},{id:"dd3-tinh-lang-nghia-xom-08",type:"mc",q:"Lời chào nào phù hợp khi gặp ông hàng xóm buổi sáng?",explain:"Em chào người lớn tuổi bằng lời lễ phép: “Cháu chào ông ạ!”.",options:["Ê, ông ơi!","Chào nhé, đi đâu đấy?","Ông tránh ra cho cháu đi!","Cháu chào ông ạ!"],answer:3},{id:"dd3-tinh-lang-nghia-xom-09",type:"tf",q:"Gặp hàng xóm lớn tuổi mà không quen thân thì em không cần chào.",explain:"Sai. Gặp người lớn tuổi trong xóm, em vẫn lễ phép chào hỏi.",answer:!1}]},{questions:[{id:"dd3-tinh-lang-nghia-xom-10",type:"match",q:"Nối việc làm với lí do nên làm.",explain:"Mỗi việc làm nhỏ đều giúp hàng xóm sống vui vẻ, thoải mái.",pairs:[["Đi nhẹ, nói khẽ buổi trưa","Để hàng xóm được nghỉ ngơi"],["Trả đồ mượn đúng hẹn","Để giữ lòng tin"],["Bỏ rác đúng chỗ","Để ngõ xóm sạch đẹp"]]},{id:"dd3-tinh-lang-nghia-xom-11",type:"tf",q:"Mượn chiếc thang của nhà bên, Tùng dùng xong để ở sân nhà mình cả tuần. Tùng làm đúng.",explain:"Sai. Dùng xong, Tùng nên trả ngay và cảm ơn hàng xóm.",answer:!1},{id:"dd3-tinh-lang-nghia-xom-12",type:"mc",q:"Vì sao không nên tự ý vào nhà hàng xóm khi chưa được mời?",explain:"Tự ý vào nhà người khác là thiếu lịch sự. Em gõ cửa và chờ được mời.",options:["Vì như vậy là thiếu lịch sự","Vì nhà hàng xóm luôn khóa cửa","Vì đi lại rất mệt"],answer:0},{id:"dd3-tinh-lang-nghia-xom-13",type:"multi",q:"Những bạn nào cư xử chưa đúng với hàng xóm?",explain:"Trèo tường và bấm chuông trêu đều thiếu tôn trọng hàng xóm.",options:["Bình trèo tường sang nhặt bóng khi nhà bên vắng chủ","Chi chào cô hàng xóm","Dũng bấm chuông nhà bên rồi bỏ chạy để trêu","Vy cảm ơn khi được bác cho quả"],answers:[0,2]},{id:"dd3-tinh-lang-nghia-xom-14",type:"tf",q:"Chỉ những việc giúp đỡ thật lớn mới thể hiện sự quan tâm hàng xóm.",explain:"Sai. Việc nhỏ như chào hỏi, hỏi thăm cũng thể hiện sự quan tâm.",answer:!1},{id:"dd3-tinh-lang-nghia-xom-15",type:"mc",q:"Câu nào nói đúng về tình làng nghĩa xóm?",explain:"Khi hàng xóm quan tâm, giúp đỡ nhau, cuộc sống vui vẻ và an toàn hơn.",options:["Hàng xóm gặp nhau không cần chào hỏi gì cả","Nhà ai nấy biết, không cần để ý nhà bên là tốt nhất","Hàng xóm chỉ cần gặp nhau vào ngày Tết","Hàng xóm biết giúp nhau thì cuộc sống vui hơn"],answer:3},{id:"dd3-tinh-lang-nghia-xom-16",type:"order",q:"Sắp xếp các bước mượn đồ của hàng xóm cho lịch sự.",explain:"Chào hỏi, nói rõ, cảm ơn rồi giữ gìn và trả đúng hẹn.",items:["Chào hỏi người hàng xóm","Nói rõ muốn mượn đồ gì","Cảm ơn khi được cho mượn","Giữ gìn và trả đúng hẹn"]},{id:"dd3-tinh-lang-nghia-xom-17",type:"tf",q:"Ngày Tết, Hà cùng bố mẹ sang chúc Tết hàng xóm. Hà làm đúng.",explain:"Đúng rồi. Chúc Tết là nét đẹp của tình làng nghĩa xóm.",answer:!0},{id:"dd3-tinh-lang-nghia-xom-18",type:"mc",q:"Vì sao khi thấy cháy hay có người bị thương, em cần gọi người lớn?",explain:"Việc quá sức em cần người lớn giúp để mọi người được an toàn.",options:["Vì em không muốn giúp đỡ bất kì ai","Vì muốn được đứng gần xem cho thật rõ","Vì người lớn xử lí được an toàn hơn","Vì sợ bị bố mẹ mắng nếu tự làm"],answer:2}]},{questions:[{id:"dd3-tinh-lang-nghia-xom-19",type:"mc",q:"Cô hàng xóm nhờ An cho mèo ăn hai ngày khi cô đi vắng, An đã nhận lời. An nên làm gì?",explain:"An đã nhận lời thì cần làm đến nơi đến chốn.",options:["Chỉ cho ăn một lần","Quên luôn","Nhờ bạn làm rồi không kiểm tra","Cho mèo ăn đều đặn như đã hứa"],answer:3},{id:"dd3-tinh-lang-nghia-xom-20",type:"tf",q:"Thấy ông hàng xóm bị ngã ngoài ngõ, Nam chạy đi gọi người lớn đến giúp. Nam làm đúng.",explain:"Đúng rồi. Gọi người lớn giúp ông kịp thời là việc làm tốt.",answer:!0},{id:"dd3-tinh-lang-nghia-xom-21",type:"mc",q:"Quả bóng của Khoa bay sang sân nhà hàng xóm. Khoa nên làm gì?",explain:"Khoa xin phép lịch sự, không trèo tường vì vừa nguy hiểm vừa thiếu tôn trọng.",options:["Trèo qua tường sang sân nhà bên để lấy","Đá vào cổng thật mạnh để chủ nhà ra mở cổng","Bấm chuông, chào hỏi và xin phép vào lấy","Bỏ luôn quả bóng, không lấy lại nữa"],answer:2},{id:"dd3-tinh-lang-nghia-xom-22",type:"multi",q:"Xóm em dọn vệ sinh ngày Chủ nhật. Em có thể góp sức bằng cách nào?",explain:"Em góp sức bằng việc vừa sức và rủ các bạn cùng tham gia.",options:["Nhặt rác nhỏ ven đường","Mang chổi nhỏ đi cùng","Rủ các bạn cùng tham gia","Ngủ nướng ở nhà"],answers:[0,1,2]},{id:"dd3-tinh-lang-nghia-xom-23",type:"tf",q:"Chó nhà Thảo hay sủa đêm làm hàng xóm mất ngủ, Thảo cho rằng đó không phải việc của mình. Thảo nghĩ đúng.",explain:"Sai. Thảo nên cùng bố mẹ tìm cách để không làm phiền hàng xóm.",answer:!1},{id:"dd3-tinh-lang-nghia-xom-24",type:"mc",q:"Bà hàng xóm nghe không rõ. Khi nói chuyện với bà, em nên làm gì?",explain:"Nói chậm, rõ, lễ phép giúp bà nghe được và thấy được tôn trọng.",options:["Hét thật to vào tai bà","Nói chậm, rõ ràng và lễ phép","Không nói chuyện với bà nữa","Trêu bà vì bà nghe không rõ"],answer:1},{id:"dd3-tinh-lang-nghia-xom-25",type:"match",q:"Nối tình huống với cách xử lí đúng.",explain:"Em trung thực, giữ lời và nhờ bố mẹ khi cần.",pairs:[["Làm vỡ chậu hoa nhà bên","Xin lỗi và báo bố mẹ"],["Nhận lời tưới cây giúp hàng xóm","Tưới đều như đã hứa"],["Cổng nhà bên mở toang lúc vắng chủ","Báo bố mẹ để báo hàng xóm"]]},{id:"dd3-tinh-lang-nghia-xom-26",type:"fill",q:"Mượn đồ của hàng xóm thì phải trả đúng …",explain:"Mượn đồ thì trả đúng hẹn.",answer:["hẹn","hạn"]},{id:"dd3-tinh-lang-nghia-xom-27",type:"tf",q:"Ngọc mời các bạn nhỏ trong xóm cùng chơi trò chơi dân gian. Ngọc giúp xóm thêm gắn bó.",explain:"Đúng rồi. Vui chơi cùng nhau giúp các bạn trong xóm thân thiết hơn.",answer:!0}]}],challenge:{questions:[{id:"dd3-tinh-lang-nghia-xom-28",type:"mc",q:"Gia đình Bình sắp sửa nhà nên sẽ có tiếng ồn. Cách nào thể hiện sự quan tâm hàng xóm?",explain:"Báo trước và tránh giờ nghỉ là biết nghĩ cho hàng xóm.",options:["Làm ồn vào bất cứ giờ nào, kể cả buổi tối","Báo trước cho hàng xóm và tránh làm ồn giờ nghỉ","Để gạch cát chắn ngang lối đi chung của xóm","Không cần nói gì vì đó là nhà của mình"],answer:1},{id:"dd3-tinh-lang-nghia-xom-29",type:"multi",q:"Những việc nào thể hiện sự lịch sự với hàng xóm?",explain:"Gõ cửa, trả đồ đúng hẹn, cảm ơn là lịch sự. Tự ý lấy đồ là sai.",options:["Gõ cửa trước khi vào","Trả đồ mượn đúng hẹn","Tự ý lấy đồ nhà bên","Cảm ơn khi được giúp đỡ"],answers:[0,1,3]},{id:"dd3-tinh-lang-nghia-xom-30",type:"order",q:"Thấy khói bốc ra từ nhà hàng xóm, em làm theo thứ tự nào?",explain:"Em tránh xa nguy hiểm trước, báo người lớn, rồi cùng người lớn gọi 114.",items:["Tránh xa chỗ có khói","Gọi to báo người lớn gần nhất","Cùng người lớn gọi số cứu hỏa 114"]},{id:"dd3-tinh-lang-nghia-xom-19",type:"mc",q:"Cô hàng xóm nhờ An cho mèo ăn hai ngày khi cô đi vắng, An đã nhận lời. An nên làm gì?",explain:"An đã nhận lời thì cần làm đến nơi đến chốn.",options:["Chỉ cho ăn một lần","Quên luôn","Nhờ bạn làm rồi không kiểm tra","Cho mèo ăn đều đặn như đã hứa"],answer:3},{id:"dd3-tinh-lang-nghia-xom-25",type:"match",q:"Nối tình huống với cách xử lí đúng.",explain:"Em trung thực, giữ lời và nhờ bố mẹ khi cần.",pairs:[["Làm vỡ chậu hoa nhà bên","Xin lỗi và báo bố mẹ"],["Nhận lời tưới cây giúp hàng xóm","Tưới đều như đã hứa"],["Cổng nhà bên mở toang lúc vắng chủ","Báo bố mẹ để báo hàng xóm"]]},{id:"dd3-tinh-lang-nghia-xom-16",type:"order",q:"Sắp xếp các bước mượn đồ của hàng xóm cho lịch sự.",explain:"Chào hỏi, nói rõ, cảm ơn rồi giữ gìn và trả đúng hẹn.",items:["Chào hỏi người hàng xóm","Nói rõ muốn mượn đồ gì","Cảm ơn khi được cho mượn","Giữ gìn và trả đúng hẹn"]}]},summary:["Em lịch sự với hàng xóm: gõ cửa, chào hỏi, cảm ơn, trả đồ đúng hẹn.","Em giữ ngõ xóm sạch đẹp và không làm phiền hàng xóm.","Gặp việc quá sức, em tránh xa nguy hiểm và gọi người lớn."]}]},{id:"ham-hoc-hoi",title:"Ham học hỏi",lessons:[{id:"dd3-ham-hoc-hoi",title:"Thế nào là ham học hỏi?",weeks:[11,12],learn:[{title:"Ham học hỏi là gì?",text:"Ham học hỏi là luôn muốn biết thêm điều mới, chăm đọc sách, hay đặt câu hỏi và tìm câu trả lời.",example:"📚 ❓"},{title:"Lợi ích",text:"Ham học hỏi giúp em hiểu biết nhiều hơn, học tốt hơn và làm được nhiều việc có ích.",example:"💡"},{title:"Học ở mọi nơi",text:"Em học ở trường, học từ sách báo, từ thầy cô, bố mẹ, bạn bè và cuộc sống quanh em.",example:"Đi một ngày đàng, học một sàng khôn."}],practice:[{questions:[{id:"dd3-ham-hoc-hoi-01",type:"mc",q:"Biểu hiện nào cho thấy một bạn ham học hỏi?",emoji:"🙋",explain:"Bạn ham học hỏi mạnh dạn đặt câu hỏi khi chưa hiểu.",options:["Ngại hỏi dù chưa hiểu bài","Chỉ thích chơi điện tử cả ngày","Hay ngủ gật trong giờ học","Hay đặt câu hỏi khi chưa hiểu"],answer:3},{id:"dd3-ham-hoc-hoi-02",type:"tf",q:"Ham học hỏi là luôn muốn tìm hiểu điều mới.",explain:"Đúng rồi. Người ham học hỏi luôn tò mò, muốn biết thêm.",answer:!0},{id:"dd3-ham-hoc-hoi-03",type:"multi",q:"Đâu là biểu hiện của người ham học hỏi?",explain:"Đọc sách, hỏi khi chưa hiểu, tìm hiểu xung quanh là ham học hỏi.",options:["Chăm đọc sách","Hỏi thầy cô khi chưa hiểu","Tìm hiểu thế giới xung quanh","Lười suy nghĩ"],answers:[0,1,2]},{id:"dd3-ham-hoc-hoi-04",type:"tf",q:"Em chỉ có thể học ở trường, không học được ở nơi nào khác.",explain:"Sai. Em có thể học ở nhà, ở thư viện, từ sách báo và cuộc sống quanh em.",answer:!1},{id:"dd3-ham-hoc-hoi-05",type:"mc",q:"Em có thể học hỏi từ ai?",explain:"Ai cũng có điều hay để em học hỏi.",options:["Chỉ học từ thầy cô ở trường, không học thêm từ ai khác","Chỉ học từ bạn thân nhất của mình trong lớp","Không cần học từ ai, tự mình biết hết mọi thứ","Từ thầy cô, bố mẹ, bạn bè và mọi người xung quanh"],answer:3},{id:"dd3-ham-hoc-hoi-06",type:"fill",q:"Hoàn thành câu tục ngữ: “Đi một ngày đàng, học một sàng …”.",explain:"Câu tục ngữ là “Đi một ngày đàng, học một sàng khôn”.",answer:["khôn"]},{id:"dd3-ham-hoc-hoi-07",type:"tf",q:"Nam chưa hiểu bài nhưng không hỏi vì sợ các bạn cười. Như vậy là ham học hỏi.",explain:"Sai. Ham học hỏi là mạnh dạn hỏi khi chưa hiểu.",answer:!1},{id:"dd3-ham-hoc-hoi-08",type:"mc",q:"Ham học hỏi mang lại điều gì cho em?",explain:"Ham học hỏi giúp em hiểu biết nhiều hơn và tiến bộ.",options:["Làm em mất bạn","Làm em mệt và học kém đi","Giúp em hiểu biết nhiều hơn","Không có ích gì"],answer:2},{id:"dd3-ham-hoc-hoi-09",type:"tf",q:"Đọc sách là một cách học hỏi rất tốt.",emoji:"📖",explain:"Đúng rồi. Sách mở ra cho em nhiều điều mới lạ.",answer:!0}]},{questions:[{id:"dd3-ham-hoc-hoi-10",type:"match",q:"Nối việc làm với điều em học được.",explain:"Mỗi việc làm đều giúp em học thêm điều mới.",pairs:[["Đọc truyện","Biết thêm nhiều từ ngữ hay"],["Tham quan bảo tàng","Hiểu thêm về lịch sử"],["Phụ mẹ nấu cơm","Biết làm việc nhà"]]},{id:"dd3-ham-hoc-hoi-11",type:"tf",q:"Người ham học hỏi không bao giờ mắc lỗi.",explain:"Sai. Ai cũng có lúc mắc lỗi. Người ham học hỏi biết học từ lỗi sai.",answer:!1},{id:"dd3-ham-hoc-hoi-12",type:"mc",q:"Vì sao cần ham học hỏi?",explain:"Ham học hỏi giúp em hiểu biết thêm và tiến bộ mỗi ngày.",options:["Để khoe với bạn bè rằng mình giỏi nhất lớp","Để sau này không phải đi học nữa","Để được bố mẹ mua thật nhiều đồ chơi","Để hiểu biết thêm và tiến bộ mỗi ngày"],answer:3},{id:"dd3-ham-hoc-hoi-13",type:"multi",q:"Những bạn nào ham học hỏi?",explain:"Lan và Chi chủ động tìm hiểu điều mới, đó là ham học hỏi.",options:["Lan hỏi bà cách gói bánh chưng","Bình chép bài của bạn","Chi tìm đọc sách về các loài chim","Dũng ngủ trong giờ học"],answers:[0,2]},{id:"dd3-ham-hoc-hoi-14",type:"tf",q:"Hỏi lại khi chưa hiểu bài là việc đáng xấu hổ.",explain:"Sai. Hỏi khi chưa hiểu là việc tốt, giúp em học tốt hơn.",answer:!1},{id:"dd3-ham-hoc-hoi-15",type:"mc",q:"Câu “Học thầy không tày học bạn” khuyên em điều gì?",explain:"Câu tục ngữ khuyên em học hỏi cả từ bạn bè quanh mình.",options:["Không cần học thầy cô nữa, chỉ cần học bạn","Chỉ nên học một mình ở nhà cho yên tĩnh","Có thể học được nhiều điều hay từ bạn bè","Không nên chơi với bạn để tập trung học"],answer:2},{id:"dd3-ham-hoc-hoi-16",type:"order",q:"Sắp xếp các bước khi gặp một từ mới em chưa hiểu.",explain:"Đọc kĩ, đoán nghĩa, kiểm tra lại rồi tập dùng từ mới.",items:["Đọc kĩ câu có từ đó","Thử đoán nghĩa của từ","Hỏi người lớn hoặc tra từ điển","Dùng từ đó để đặt câu"]},{id:"dd3-ham-hoc-hoi-17",type:"tf",q:"Học hỏi từ những người làm nghề quanh em, như bác nông dân, cô bán hàng, cũng rất bổ ích.",explain:"Đúng rồi. Mỗi nghề đều có nhiều điều hay để em học.",answer:!0},{id:"dd3-ham-hoc-hoi-18",type:"mc",q:"Trái với ham học hỏi là gì?",explain:"Lười học, ngại tìm hiểu là trái với ham học hỏi.",options:["Chăm chỉ đọc sách","Lười học, ngại tìm hiểu","Thích đặt câu hỏi","Hay tìm hiểu điều mới"],answer:1}]},{questions:[{id:"dd3-ham-hoc-hoi-19",type:"mc",q:"Trong giờ Toán, Minh chưa hiểu cách làm bài. Minh nên làm gì?",explain:"Minh nên giơ tay hỏi cô để hiểu bài.",options:["Ngồi im cho qua","Chép bài của bạn","Giơ tay hỏi cô giáo","Bỏ bài đó không làm"],answer:2},{id:"dd3-ham-hoc-hoi-20",type:"mc",q:"Đi công viên, Thảo thấy một loài hoa lạ. Thảo nên làm gì để biết tên hoa?",explain:"Hỏi người lớn hoặc đọc biển tên là cách tìm hiểu đúng, không làm hại cây.",options:["Hỏi bố mẹ hoặc đọc biển ghi tên cây","Hái một bông hoa mang về nhà để hỏi","Không cần quan tâm, đi chơi chỗ khác","Giẫm lên bông hoa cho vui rồi đi tiếp"],answer:0},{id:"dd3-ham-hoc-hoi-21",type:"tf",q:"Khoa đọc xong sách thì kể lại cho em gái nghe những điều hay. Khoa vừa học vừa biết chia sẻ.",explain:"Đúng rồi. Kể lại giúp Khoa nhớ lâu và em gái cũng biết thêm.",answer:!0},{id:"dd3-ham-hoc-hoi-22",type:"multi",q:"Vy muốn biết thêm về cá heo. Vy có thể làm gì?",explain:"Đọc sách, hỏi thầy cô, xem chương trình khoa học đều giúp Vy hiểu thêm.",options:["Đọc sách về các loài vật biển","Hỏi thầy cô","Cùng bố mẹ xem chương trình khoa học","Đoán bừa rồi thôi","Tự ra biển tìm cá heo một mình"],answers:[0,1,2]},{id:"dd3-ham-hoc-hoi-23",type:"tf",q:"Dũng nghĩ mình đã giỏi nên không cần học thêm. Dũng nghĩ đúng.",explain:"Sai. Dù giỏi đến đâu, mỗi ngày vẫn có điều mới để học.",answer:!1},{id:"dd3-ham-hoc-hoi-24",type:"mc",q:"Bạn cùng bàn giải được bài khó bằng một cách hay. Em nên làm gì?",explain:"Học hỏi cách hay của bạn giúp em tiến bộ.",options:["Nhờ bạn chỉ cách làm để học hỏi","Ghen tị vì bạn giỏi hơn mình","Nói với lớp là bạn chép bài","Không thèm nghe"],answer:0},{id:"dd3-ham-hoc-hoi-25",type:"order",q:"Sắp xếp các bước tìm hiểu một điều em thắc mắc.",explain:"Biết rõ mình muốn hỏi gì, tìm câu trả lời, ghi lại rồi chia sẻ.",items:["Nêu rõ điều em muốn biết","Tìm sách hoặc hỏi người hiểu biết","Ghi lại câu trả lời","Kể lại cho bạn bè nghe"]},{id:"dd3-ham-hoc-hoi-26",type:"fill",q:"Người luôn muốn biết thêm điều mới là người ham học …",explain:"Đó là người ham học hỏi.",answer:["hỏi"]},{id:"dd3-ham-hoc-hoi-27",type:"match",q:"Nối điều em muốn biết với người em có thể hỏi.",explain:"Mỗi người làm nghề hiểu rõ công việc của mình, em có thể hỏi họ.",pairs:[["Cách phòng bệnh","Bác sĩ"],["Cách trồng lúa","Bác nông dân"],["Cách giải bài toán","Thầy cô giáo"]]}]}],challenge:{questions:[{id:"dd3-ham-hoc-hoi-28",type:"mc",q:"Bình hay hỏi trong giờ học nhưng có bạn chê Bình “hỏi nhiều quá”. Bình nên làm gì?",explain:"Hỏi để hiểu bài là việc tốt. Bình chỉ cần hỏi đúng lúc và lịch sự.",options:["Vẫn hỏi đúng lúc những điều mình chưa hiểu","Không bao giờ hỏi nữa cho bạn khỏi chê","Cãi nhau với bạn đó","Bỏ học"],answer:0},{id:"dd3-ham-hoc-hoi-29",type:"tf",q:"Người ham học hỏi biết học từ cả những lần mình làm sai.",explain:"Đúng rồi. Mỗi lỗi sai giúp em biết thêm cách làm đúng.",answer:!0},{id:"dd3-ham-hoc-hoi-30",type:"multi",q:"Đâu là cách học hỏi ngoài giờ lên lớp?",explain:"Đọc sách ở thư viện, nghe ông bà kể chuyện giúp em học thêm nhiều điều.",options:["Đọc sách ở thư viện","Nằm xem ti vi đến khuya","Hỏi ông bà về chuyện ngày xưa","Xem điện thoại suốt ngày"],answers:[0,2]},{id:"dd3-ham-hoc-hoi-19",type:"mc",q:"Trong giờ Toán, Minh chưa hiểu cách làm bài. Minh nên làm gì?",explain:"Minh nên giơ tay hỏi cô để hiểu bài.",options:["Ngồi im cho qua","Chép bài của bạn","Giơ tay hỏi cô giáo","Bỏ bài đó không làm"],answer:2},{id:"dd3-ham-hoc-hoi-27",type:"match",q:"Nối điều em muốn biết với người em có thể hỏi.",explain:"Mỗi người làm nghề hiểu rõ công việc của mình, em có thể hỏi họ.",pairs:[["Cách phòng bệnh","Bác sĩ"],["Cách trồng lúa","Bác nông dân"],["Cách giải bài toán","Thầy cô giáo"]]},{id:"dd3-ham-hoc-hoi-16",type:"order",q:"Sắp xếp các bước khi gặp một từ mới em chưa hiểu.",explain:"Đọc kĩ, đoán nghĩa, kiểm tra lại rồi tập dùng từ mới.",items:["Đọc kĩ câu có từ đó","Thử đoán nghĩa của từ","Hỏi người lớn hoặc tra từ điển","Dùng từ đó để đặt câu"]}]},summary:["Ham học hỏi là luôn muốn biết thêm điều mới.","Em học từ sách báo, thầy cô, bố mẹ, bạn bè và cuộc sống.","Ham học hỏi giúp em hiểu biết nhiều hơn và tiến bộ mỗi ngày."]},{id:"dd3-ren-ham-hoc",title:"Rèn luyện tính ham học hỏi",weeks:[13,14],learn:[{title:"Cách rèn luyện",text:"Em đặt câu hỏi khi chưa hiểu, đọc sách mỗi ngày, ghi lại điều mới học được và chăm luyện tập.",example:"📖 ✏️"},{title:"Hỏi lịch sự",text:"Khi hỏi, em giơ tay hoặc chờ đến lượt, nói lễ phép và lắng nghe câu trả lời, rồi cảm ơn.",example:"🙋 🙏"},{title:"Không ngại khó",text:"Gặp bài khó, em kiên trì suy nghĩ, thử nhiều cách và nhờ giúp đỡ khi cần.",example:"🧩 💪"}],practice:[{questions:[{id:"dd3-ren-ham-hoc-01",type:"tf",q:"Đọc sách mỗi ngày giúp em hiểu biết thêm.",emoji:"📚",explain:"Đúng rồi. Đọc sách đều đặn là thói quen của người ham học hỏi.",answer:!0},{id:"dd3-ren-ham-hoc-02",type:"mc",q:"Muốn hỏi cô giáo trong giờ học, em làm thế nào?",explain:"Em giơ tay xin phép và chờ cô mời.",options:["Nói to khi cô đang giảng","Chạy lên bàn cô","Gọi bạn thật to","Giơ tay xin phép"],answer:3},{id:"dd3-ren-ham-hoc-03",type:"multi",q:"Đâu là cách rèn tính ham học hỏi?",explain:"Ghi chép và đặt câu hỏi giúp em ham học hỏi hơn. Em không bỏ cuộc, không ngại hỏi.",options:["Ghi lại điều mới học được","Đặt câu hỏi khi chưa hiểu","Bỏ cuộc khi gặp bài khó","Ngại hỏi vì sợ bạn cười"],answers:[0,1]},{id:"dd3-ren-ham-hoc-04",type:"tf",q:"Gặp bài khó, em nên bỏ qua ngay.",explain:"Sai. Em kiên trì suy nghĩ, thử cách khác hoặc nhờ giúp đỡ.",answer:!1},{id:"dd3-ren-ham-hoc-05",type:"mc",q:"Khi được giải đáp thắc mắc, em nên nói gì?",explain:"Em cảm ơn người đã giúp mình hiểu bài.",options:["Thế thôi à?","Biết rồi!","Em cảm ơn ạ!","Không nói gì"],answer:2},{id:"dd3-ren-ham-hoc-06",type:"fill",q:"Gặp bài khó, em không nản mà … trì suy nghĩ.",explain:"Em kiên trì suy nghĩ, không nản lòng.",answer:["kiên"]},{id:"dd3-ren-ham-hoc-07",type:"tf",q:"Lắng nghe người khác nói là một cách học hỏi.",explain:"Đúng rồi. Chăm chú lắng nghe giúp em biết thêm nhiều điều.",answer:!0},{id:"dd3-ren-ham-hoc-08",type:"mc",q:"Đâu là thói quen tốt của người ham học hỏi?",explain:"Đọc sách đều đặn là thói quen tốt giúp em ham học hỏi.",options:["Xem ti vi đến tận khuya mỗi tối","Có góc đọc sách và đọc đều đặn","Để sách vở lộn xộn khắp nơi","Chỉ học bài khi sắp kiểm tra"],answer:1},{id:"dd3-ren-ham-hoc-09",type:"tf",q:"Chỉ cần học trên lớp, về nhà không cần tìm hiểu thêm gì.",explain:"Sai. Ở nhà em vẫn có thể đọc sách, hỏi bố mẹ và tìm hiểu thêm.",answer:!1}]},{questions:[{id:"dd3-ren-ham-hoc-10",type:"order",q:"Sắp xếp cách em đặt câu hỏi với cô giáo trong giờ học.",explain:"Giơ tay, chờ cô mời, nói rõ điều chưa hiểu rồi lắng nghe và cảm ơn.",items:["Giơ tay xin phép","Đứng lên khi cô mời","Nói rõ điều chưa hiểu","Lắng nghe và cảm ơn cô"]},{id:"dd3-ren-ham-hoc-11",type:"mc",q:"Vì sao nên ghi lại điều mới học được?",explain:"Ghi lại giúp em nhớ lâu và ôn lại dễ dàng.",options:["Để quyển vở trông dày hơn","Để nhớ lâu và xem lại khi cần","Để khoe với bạn là mình chăm","Để khỏi phải nghe cô giảng bài"],answer:1},{id:"dd3-ren-ham-hoc-12",type:"tf",q:"Hỏi bài bạn trong lúc đang làm bài kiểm tra là ham học hỏi.",explain:"Sai. Khi kiểm tra, em tự làm bài. Chưa hiểu thì hỏi sau giờ kiểm tra.",answer:!1},{id:"dd3-ren-ham-hoc-13",type:"match",q:"Nối khó khăn với cách vượt qua.",explain:"Mỗi khó khăn đều có cách vượt qua nếu em chịu tìm hiểu.",pairs:[["Chưa hiểu bài","Hỏi thầy cô, bạn bè"],["Quên kiến thức cũ","Ôn lại vở ghi"],["Không biết nghĩa của từ","Tra từ điển"]]},{id:"dd3-ren-ham-hoc-14",type:"multi",q:"Những bạn nào hỏi lịch sự?",explain:"An và Chi hỏi lễ phép, nhẹ nhàng. Hỏi lịch sự giúp em được giúp đỡ vui vẻ.",options:["An: “Thưa cô, em chưa hiểu bài này ạ.”","Bình: “Ê, chỉ bài này mau lên!”","Chi: “Bạn chỉ giúp mình được không?”","Dũng giật vở của bạn để xem"],answers:[0,2]},{id:"dd3-ren-ham-hoc-15",type:"tf",q:"Kiên trì luyện tập giúp em tiến bộ dần mỗi ngày.",explain:"Đúng rồi. Mỗi ngày một chút, em sẽ tiến bộ.",answer:!0},{id:"dd3-ren-ham-hoc-16",type:"mc",q:"Khi bạn giảng bài cho mình, em nên làm gì?",explain:"Chăm chú lắng nghe là tôn trọng bạn và giúp em hiểu bài.",options:["Ngắt lời bạn liên tục","Làm việc riêng","Chăm chú lắng nghe","Cười chê bạn"],answer:2},{id:"dd3-ren-ham-hoc-17",type:"tf",q:"Muốn ham học hỏi thì phải biết hết mọi thứ ngay lập tức.",explain:"Sai. Học hỏi là cả một quá trình, mỗi ngày em biết thêm một ít.",answer:!1},{id:"dd3-ren-ham-hoc-18",type:"mc",q:"Hà muốn đọc nhiều sách hơn. Cách nào hợp lí?",explain:"Đọc đều đặn mỗi ngày giúp Hà hình thành thói quen tốt.",options:["Mỗi ngày dành một ít thời gian để đọc","Đọc một lúc thật nhiều rồi thôi hẳn","Chỉ đọc khi bị nhắc","Mua sách rồi cất đi"],answer:0}]},{questions:[{id:"dd3-ren-ham-hoc-19",type:"mc",q:"Lan muốn biết cách trồng rau trong chậu. Cách làm nào tốt nhất?",explain:"Hỏi, đọc, làm thử và ghi lại giúp Lan học được thật sự.",options:["Đoán bừa cách trồng rồi bỏ","Hỏi bà, đọc sách rồi thử trồng và ghi lại","Nhờ bạn trồng hộ rồi nhận là của mình","Không làm gì cả"],answer:1},{id:"dd3-ren-ham-hoc-20",type:"tf",q:"Thấy bạn mới vào lớp vẽ đẹp, Phúc xin bạn chỉ cho cách vẽ. Phúc làm đúng.",explain:"Đúng rồi. Phúc biết học hỏi từ bạn bè.",answer:!0},{id:"dd3-ren-ham-hoc-21",type:"mc",q:"Bài tập về nhà khó, Nam đã thử nhiều cách mà chưa ra. Nam nên làm gì?",explain:"Nhờ gợi ý rồi tự làm giúp Nam hiểu bài thật sự.",options:["Nhờ bố mẹ gợi ý rồi tự làm tiếp","Chép đáp án có sẵn cho nhanh","Bỏ trống bài và không hỏi ai","Xé trang vở"],answer:0},{id:"dd3-ren-ham-hoc-22",type:"multi",q:"Tùng muốn tìm hiểu về các hành tinh. Tùng nên làm gì?",explain:"Đọc sách, hỏi thầy cô và ghi chép giúp Tùng tìm hiểu tốt.",options:["Mượn sách ở thư viện","Hỏi thầy cô giáo","Ghi lại điều thú vị đã học","Chép bài của bạn"],answers:[0,1,2]},{id:"dd3-ren-ham-hoc-23",type:"order",q:"Sắp xếp các bước Vy làm sổ tay “Điều em học được”.",explain:"Chuẩn bị sổ, ghi mỗi ngày, đọc lại và chia sẻ.",items:["Chuẩn bị một cuốn sổ nhỏ","Mỗi ngày ghi lại một điều mới","Thỉnh thoảng đọc lại sổ","Chia sẻ điều hay với bạn bè"]},{id:"dd3-ren-ham-hoc-24",type:"tf",q:"Ngọc ngại hỏi cô vì sợ cô nghĩ mình kém, nên đành bỏ qua phần chưa hiểu. Ngọc làm đúng.",explain:"Sai. Ngọc nên mạnh dạn hỏi, cô luôn sẵn lòng giúp học sinh.",answer:!1},{id:"dd3-ren-ham-hoc-25",type:"mc",q:"Ông kể chuyện ngày xưa cho Khoa nghe. Khoa nên làm gì?",explain:"Chăm chú nghe và hỏi thêm giúp Khoa biết nhiều điều quý từ ông.",options:["Chăm chú nghe và hỏi thêm điều mình thích","Bỏ đi chơi với bạn vì chuyện ngày xưa","Bảo ông thôi kể để mình đi xem ti vi","Vừa nghe ông kể vừa chơi điện thoại"],answer:0},{id:"dd3-ren-ham-hoc-26",type:"fill",q:"Gặp từ khó, em có thể tra từ … để biết nghĩa.",explain:"Em tra từ điển để biết nghĩa của từ.",answer:["điển"]},{id:"dd3-ren-ham-hoc-27",type:"match",q:"Nối việc làm với thói quen tốt của người ham học.",explain:"Chăm đọc, mạnh dạn hỏi, kiên trì sửa lỗi là thói quen tốt.",pairs:[["Đọc sách mỗi tối","Chăm đọc"],["Giơ tay hỏi bài","Mạnh dạn hỏi"],["Làm lại bài sai","Kiên trì sửa lỗi"]]}]}],challenge:{questions:[{id:"dd3-ren-ham-hoc-28",type:"mc",q:"Thảo mê đọc truyện, đọc đến khuya nên sáng ra mệt mỏi. Thảo nên làm gì?",explain:"Ham đọc là tốt, nhưng Thảo cần đọc đúng giờ và ngủ đủ giấc.",options:["Đọc thâu đêm cho hết cả bộ truyện","Bỏ hẳn việc đọc truyện từ nay","Mang truyện đến lớp đọc lén trong giờ học","Đọc vào giờ hợp lí và ngủ đủ giấc"],answer:3},{id:"dd3-ren-ham-hoc-29",type:"tf",q:"Biết vận dụng điều đã học vào cuộc sống giúp em nhớ lâu và hiểu sâu hơn.",explain:"Đúng rồi. Học đi đôi với hành giúp em hiểu sâu hơn.",answer:!0},{id:"dd3-ren-ham-hoc-30",type:"multi",q:"Những câu nào nói đúng về người ham học hỏi?",explain:"Người ham học hỏi mạnh dạn, kiên trì và biết học từ lỗi sai.",options:["Mạnh dạn hỏi khi chưa hiểu","Kiên trì khi gặp bài khó","Ngại thử điều mới","Biết học từ lỗi sai"],answers:[0,1,3]},{id:"dd3-ren-ham-hoc-19",type:"mc",q:"Lan muốn biết cách trồng rau trong chậu. Cách làm nào tốt nhất?",explain:"Hỏi, đọc, làm thử và ghi lại giúp Lan học được thật sự.",options:["Đoán bừa cách trồng rồi bỏ","Hỏi bà, đọc sách rồi thử trồng và ghi lại","Nhờ bạn trồng hộ rồi nhận là của mình","Không làm gì cả"],answer:1},{id:"dd3-ren-ham-hoc-23",type:"order",q:"Sắp xếp các bước Vy làm sổ tay “Điều em học được”.",explain:"Chuẩn bị sổ, ghi mỗi ngày, đọc lại và chia sẻ.",items:["Chuẩn bị một cuốn sổ nhỏ","Mỗi ngày ghi lại một điều mới","Thỉnh thoảng đọc lại sổ","Chia sẻ điều hay với bạn bè"]},{id:"dd3-ren-ham-hoc-13",type:"match",q:"Nối khó khăn với cách vượt qua.",explain:"Mỗi khó khăn đều có cách vượt qua nếu em chịu tìm hiểu.",pairs:[["Chưa hiểu bài","Hỏi thầy cô, bạn bè"],["Quên kiến thức cũ","Ôn lại vở ghi"],["Không biết nghĩa của từ","Tra từ điển"]]}]},summary:["Em rèn tính ham học hỏi bằng cách đọc sách, đặt câu hỏi và ghi lại điều mới.","Khi hỏi, em lễ phép, lắng nghe và cảm ơn.","Gặp bài khó, em kiên trì và nhờ giúp đỡ khi cần."]}]},{id:"giu-loi-hua",title:"Giữ lời hứa",lessons:[{id:"dd3-giu-loi-hua",title:"Vì sao phải giữ lời hứa?",weeks:[15,16],learn:[{title:"Giữ lời hứa là gì?",text:"Giữ lời hứa là làm đúng điều mình đã hứa với người khác hoặc với chính mình.",example:"🤝"},{title:"Vì sao phải giữ lời hứa?",text:"Người giữ lời hứa được mọi người tin tưởng, quý mến. Thất hứa làm người khác buồn và mất lòng tin.",example:"Lời nói phải đi đôi với việc làm."},{title:"Chuyện chiếc vòng bạc",text:"Chuyện kể Bác Hồ hứa tặng một em bé chiếc vòng bạc. Lâu sau trở lại, Bác vẫn nhớ và mang vòng đến tặng em.",example:"💍"},{title:"Hứa điều làm được",text:"Trước khi hứa, em suy nghĩ xem mình có làm được không. Em chỉ hứa những điều đúng đắn và vừa sức.",example:"🤔"}],practice:[{questions:[{id:"dd3-giu-loi-hua-01",type:"mc",q:"Giữ lời hứa là gì?",emoji:"🤝",explain:"Giữ lời hứa là làm đúng điều mình đã hứa.",options:["Làm đúng điều mình đã hứa","Hứa thật nhiều điều với mọi người","Hứa xong rồi để đó, không làm","Chỉ hứa với những bạn thân"],answer:0},{id:"dd3-giu-loi-hua-02",type:"tf",q:"Người biết giữ lời hứa được mọi người tin tưởng.",explain:"Đúng rồi. Giữ lời hứa giúp em được mọi người tin tưởng, quý mến.",answer:!0},{id:"dd3-giu-loi-hua-03",type:"tf",q:"Hứa xong mà quên cũng không sao.",explain:"Sai. Quên lời hứa làm người khác buồn và mất lòng tin.",answer:!1},{id:"dd3-giu-loi-hua-04",type:"multi",q:"Những bạn nào giữ lời hứa?",explain:"An và Chi làm đúng điều đã hứa. Bình và Dũng đã thất hứa.",options:["An hứa trả truyện vào thứ Hai và trả đúng hẹn","Bình hứa đến sinh nhật bạn nhưng đi chơi chỗ khác","Chi hứa tự dọn giường mỗi sáng và làm đều đặn","Dũng hứa giữ bí mật cho bạn rồi kể với cả lớp"],answers:[0,2]},{id:"dd3-giu-loi-hua-05",type:"fill",q:"Lời nói phải đi đôi với việc …",explain:"Câu đó là “Lời nói phải đi đôi với việc làm”.",answer:["làm"]},{id:"dd3-giu-loi-hua-06",type:"mc",q:"Khi em không giữ lời hứa, người khác sẽ thế nào?",explain:"Thất hứa làm người khác buồn và không còn tin em.",options:["Vui hơn vì không phải chờ em","Buồn và mất lòng tin vào em","Tin em hơn trước rất nhiều","Không cảm thấy gì cả"],answer:1},{id:"dd3-giu-loi-hua-07",type:"tf",q:"Trước khi hứa, em nên suy nghĩ xem mình có làm được không.",explain:"Đúng rồi. Suy nghĩ kĩ giúp em chỉ hứa điều mình làm được.",answer:!0},{id:"dd3-giu-loi-hua-08",type:"mc",q:"Trong chuyện “Chiếc vòng bạc”, Bác Hồ đã làm gì?",explain:"Dù bận nhiều việc, Bác vẫn nhớ và giữ đúng lời hứa với em bé.",options:["Quên mất lời hứa với em bé vì quá bận","Nhờ người khác hứa thay mình với em bé","Không hứa gì với em bé khi chia tay","Giữ đúng lời hứa tặng em bé chiếc vòng bạc"],answer:3},{id:"dd3-giu-loi-hua-09",type:"tf",q:"Chỉ cần giữ lời hứa với người lớn, hứa với em nhỏ thì không cần giữ.",explain:"Sai. Hứa với ai, em cũng cần giữ lời.",answer:!1}]},{questions:[{id:"dd3-giu-loi-hua-10",type:"mc",q:"Vì sao phải giữ lời hứa?",explain:"Giữ lời hứa giúp em được tin tưởng và quý mến.",options:["Để được bố mẹ thưởng quà thật to","Để sau đó không phải làm gì nữa","Để được mọi người tin tưởng, quý mến","Vì sợ bị thầy cô phạt nếu mình thất hứa"],answer:2},{id:"dd3-giu-loi-hua-11",type:"match",q:"Nối lời hứa với việc làm giữ lời.",explain:"Giữ lời hứa là làm đúng điều đã hứa.",pairs:[["Hứa trả sách cho bạn ngày mai","Hôm sau mang sách đi trả"],["Hứa học bài xong mới xem ti vi","Học bài xong mới bật ti vi"],["Hứa giúp em tập đọc","Ngồi kèm em đọc bài"]]},{id:"dd3-giu-loi-hua-12",type:"tf",q:"Hứa những điều mình không làm được là việc làm đúng.",explain:"Sai. Em chỉ nên hứa những điều mình làm được.",answer:!1},{id:"dd3-giu-loi-hua-13",type:"multi",q:"Câu nào nói đúng về người hay thất hứa?",explain:"Hay thất hứa làm mất lòng tin, làm người khác buồn và hỏng việc chung.",options:["Mọi người dần không tin","Làm người khác buồn","Được mọi người quý mến hơn","Có thể làm hỏng việc chung"],answers:[0,1,3]},{id:"dd3-giu-loi-hua-14",type:"mc",q:"Lời hứa nào em KHÔNG nên hứa?",explain:"Việc nguy hiểm cần báo người lớn, em không hứa giấu chuyện đó.",options:["Hứa với mẹ sẽ đi học đúng giờ mỗi ngày","Hứa giúp bạn ôn bài trước giờ kiểm tra","Hứa giấu chuyện bạn làm việc nguy hiểm","Hứa giữ gìn cẩn thận quyển sách mượn"],answer:2},{id:"dd3-giu-loi-hua-15",type:"tf",q:"Giữ lời hứa là tôn trọng người khác và tôn trọng chính mình.",explain:"Đúng rồi. Người giữ lời hứa là người đáng tin cậy.",answer:!0},{id:"dd3-giu-loi-hua-16",type:"order",q:"Sắp xếp các bước để hứa và giữ lời hứa.",explain:"Suy nghĩ trước, hứa rõ ràng, ghi nhớ rồi làm đúng.",items:["Suy nghĩ xem mình có làm được không","Nói lời hứa rõ ràng","Ghi nhớ lời hứa","Thực hiện đúng lời hứa"]},{id:"dd3-giu-loi-hua-17",type:"mc",q:"Câu nào khuyên em giữ lời hứa?",explain:"Nói được thì làm được, đó là giữ lời hứa.",options:["Ăn quả nhớ kẻ trồng cây","Lời nói phải đi đôi với việc làm","Có công mài sắt có ngày nên kim","Uống nước nhớ nguồn"],answer:1},{id:"dd3-giu-loi-hua-18",type:"tf",q:"Thất hứa một lần thì không ảnh hưởng gì đến lòng tin của mọi người.",explain:"Sai. Dù một lần, thất hứa cũng làm người khác bớt tin em.",answer:!1}]},{questions:[{id:"dd3-giu-loi-hua-19",type:"mc",q:"Minh hứa ôn bài cùng Nam lúc 3 giờ chiều, nhưng có bạn rủ đi đá bóng. Minh nên làm gì?",explain:"Minh đã hứa với Nam thì cần giữ lời, có thể đi đá bóng vào dịp khác.",options:["Đi đá bóng, không báo Nam","Nói dối Nam là bị ốm","Trốn ở nhà không gặp ai","Giữ lời hẹn ôn bài với Nam"],answer:3},{id:"dd3-giu-loi-hua-20",type:"tf",q:"Hà hứa với cô sẽ mang tranh vẽ quê hương đến lớp. Hà vẽ xong từ tối hôm trước và mang đến đúng hẹn. Hà biết giữ lời hứa.",explain:"Đúng rồi. Hà chuẩn bị sớm nên giữ được lời hứa.",answer:!0},{id:"dd3-giu-loi-hua-21",type:"multi",q:"Lan hay quên lời hứa. Lan có thể làm gì để nhớ?",explain:"Ghi chép và nhờ người thân nhắc giúp Lan nhớ và giữ lời hứa.",options:["Ghi lời hứa vào sổ tay","Nhờ người thân nhắc","Hứa rồi để đó tính sau","Hứa thật nhiều hơn"],answers:[0,1]},{id:"dd3-giu-loi-hua-22",type:"mc",q:"Vy nhờ Tùng giữ bí mật chuyện Vy sợ bóng tối và Tùng đã hứa. Tùng nên làm gì?",explain:"Đây là chuyện riêng không nguy hiểm, Tùng giữ kín là giữ lời hứa và tôn trọng bạn.",options:["Kể cho cả lớp nghe","Lấy chuyện đó trêu Vy","Kể cho vài bạn thân","Giữ kín, không kể với ai"],answer:3},{id:"dd3-giu-loi-hua-23",type:"tf",q:"Ngọc hứa chơi với em sau khi làm bài, nhưng rồi lại ngồi xem ti vi. Ngọc giữ đúng lời hứa.",explain:"Sai. Ngọc đã thất hứa, làm em buồn.",answer:!1},{id:"dd3-giu-loi-hua-24",type:"order",q:"Phúc hứa trả truyện cho bạn vào ngày mai. Sắp xếp việc Phúc nên làm.",explain:"Chuẩn bị từ tối giúp Phúc không quên và trả đúng hẹn.",items:["Đọc xong truyện trong hôm nay","Cất truyện vào cặp từ tối","Mang truyện đến lớp","Trả truyện và cảm ơn bạn"]},{id:"dd3-giu-loi-hua-25",type:"mc",q:"Dũng hứa với mẹ đi ngủ trước 9 giờ tối, nhưng phim hay chưa hết. Dũng nên làm gì?",explain:"Dũng giữ lời hứa với mẹ và ngủ đủ giấc. Phim có thể xem vào hôm khác.",options:["Xem tiếp cho hết phim rồi mới ngủ","Xem lén khi mẹ đã ngủ","Tắt ti vi đi ngủ đúng giờ như đã hứa","Cãi lại mẹ"],answer:2},{id:"dd3-giu-loi-hua-26",type:"fill",q:"Người làm đúng điều mình đã hứa là người biết giữ lời …",explain:"Đó là người biết giữ lời hứa.",answer:["hứa"]},{id:"dd3-giu-loi-hua-27",type:"tf",q:"Thảo chỉ hứa những điều mình làm được, nên Thảo luôn giữ được lời hứa. Thảo đáng khen.",explain:"Đúng rồi. Hứa điều làm được là bí quyết để giữ lời hứa.",answer:!0}]}],challenge:{questions:[{id:"dd3-giu-loi-hua-28",type:"mc",q:"Bình lỡ hứa sẽ cho bạn chép bài trong giờ kiểm tra. Bình nên làm gì?",explain:"Lời hứa làm điều sai thì không nên thực hiện. Bình giúp bạn ôn bài là tốt nhất.",options:["Cho bạn chép bài vì mình đã lỡ hứa rồi","Không làm điều sai, giải thích và giúp bạn ôn bài","Tránh mặt bạn suốt cả buổi kiểm tra","Nói dối với bạn là mình đã quên mất lời hứa"],answer:1},{id:"dd3-giu-loi-hua-29",type:"tf",q:"Lời hứa làm điều sai trái thì không nên thực hiện.",explain:"Đúng rồi. Em không làm điều sai, dù đã lỡ hứa.",answer:!0},{id:"dd3-giu-loi-hua-30",type:"multi",q:"Những câu nói nào thể hiện ý thức giữ lời hứa?",explain:"Người giữ lời hứa coi trọng lời mình nói và làm đúng hẹn.",options:["“Mình đã hứa thì mình sẽ làm.”","“Hứa cho vui thôi mà.”","“Mình sẽ trả đúng hẹn.”","“Để lúc nào rảnh tính sau.”"],answers:[0,2]},{id:"dd3-giu-loi-hua-19",type:"mc",q:"Minh hứa ôn bài cùng Nam lúc 3 giờ chiều, nhưng có bạn rủ đi đá bóng. Minh nên làm gì?",explain:"Minh đã hứa với Nam thì cần giữ lời, có thể đi đá bóng vào dịp khác.",options:["Đi đá bóng, không báo Nam","Nói dối Nam là bị ốm","Trốn ở nhà không gặp ai","Giữ lời hẹn ôn bài với Nam"],answer:3},{id:"dd3-giu-loi-hua-22",type:"mc",q:"Vy nhờ Tùng giữ bí mật chuyện Vy sợ bóng tối và Tùng đã hứa. Tùng nên làm gì?",explain:"Đây là chuyện riêng không nguy hiểm, Tùng giữ kín là giữ lời hứa và tôn trọng bạn.",options:["Kể cho cả lớp nghe","Lấy chuyện đó trêu Vy","Kể cho vài bạn thân","Giữ kín, không kể với ai"],answer:3},{id:"dd3-giu-loi-hua-14",type:"mc",q:"Lời hứa nào em KHÔNG nên hứa?",explain:"Việc nguy hiểm cần báo người lớn, em không hứa giấu chuyện đó.",options:["Hứa với mẹ sẽ đi học đúng giờ mỗi ngày","Hứa giúp bạn ôn bài trước giờ kiểm tra","Hứa giấu chuyện bạn làm việc nguy hiểm","Hứa giữ gìn cẩn thận quyển sách mượn"],answer:2}]},summary:["Giữ lời hứa là làm đúng điều mình đã hứa.","Người giữ lời hứa được mọi người tin tưởng, quý mến.","Em suy nghĩ kĩ và chỉ hứa những điều đúng đắn, vừa sức."]},{id:"dd3-khi-chua-giu-duoc-hua",title:"Khi chưa thể giữ lời hứa",weeks:[17,18],learn:[{title:"Khi có việc bất ngờ",text:"Nếu có việc bất ngờ khiến em không giữ được lời hứa, em báo ngay cho người đó, xin lỗi và hẹn lại.",example:"📞"},{title:"Sửa lỗi khi thất hứa",text:"Nếu em quên lời hứa, em thật thà nhận lỗi, xin lỗi và cố gắng làm bù.",example:"🙏"},{title:"Không hứa điều sai",text:"Em không hứa làm điều sai trái hoặc nguy hiểm. Lời hứa như thế không nên thực hiện.",example:"🚫"}],practice:[{questions:[{id:"dd3-khi-chua-giu-duoc-hua-01",type:"mc",q:"Có việc bất ngờ, không thể giữ lời hẹn, em nên làm gì?",emoji:"📞",explain:"Báo sớm, xin lỗi và hẹn lại là cách cư xử đúng.",options:["Im lặng, không nói gì với người đó cả","Nói dối một lí do nào đó cho qua chuyện","Báo cho người đó, xin lỗi và hẹn lại","Trốn tránh, không gặp người đó nữa"],answer:2},{id:"dd3-khi-chua-giu-duoc-hua-02",type:"tf",q:"Khi quên lời hứa, em thật thà nhận lỗi và xin lỗi.",explain:"Đúng rồi. Thật thà nhận lỗi giúp em giữ được lòng tin.",answer:!0},{id:"dd3-khi-chua-giu-duoc-hua-03",type:"tf",q:"Thất hứa rồi thì cứ im lặng, không cần xin lỗi.",explain:"Sai. Em cần xin lỗi và tìm cách sửa lỗi.",answer:!1},{id:"dd3-khi-chua-giu-duoc-hua-04",type:"multi",q:"Lí do nào là chính đáng khi không thể đến buổi hẹn?",explain:"Ốm, việc gấp, mưa bão là lí do chính đáng. Muốn chơi điện tử thì không.",options:["Bị ốm phải nằm nghỉ","Gia đình có việc gấp","Muốn ở nhà chơi điện tử","Trời đang mưa bão to"],answers:[0,1,3]},{id:"dd3-khi-chua-giu-duoc-hua-05",type:"fill",q:"Khi không giữ được lời hứa, em cần nói lời xin …",explain:"Em nói lời xin lỗi.",answer:["lỗi"]},{id:"dd3-khi-chua-giu-duoc-hua-06",type:"mc",q:"Lời nói nào phù hợp khi em không thể đến như đã hẹn?",explain:"Em nói rõ lí do, xin lỗi và hẹn lại một cách lịch sự.",options:["Mình không đến được thì thôi, bạn cứ tự chơi một mình đi nhé.","Tại bạn hẹn sớm quá nên mình không đến được đâu.","Ai bảo bạn cứ chờ mình làm gì, mình bận lắm.","Mình xin lỗi, mình bị ốm nên không đến được. Hẹn bạn hôm khác nhé!"],answer:3},{id:"dd3-khi-chua-giu-duoc-hua-07",type:"tf",q:"Báo trước khi không thể giữ lời hẹn giúp người khác không phải chờ đợi.",explain:"Đúng rồi. Báo trước là biết tôn trọng thời gian của người khác.",answer:!0},{id:"dd3-khi-chua-giu-duoc-hua-08",type:"mc",q:"Khi đã lỡ thất hứa, em nên làm gì tiếp theo?",explain:"Làm bù điều đã hứa giúp em sửa lỗi.",options:["Hứa thêm nhiều điều khác","Cố gắng làm bù điều đã hứa","Đổ lỗi cho người khác","Quên luôn chuyện đó"],answer:1},{id:"dd3-khi-chua-giu-duoc-hua-09",type:"tf",q:"Nói dối để che giấu việc thất hứa là cách làm đúng.",explain:"Sai. Nói dối càng làm mất lòng tin. Em thật thà nhận lỗi.",answer:!1}]},{questions:[{id:"dd3-khi-chua-giu-duoc-hua-10",type:"order",q:"Sắp xếp các bước khi em không thể giữ lời hẹn.",explain:"Báo sớm, nói lí do, xin lỗi rồi hẹn lại.",items:["Báo sớm cho người đó","Nói rõ lí do","Xin lỗi","Hẹn lại thời gian khác"]},{id:"dd3-khi-chua-giu-duoc-hua-11",type:"mc",q:"Vì sao cần báo sớm khi không thể giữ lời hẹn?",explain:"Báo sớm giúp người kia không mất công chờ đợi.",options:["Để được mọi người khen là bạn ngoan, lễ phép","Để người kia không phải chờ và kịp sắp xếp việc khác","Để từ nay không phải làm việc đó nữa","Để người kia giận và không hẹn mình nữa"],answer:1},{id:"dd3-khi-chua-giu-duoc-hua-12",type:"tf",q:"Bị ốm không đi học nhóm được như đã hẹn, Lan nhờ mẹ gọi điện báo cho các bạn. Lan làm đúng.",explain:"Đúng rồi. Lan báo trước để các bạn không phải chờ.",answer:!0},{id:"dd3-khi-chua-giu-duoc-hua-13",type:"match",q:"Nối tình huống với cách xử lí phù hợp.",explain:"Mỗi lỗi đều cần nhận lỗi và sửa chữa.",pairs:[["Quên mang trả sách cho bạn","Xin lỗi và mai mang trả"],["Bị ốm, không đến được buổi hẹn","Báo cho bạn và hẹn lại"],["Lỡ làm hỏng đồ mượn","Nhận lỗi và tìm cách đền bù"]]},{id:"dd3-khi-chua-giu-duoc-hua-14",type:"multi",q:"Những việc nào KHÔNG nên làm khi lỡ thất hứa?",explain:"Đổ lỗi, nói dối, tránh mặt đều không đúng. Em xin lỗi chân thành.",options:["Đổ lỗi cho người khác","Nói dối","Xin lỗi chân thành","Tránh mặt người đó"],answers:[0,1,3]},{id:"dd3-khi-chua-giu-duoc-hua-15",type:"tf",q:"Nếu đã nói rõ lí do thì không cần xin lỗi.",explain:"Sai. Dù có lí do, em vẫn xin lỗi vì đã làm người khác chờ hoặc buồn.",answer:!1},{id:"dd3-khi-chua-giu-duoc-hua-16",type:"mc",q:"Bạn nào biết sửa lỗi khi thất hứa?",explain:"Hà nhận lỗi và làm bù, đó là cách sửa lỗi đúng.",options:["Bình quên lời hẹn rồi nói là tại bạn nhắc muộn","Chi quên trả bút cho bạn và giữ luôn bút đó","Hà quên ôn bài cùng bạn nên hôm sau xin lỗi và ôn bù","Dũng thất hứa với bạn rồi tránh mặt bạn cả tuần"],answer:2},{id:"dd3-khi-chua-giu-duoc-hua-17",type:"tf",q:"Em không nên hứa giữ bí mật về việc có thể gây nguy hiểm cho bạn.",explain:"Đúng rồi. Việc nguy hiểm cần báo người lớn để bảo vệ bạn.",answer:!0},{id:"dd3-khi-chua-giu-duoc-hua-18",type:"mc",q:"Một bạn rủ Nam hứa cùng trốn học đi chơi. Nam nên làm gì?",explain:"Trốn học là sai, Nam không hứa và khuyên bạn đi học.",options:["Không hứa và khuyên bạn đi học","Hứa cho bạn vui nhưng không đi","Hứa rồi đi chơi cùng bạn","Im lặng rồi đi theo bạn"],answer:0}]},{questions:[{id:"dd3-khi-chua-giu-duoc-hua-19",type:"mc",q:"Ngọc hẹn sang nhà Vy chơi lúc 4 giờ, nhưng mẹ cần Ngọc ở nhà trông em. Ngọc nên làm gì?",explain:"Ngọc giúp mẹ và báo cho Vy biết, như vậy là chu đáo.",options:["Để em ở nhà một mình rồi đi sang nhà Vy","Gọi điện báo Vy, xin lỗi và hẹn hôm khác","Ở nhà trông em nhưng không báo gì cho Vy","Hôm sau nói dối Vy là mình quên mất"],answer:1},{id:"dd3-khi-chua-giu-duoc-hua-20",type:"tf",q:"Tùng mượn hộp bút màu của bạn và làm mất một cây. Tùng xin lỗi bạn và xin bố mẹ mua đền. Tùng làm đúng.",explain:"Đúng rồi. Tùng nhận lỗi và đền bù, bạn sẽ thông cảm.",answer:!0},{id:"dd3-khi-chua-giu-duoc-hua-21",type:"multi",q:"Phúc hứa giúp cô dọn thư viện nhưng hôm đó Phúc bị sốt. Phúc nên làm gì?",explain:"Phúc nghỉ ngơi, báo và xin lỗi cô, khỏi ốm thì giúp cô sau.",options:["Nhờ bố mẹ báo cho cô","Xin lỗi cô","Khỏi ốm thì xin giúp cô việc khác","Cố đến trường dù đang sốt cao","Không báo gì, coi như quên"],answers:[0,1,2]},{id:"dd3-khi-chua-giu-duoc-hua-22",type:"mc",q:"Khoa quên lời hứa đọc truyện cho em, em khóc. Khoa nên làm gì?",explain:"Khoa xin lỗi và làm bù ngay để em vui trở lại.",options:["Mắng em vì em khóc to làm ồn cả nhà","Xin lỗi em và đọc truyện cho em nghe ngay","Hứa mai đọc rồi lại quên tiếp như hôm nay","Bỏ ra ngoài chơi với bạn cho đỡ phiền"],answer:1},{id:"dd3-khi-chua-giu-duoc-hua-23",type:"order",q:"Thảo lỡ quên trả sách thư viện đúng hạn. Sắp xếp việc Thảo nên làm.",explain:"Thảo mang sách đến, xin lỗi, trả sách và rút kinh nghiệm.",items:["Tìm sách và mang đến thư viện","Xin lỗi cô thủ thư","Trả sách","Ghi nhớ hạn trả cho lần sau"]},{id:"dd3-khi-chua-giu-duoc-hua-24",type:"tf",q:"Dũng hứa giữ bí mật chuyện bạn bị bắt nạt nên không nói với ai. Dũng làm đúng.",explain:"Sai. Chuyện bị bắt nạt cần báo thầy cô, bố mẹ để giúp bạn.",answer:!1},{id:"dd3-khi-chua-giu-duoc-hua-25",type:"mc",q:"Vì sao em không nên hứa khi chưa chắc làm được?",explain:"Hứa bừa dễ thất hứa, làm người khác buồn và mất lòng tin.",options:["Vì dễ thất hứa, làm người khác buồn","Vì hứa nhiều điều cùng lúc rất mệt","Vì lời hứa của trẻ em không quan trọng","Vì không ai nghe lời hứa của em cả"],answer:0},{id:"dd3-khi-chua-giu-duoc-hua-26",type:"fill",q:"Thay vì hứa bừa, em chỉ hứa những điều mình làm …",explain:"Em chỉ hứa những điều mình làm được.",answer:["được"]},{id:"dd3-khi-chua-giu-duoc-hua-27",type:"match",q:"Nối câu nói với tình huống phù hợp.",explain:"Mỗi tình huống cần một câu nói phù hợp, thật thà.",pairs:[["Mình xin lỗi, mình quên mất.","Lỡ quên lời hứa"],["Hẹn bạn chiều mai nhé!","Hẹn lại thời gian"],["Mình không hứa điều đó được.","Bạn rủ làm việc sai"]]}]}],challenge:{questions:[{id:"dd3-khi-chua-giu-duoc-hua-28",type:"mc",q:"An hứa đi sinh nhật Chi, nhưng sáng hôm đó ông bị ốm, cả nhà phải đưa ông vào viện. An nên làm gì?",explain:"An ở bên ông là đúng, báo và gửi lời chúc để Chi hiểu và thông cảm.",options:["Không báo gì cho Chi vì cả nhà đang bận","Bỏ ông ở viện để đi sinh nhật cho đúng hẹn","Hôm sau nói dối Chi là mình quên mất ngày","Nhờ bố mẹ báo cho Chi, xin lỗi và gửi lời chúc"],answer:3},{id:"dd3-khi-chua-giu-duoc-hua-29",type:"tf",q:"Giữ lời hứa không có nghĩa là phải làm theo lời hứa sai trái.",explain:"Đúng rồi. Lời hứa sai trái thì không thực hiện.",answer:!0},{id:"dd3-khi-chua-giu-duoc-hua-30",type:"multi",q:"Khi lỡ thất hứa, những việc nào giúp em lấy lại lòng tin?",explain:"Nhận lỗi, làm bù và giữ lời lần sau giúp em lấy lại lòng tin.",options:["Thật thà nhận lỗi","Làm bù điều đã hứa","Cố gắng giữ lời ở lần sau","Hứa thật nhiều cho người khác vui"],answers:[0,1,2]},{id:"dd3-khi-chua-giu-duoc-hua-19",type:"mc",q:"Ngọc hẹn sang nhà Vy chơi lúc 4 giờ, nhưng mẹ cần Ngọc ở nhà trông em. Ngọc nên làm gì?",explain:"Ngọc giúp mẹ và báo cho Vy biết, như vậy là chu đáo.",options:["Để em ở nhà một mình rồi đi sang nhà Vy","Gọi điện báo Vy, xin lỗi và hẹn hôm khác","Ở nhà trông em nhưng không báo gì cho Vy","Hôm sau nói dối Vy là mình quên mất"],answer:1},{id:"dd3-khi-chua-giu-duoc-hua-24",type:"tf",q:"Dũng hứa giữ bí mật chuyện bạn bị bắt nạt nên không nói với ai. Dũng làm đúng.",explain:"Sai. Chuyện bị bắt nạt cần báo thầy cô, bố mẹ để giúp bạn.",answer:!1},{id:"dd3-khi-chua-giu-duoc-hua-10",type:"order",q:"Sắp xếp các bước khi em không thể giữ lời hẹn.",explain:"Báo sớm, nói lí do, xin lỗi rồi hẹn lại.",items:["Báo sớm cho người đó","Nói rõ lí do","Xin lỗi","Hẹn lại thời gian khác"]}]},summary:["Khi không thể giữ lời hứa, em báo sớm, nói rõ lí do, xin lỗi và hẹn lại.","Lỡ quên lời hứa, em thật thà nhận lỗi và làm bù.","Em không hứa và không làm những điều sai trái, nguy hiểm."]}]},{id:"nhiem-vu",title:"Tích cực hoàn thành nhiệm vụ",lessons:[{id:"dd3-tich-cuc-nhiem-vu",title:"Tích cực hoàn thành nhiệm vụ",weeks:[19,20],learn:[{title:"Nhiệm vụ của em",text:"Nhiệm vụ là việc em được giao hoặc nhận làm: học bài, trực nhật, việc nhà, phần việc trong nhóm.",example:"📚 🧹"},{title:"Thế nào là tích cực?",text:"Tích cực hoàn thành nhiệm vụ là chủ động, cố gắng làm xong việc đúng hạn, cẩn thận, không ngại khó.",example:"💪"},{title:"Vì sao cần tích cực?",text:"Hoàn thành tốt nhiệm vụ giúp em tiến bộ, được tin tưởng và góp sức vào việc chung.",example:"⭐"}],practice:[{questions:[{id:"dd3-tich-cuc-nhiem-vu-01",type:"mc",q:"Tích cực hoàn thành nhiệm vụ là gì?",emoji:"💪",explain:"Tích cực là chủ động và cố gắng làm xong việc được giao.",options:["Làm thật nhanh cho xong, dù cẩu thả","Đợi người khác làm hộ mình","Bỏ dở khi gặp khó","Chủ động, cố gắng làm xong việc được giao"],answer:3},{id:"dd3-tich-cuc-nhiem-vu-02",type:"tf",q:"Trực nhật lớp khi đến phiên là một nhiệm vụ của em.",explain:"Đúng rồi. Đến phiên trực nhật, em làm đầy đủ, đúng giờ.",answer:!0},{id:"dd3-tich-cuc-nhiem-vu-03",type:"multi",q:"Đâu là nhiệm vụ của học sinh lớp 3?",explain:"Học tập, trực nhật, giúp việc nhà vừa sức là nhiệm vụ của em.",options:["Học bài và làm bài đầy đủ","Trực nhật lớp theo phân công","Giúp bố mẹ việc nhà vừa sức","Đi làm kiếm tiền"],answers:[0,1,2]},{id:"dd3-tich-cuc-nhiem-vu-04",type:"tf",q:"Gặp việc khó, em bỏ dở và để người khác làm thay.",explain:"Sai. Em cố gắng tìm cách làm và nhờ giúp đỡ khi cần.",answer:!1},{id:"dd3-tich-cuc-nhiem-vu-05",type:"fill",q:"Làm xong việc được giao đúng thời gian gọi là làm đúng …",explain:"Làm xong đúng thời gian là làm đúng hạn.",answer:["hạn","hẹn"]},{id:"dd3-tich-cuc-nhiem-vu-06",type:"mc",q:"Bạn nào tích cực hoàn thành nhiệm vụ?",explain:"Lan chủ động làm xong phần việc của mình trước hạn.",options:["Lan làm xong phần việc trong nhóm trước hạn","Bình ngồi chơi để các bạn trong nhóm làm hết","Chi làm qua loa cho xong rồi đi chơi","Dũng quên mất việc cô giao cho cả nhóm"],answer:0},{id:"dd3-tich-cuc-nhiem-vu-07",type:"tf",q:"Hoàn thành tốt nhiệm vụ giúp em được mọi người tin tưởng.",explain:"Đúng rồi. Người làm tốt việc được giao luôn được tin tưởng.",answer:!0},{id:"dd3-tich-cuc-nhiem-vu-08",type:"mc",q:"Trái với tích cực hoàn thành nhiệm vụ là gì?",explain:"Lười biếng, ỷ lại là trái với tích cực.",options:["Chăm chỉ, cố gắng","Cẩn thận, chu đáo","Lười biếng, ỷ lại","Chủ động, tự giác"],answer:2},{id:"dd3-tich-cuc-nhiem-vu-09",type:"tf",q:"Chỉ cần làm nhiệm vụ khi có thầy cô kiểm tra.",explain:"Sai. Em tự giác làm nhiệm vụ dù có ai kiểm tra hay không.",answer:!1}]},{questions:[{id:"dd3-tich-cuc-nhiem-vu-10",type:"mc",q:"Vì sao cần tích cực hoàn thành nhiệm vụ?",explain:"Tích cực làm việc giúp em tiến bộ và giúp ích cho mọi người.",options:["Để được ra về sớm hơn các bạn khác","Để em tiến bộ và góp sức vào việc chung","Để sau này không phải làm gì nữa cả","Để người khác thấy và làm hộ phần của mình"],answer:1},{id:"dd3-tich-cuc-nhiem-vu-11",type:"match",q:"Nối nhiệm vụ với cách làm tích cực.",explain:"Mỗi nhiệm vụ đều cần làm đầy đủ, cẩn thận, đúng hạn.",pairs:[["Trực nhật lớp","Quét lớp sạch sẽ, đúng giờ"],["Bài tập về nhà","Tự làm đầy đủ, cẩn thận"],["Phần việc trong nhóm","Làm xong đúng hạn"]]},{id:"dd3-tich-cuc-nhiem-vu-12",type:"tf",q:"Ỷ lại vào bạn khi làm việc nhóm là thiếu tích cực.",explain:"Đúng rồi. Mỗi bạn cần làm tốt phần việc của mình.",answer:!0},{id:"dd3-tich-cuc-nhiem-vu-13",type:"multi",q:"Việc nào giúp em hoàn thành tốt nhiệm vụ?",explain:"Hiểu rõ việc, làm cẩn thận và hỏi khi chưa hiểu giúp em làm tốt.",options:["Hiểu rõ việc cần làm","Làm cẩn thận từng bước","Để đến sát giờ mới làm","Hỏi khi chưa hiểu"],answers:[0,1,3]},{id:"dd3-tich-cuc-nhiem-vu-14",type:"tf",q:"Làm thật nhanh cho xong, dù cẩu thả, là tích cực hoàn thành nhiệm vụ.",explain:"Sai. Tích cực là làm xong và làm cẩn thận.",answer:!1},{id:"dd3-tich-cuc-nhiem-vu-15",type:"mc",q:"Được giao nhiệm vụ mà chưa hiểu rõ, em nên làm gì?",explain:"Hỏi lại cho rõ giúp em làm đúng việc được giao.",options:["Làm đại cho xong, sai thì thôi","Bỏ không làm vì không hiểu","Hỏi lại người giao việc cho rõ","Chờ bạn làm xong rồi chép theo"],answer:2},{id:"dd3-tich-cuc-nhiem-vu-16",type:"order",q:"Sắp xếp các bước hoàn thành một nhiệm vụ.",explain:"Hiểu việc, lên kế hoạch, làm cẩn thận rồi kiểm tra lại.",items:["Hiểu rõ nhiệm vụ","Lên kế hoạch làm","Làm cẩn thận từng việc","Kiểm tra lại kết quả"]},{id:"dd3-tich-cuc-nhiem-vu-17",type:"tf",q:"Làm xong việc của mình, bạn tích cực còn hỏi xem có thể giúp bạn khác không.",explain:"Đúng rồi. Giúp bạn khi đã xong việc làm cho việc chung tốt hơn.",answer:!0},{id:"dd3-tich-cuc-nhiem-vu-18",type:"mc",q:"Không hoàn thành nhiệm vụ sẽ dẫn đến điều gì?",explain:"Bỏ dở nhiệm vụ làm ảnh hưởng đến em và việc chung.",options:["Không có gì xảy ra, mọi việc vẫn bình thường","Ảnh hưởng đến kết quả của em và mọi người","Được mọi người khen nhiều hơn trước","Được nghỉ thêm mà không ai nhắc"],answer:1}]},{questions:[{id:"dd3-tich-cuc-nhiem-vu-19",type:"mc",q:"Đến phiên trực nhật nhưng Khoa muốn ra chơi ngay. Khoa nên làm gì?",explain:"Khoa làm xong nhiệm vụ trước rồi mới đi chơi.",options:["Bỏ đi chơi, để lớp bẩn cũng được","Nhờ bạn làm hộ rồi chạy đi chơi","Làm xong trực nhật rồi mới đi chơi","Làm qua loa cho nhanh để được chơi"],answer:2},{id:"dd3-tich-cuc-nhiem-vu-20",type:"tf",q:"Nhóm Hà làm báo tường, Hà được giao vẽ tranh. Hà vẽ xong sớm rồi giúp bạn trang trí. Hà rất tích cực.",explain:"Đúng rồi. Hà làm tốt phần mình và còn giúp bạn.",answer:!0},{id:"dd3-tich-cuc-nhiem-vu-21",type:"multi",q:"Trong nhóm của Minh có bạn chưa làm phần việc của mình. Minh nên làm gì?",explain:"Minh nhắc nhẹ nhàng, hỏi han và giúp bạn để cả nhóm hoàn thành việc.",options:["Nhắc nhở bạn nhẹ nhàng","Hỏi bạn có gặp khó khăn gì không","Cùng bạn tìm cách làm","Mắng bạn trước cả lớp","Làm hộ hết phần của bạn mà không nói gì"],answers:[0,1,2]},{id:"dd3-tich-cuc-nhiem-vu-22",type:"mc",q:"Mẹ giao Vy tưới cây mỗi chiều, có hôm Vy mải chơi nên quên. Vy nên làm gì?",explain:"Vy tự nhắc mình để làm tròn việc được giao.",options:["Bỏ luôn việc tưới cây","Nói là cây tự héo","Tự nhắc mình và tưới cây đều đặn","Nhờ em tưới rồi không kiểm tra"],answer:2},{id:"dd3-tich-cuc-nhiem-vu-23",type:"order",q:"Nam được giao tưới cây cho lớp. Sắp xếp việc Nam làm.",explain:"Nam chuẩn bị, tưới cây rồi cất dụng cụ gọn gàng.",items:["Lấy bình tưới","Hứng nước sạch","Tưới đủ nước cho từng chậu","Cất bình tưới đúng chỗ"]},{id:"dd3-tich-cuc-nhiem-vu-24",type:"tf",q:"Tùng làm lớp trưởng nhưng việc gì cũng đẩy cho bạn khác làm. Tùng làm đúng.",explain:"Sai. Tùng cần gương mẫu, làm tốt việc của mình.",answer:!1},{id:"dd3-tich-cuc-nhiem-vu-25",type:"mc",q:"Bài tập về nhà nhiều, Ngọc thấy hơi mệt. Ngọc nên làm gì?",explain:"Nghỉ ngắn để lấy sức rồi làm tiếp là cách tích cực.",options:["Bỏ dở bài tập để đi ngủ luôn","Nghỉ một chút rồi làm tiếp cho xong","Nhờ chị làm hộ các bài còn lại","Sáng mai đến lớp sớm chép bài của bạn"],answer:1},{id:"dd3-tich-cuc-nhiem-vu-26",type:"fill",q:"Người chủ động, cố gắng làm xong việc được giao là người tích …",explain:"Đó là người tích cực.",answer:["cực"]},{id:"dd3-tich-cuc-nhiem-vu-27",type:"match",q:"Nối việc làm với nhận xét đúng.",explain:"Em học theo việc làm có trách nhiệm, tránh ỷ lại và cẩu thả.",pairs:[["Làm xong phần việc đúng hạn","Có trách nhiệm"],["Đợi bạn làm hộ","Ỷ lại"],["Làm cho xong, nhiều lỗi","Cẩu thả"]]}]}],challenge:{questions:[{id:"dd3-tich-cuc-nhiem-vu-28",type:"mc",q:"Lớp chuẩn bị văn nghệ, Thảo được giao múa nhưng thấy động tác khó. Thảo nên làm gì?",explain:"Thảo kiên trì luyện tập và nhờ giúp đỡ để hoàn thành tốt.",options:["Chăm tập và nhờ bạn hướng dẫn thêm","Xin bỏ cuộc ngay vì động tác khó quá","Tập qua loa, đến đâu hay đến đó","Đổ lỗi cho bài múa quá khó"],answer:0},{id:"dd3-tich-cuc-nhiem-vu-29",type:"tf",q:"Tích cực hoàn thành nhiệm vụ giúp em rèn tính tự lập và trách nhiệm.",explain:"Đúng rồi. Mỗi nhiệm vụ hoàn thành giúp em lớn lên.",answer:!0},{id:"dd3-tich-cuc-nhiem-vu-30",type:"multi",q:"Những bạn nào cần cố gắng hơn khi làm nhiệm vụ?",explain:"Bình, Dũng, Phúc chưa tích cực. An đã làm tốt.",options:["Bình hay để bài tập đến sáng mới làm","An làm bài xong rồi mới chơi","Dũng trực nhật qua loa","Phúc nhận việc rồi bỏ dở"],answers:[0,2,3]},{id:"dd3-tich-cuc-nhiem-vu-19",type:"mc",q:"Đến phiên trực nhật nhưng Khoa muốn ra chơi ngay. Khoa nên làm gì?",explain:"Khoa làm xong nhiệm vụ trước rồi mới đi chơi.",options:["Bỏ đi chơi, để lớp bẩn cũng được","Nhờ bạn làm hộ rồi chạy đi chơi","Làm xong trực nhật rồi mới đi chơi","Làm qua loa cho nhanh để được chơi"],answer:2},{id:"dd3-tich-cuc-nhiem-vu-21",type:"multi",q:"Trong nhóm của Minh có bạn chưa làm phần việc của mình. Minh nên làm gì?",explain:"Minh nhắc nhẹ nhàng, hỏi han và giúp bạn để cả nhóm hoàn thành việc.",options:["Nhắc nhở bạn nhẹ nhàng","Hỏi bạn có gặp khó khăn gì không","Cùng bạn tìm cách làm","Mắng bạn trước cả lớp","Làm hộ hết phần của bạn mà không nói gì"],answers:[0,1,2]},{id:"dd3-tich-cuc-nhiem-vu-16",type:"order",q:"Sắp xếp các bước hoàn thành một nhiệm vụ.",explain:"Hiểu việc, lên kế hoạch, làm cẩn thận rồi kiểm tra lại.",items:["Hiểu rõ nhiệm vụ","Lên kế hoạch làm","Làm cẩn thận từng việc","Kiểm tra lại kết quả"]}]},summary:["Tích cực hoàn thành nhiệm vụ là chủ động, cố gắng làm xong việc được giao.","Em làm cẩn thận, đúng hạn, không ỷ lại.","Hoàn thành tốt nhiệm vụ giúp em tiến bộ và được tin tưởng."]},{id:"dd3-lam-viec-co-ke-hoach",title:"Làm việc có kế hoạch",weeks:[21,22],learn:[{title:"Lập kế hoạch",text:"Em ghi ra những việc cần làm, việc nào làm trước, việc nào làm sau và khi nào xong.",example:"📝 ⏰"},{title:"Làm đến nơi đến chốn",text:"Em làm cẩn thận từng việc, không bỏ dở. Làm xong, em tự kiểm tra lại.",example:"✅"},{title:"Vượt qua khó khăn",text:"Gặp khó, em bình tĩnh tìm cách, chia nhỏ việc và nhờ thầy cô, bố mẹ, bạn bè giúp khi cần.",example:"🧩"}],practice:[{questions:[{id:"dd3-lam-viec-co-ke-hoach-01",type:"tf",q:"Lập kế hoạch giúp em làm việc gọn gàng, không bị quên.",emoji:"📝",explain:"Đúng rồi. Có kế hoạch, em biết việc nào cần làm và làm khi nào.",answer:!0},{id:"dd3-lam-viec-co-ke-hoach-02",type:"mc",q:"Làm xong việc, em nên làm gì?",explain:"Kiểm tra lại giúp em phát hiện lỗi và sửa kịp.",options:["Tự kiểm tra lại kết quả","Để đó không xem lại","Khoe ngay mà không kiểm tra","Xé đi làm lại từ đầu"],answer:0},{id:"dd3-lam-viec-co-ke-hoach-03",type:"multi",q:"Kế hoạch làm việc nên ghi những gì?",explain:"Kế hoạch ghi việc cần làm, thứ tự và thời gian hoàn thành.",options:["Việc cần làm","Thứ tự làm","Thời gian làm xong","Tên món đồ chơi yêu thích"],answers:[0,1,2]},{id:"dd3-lam-viec-co-ke-hoach-04",type:"tf",q:"Làm nửa chừng rồi bỏ cũng được gọi là làm đến nơi đến chốn.",explain:"Sai. Làm đến nơi đến chốn là làm xong hẳn, không bỏ dở.",answer:!1},{id:"dd3-lam-viec-co-ke-hoach-05",type:"fill",q:"Ghi ra việc cần làm và thời gian làm gọi là lập kế …",explain:"Đó là lập kế hoạch.",answer:["hoạch"]},{id:"dd3-lam-viec-co-ke-hoach-06",type:"mc",q:"Gặp khó khăn khi làm nhiệm vụ, em nên làm gì?",explain:"Bình tĩnh tìm cách và nhờ giúp đỡ giúp em vượt qua khó khăn.",options:["Bình tĩnh tìm cách và nhờ giúp đỡ khi cần","Ngồi khóc rồi bỏ cuộc ngay lúc đó","Nổi cáu với mọi người xung quanh","Giả vờ với mọi người là mình đã làm xong rồi"],answer:0},{id:"dd3-lam-viec-co-ke-hoach-07",type:"tf",q:"Vừa làm bài vừa xem ti vi giúp em làm bài nhanh và đúng hơn.",explain:"Sai. Xem ti vi làm em mất tập trung, dễ sai.",answer:!1},{id:"dd3-lam-viec-co-ke-hoach-08",type:"mc",q:"Đâu là cách làm việc khoa học?",explain:"Làm lần lượt theo kế hoạch giúp em không bỏ sót việc.",options:["Làm nhiều việc cùng lúc lộn xộn","Chỉ làm việc mình thích","Làm lần lượt từng việc theo kế hoạch","Để mọi việc đến sát giờ"],answer:2},{id:"dd3-lam-viec-co-ke-hoach-09",type:"tf",q:"Biết nhờ giúp đỡ khi gặp việc khó cũng là cách để hoàn thành nhiệm vụ.",explain:"Đúng rồi. Nhờ giúp đỡ đúng lúc giúp em làm xong việc.",answer:!0}]},{questions:[{id:"dd3-lam-viec-co-ke-hoach-10",type:"order",q:"Sắp xếp các bước lập kế hoạch cho buổi tối.",explain:"Ghi việc, xếp thứ tự, dự tính thời gian rồi làm và đánh dấu.",items:["Ghi ra các việc cần làm","Xếp việc quan trọng lên trước","Dự tính thời gian cho từng việc","Làm theo và đánh dấu việc đã xong"]},{id:"dd3-lam-viec-co-ke-hoach-11",type:"mc",q:"Vì sao nên làm việc quan trọng trước?",explain:"Làm việc quan trọng trước giúp em không bỏ lỡ việc cần thiết.",options:["Để có cớ bỏ những việc khác đi","Vì việc quan trọng lúc nào cũng dễ làm","Để chắc chắn việc cần thiết được làm xong","Để có thật nhiều thời gian đi chơi hơn"],answer:2},{id:"dd3-lam-viec-co-ke-hoach-12",type:"tf",q:"Tự kiểm tra lại bài giúp em phát hiện và sửa lỗi sai.",explain:"Đúng rồi. Kiểm tra lại là bước quan trọng khi làm việc.",answer:!0},{id:"dd3-lam-viec-co-ke-hoach-13",type:"match",q:"Nối khó khăn với cách vượt qua.",explain:"Mỗi khó khăn đều có cách vượt qua phù hợp.",pairs:[["Việc quá nhiều","Chia nhỏ, làm từng phần"],["Hay quên việc","Ghi vào sổ hoặc bảng"],["Gặp bài khó","Hỏi thầy cô, bố mẹ"]]},{id:"dd3-lam-viec-co-ke-hoach-14",type:"multi",q:"Những thói quen nào làm em khó hoàn thành nhiệm vụ?",explain:"Trì hoãn, vừa làm vừa chơi, dễ nản là thói quen cần bỏ.",options:["Hay để việc đến sau mới làm","Vừa làm vừa chơi","Làm theo kế hoạch","Dễ nản lòng"],answers:[0,1,3]},{id:"dd3-lam-viec-co-ke-hoach-15",type:"tf",q:"Để đến sát hạn mới làm sẽ giúp kết quả tốt hơn.",explain:"Sai. Làm sát hạn dễ vội vàng, thiếu sót.",answer:!1},{id:"dd3-lam-viec-co-ke-hoach-16",type:"mc",q:"Bạn nào làm việc có kế hoạch?",explain:"Chi có kế hoạch rõ ràng và theo dõi việc đã làm.",options:["Bình nhớ ra việc gì thì làm việc đó, không ghi lại","Dũng để hết mọi việc đến tối Chủ nhật mới làm","Nam vừa xem phim vừa làm bài tập về nhà","Chi ghi việc cần làm vào bảng và đánh dấu khi xong"],answer:3},{id:"dd3-lam-viec-co-ke-hoach-17",type:"tf",q:"Khi làm việc nhóm, mỗi bạn hoàn thành phần của mình thì việc chung sẽ tốt.",explain:"Đúng rồi. Việc chung tốt khi mỗi bạn đều làm tốt phần việc.",answer:!0},{id:"dd3-lam-viec-co-ke-hoach-18",type:"mc",q:"Hà được giao một việc lớn, cần làm trong một tuần. Cách nào hợp lí?",explain:"Chia nhỏ việc và làm đều mỗi ngày giúp Hà không bị quá sức.",options:["Để đến ngày cuối cùng rồi làm hết một lần","Chia thành việc nhỏ, mỗi ngày làm một phần","Làm vài hôm đầu rồi bỏ dở giữa chừng","Chờ người khác nhắc nhở thì mới bắt đầu làm"],answer:1}]},{questions:[{id:"dd3-lam-viec-co-ke-hoach-19",type:"mc",q:"Tối nay Phúc phải làm bài tập, chuẩn bị sách vở và muốn xem phim hoạt hình. Phúc nên làm thế nào?",explain:"Phúc làm xong việc cần làm trước, rồi mới giải trí.",options:["Xem phim hoạt hình trước rồi tính sau","Vừa xem phim vừa làm bài cho đỡ chán","Làm bài, chuẩn bị sách vở xong rồi mới xem phim","Bỏ làm bài, chỉ chuẩn bị sách vở rồi xem phim"],answer:2},{id:"dd3-lam-viec-co-ke-hoach-20",type:"tf",q:"Thảo làm xong bài nhưng không kiểm tra lại nên còn nhiều lỗi. Lần sau Thảo cần tự kiểm tra trước khi nộp.",explain:"Đúng rồi. Kiểm tra lại giúp Thảo sửa lỗi kịp thời.",answer:!0},{id:"dd3-lam-viec-co-ke-hoach-21",type:"multi",q:"Tùng được giao chuẩn bị bài giới thiệu về một loài chim. Tùng nên làm gì?",explain:"Chuẩn bị từ sớm, có ý rõ ràng và tập trước giúp Tùng nói tốt.",options:["Tìm thông tin trong sách","Ghi ra những ý sẽ nói","Tập nói trước ở nhà","Đến lớp mới nghĩ xem nói gì","Chép nguyên bài của bạn khác"],answers:[0,1,2]},{id:"dd3-lam-viec-co-ke-hoach-22",type:"order",q:"Vy dọn góc học tập. Sắp xếp các bước hợp lí.",explain:"Dọn trống bàn, lau sạch rồi xếp lại gọn gàng.",items:["Lấy hết đồ trên bàn ra","Lau sạch bàn","Xếp sách vở gọn gàng","Cất đồ dùng vào đúng chỗ"]},{id:"dd3-lam-viec-co-ke-hoach-23",type:"mc",q:"Nhóm của An làm chậm vì một bạn bị ốm. Nhóm nên làm gì?",explain:"Cả nhóm cùng chia sẻ để hoàn thành việc chung.",options:["Bỏ luôn phần việc của bạn bị ốm","Trách bạn bị ốm làm cả nhóm chậm","Nộp bài còn thiếu mà không báo gì cho cô","Chia lại việc để làm giúp phần của bạn"],answer:3},{id:"dd3-lam-viec-co-ke-hoach-24",type:"tf",q:"Thấy bài khó, Dũng chép đáp án của bạn để kịp nộp. Dũng đã hoàn thành tốt nhiệm vụ.",explain:"Sai. Chép bài không phải là tự hoàn thành nhiệm vụ. Dũng nên hỏi cách làm.",answer:!1},{id:"dd3-lam-viec-co-ke-hoach-25",type:"mc",q:"Khoa được giao nhiều việc cùng lúc và thấy rối. Khoa nên làm gì đầu tiên?",explain:"Ghi ra và sắp xếp việc giúp Khoa bình tĩnh, làm lần lượt.",options:["Ngồi khóc vì có quá nhiều việc","Ghi ra các việc và chọn việc gấp làm trước","Bỏ hết, không làm việc nào cả","Làm một việc dễ nhất rồi đi chơi luôn"],answer:1},{id:"dd3-lam-viec-co-ke-hoach-26",type:"fill",q:"Làm xong việc, em tự kiểm tra lại để sửa … sai.",explain:"Em kiểm tra lại để sửa lỗi sai.",answer:["lỗi"]},{id:"dd3-lam-viec-co-ke-hoach-27",type:"match",q:"Nối việc làm với lợi ích của nó.",explain:"Mỗi cách làm đều giúp em hoàn thành nhiệm vụ tốt hơn.",pairs:[["Lập kế hoạch","Không quên việc"],["Kiểm tra lại bài","Ít lỗi sai"],["Chia nhỏ việc lớn","Đỡ thấy quá sức"]]}]}],challenge:{questions:[{id:"dd3-lam-viec-co-ke-hoach-28",type:"mc",q:"Ngày mai lớp thi đấu cờ vua, Minh đang tập thì được bạn rủ đi chơi. Minh nên làm gì?",explain:"Minh hoàn thành buổi tập trước, đó là có trách nhiệm với lớp.",options:["Tập xong buổi tập rồi mới đi chơi","Bỏ dở buổi tập để đi chơi ngay","Xin cô cho mình không thi nữa","Tập qua loa vài phút cho xong"],answer:0},{id:"dd3-lam-viec-co-ke-hoach-29",type:"tf",q:"Làm xong đúng hạn và cẩn thận tốt hơn làm thật nhanh mà nhiều lỗi.",explain:"Đúng rồi. Kết quả tốt cần cả đúng hạn và cẩn thận.",answer:!0},{id:"dd3-lam-viec-co-ke-hoach-30",type:"multi",q:"Làm xong một nhiệm vụ, em nên tự hỏi điều gì?",explain:"Tự hỏi để kiểm tra và rút kinh nghiệm giúp em tiến bộ.",options:["Mình đã làm xong hết chưa?","Có chỗ nào cần sửa không?","Lần sau mình làm tốt hơn thế nào?","Làm sao để lần sau khỏi phải làm?"],answers:[0,1,2]},{id:"dd3-lam-viec-co-ke-hoach-19",type:"mc",q:"Tối nay Phúc phải làm bài tập, chuẩn bị sách vở và muốn xem phim hoạt hình. Phúc nên làm thế nào?",explain:"Phúc làm xong việc cần làm trước, rồi mới giải trí.",options:["Xem phim hoạt hình trước rồi tính sau","Vừa xem phim vừa làm bài cho đỡ chán","Làm bài, chuẩn bị sách vở xong rồi mới xem phim","Bỏ làm bài, chỉ chuẩn bị sách vở rồi xem phim"],answer:2},{id:"dd3-lam-viec-co-ke-hoach-21",type:"multi",q:"Tùng được giao chuẩn bị bài giới thiệu về một loài chim. Tùng nên làm gì?",explain:"Chuẩn bị từ sớm, có ý rõ ràng và tập trước giúp Tùng nói tốt.",options:["Tìm thông tin trong sách","Ghi ra những ý sẽ nói","Tập nói trước ở nhà","Đến lớp mới nghĩ xem nói gì","Chép nguyên bài của bạn khác"],answers:[0,1,2]},{id:"dd3-lam-viec-co-ke-hoach-13",type:"match",q:"Nối khó khăn với cách vượt qua.",explain:"Mỗi khó khăn đều có cách vượt qua phù hợp.",pairs:[["Việc quá nhiều","Chia nhỏ, làm từng phần"],["Hay quên việc","Ghi vào sổ hoặc bảng"],["Gặp bài khó","Hỏi thầy cô, bố mẹ"]]}]},summary:["Lập kế hoạch giúp em làm việc gọn gàng, không quên việc.","Em làm đến nơi đến chốn và tự kiểm tra lại kết quả.","Gặp khó, em chia nhỏ việc và nhờ giúp đỡ khi cần."]}]},{id:"kham-pha-ban-than",title:"Khám phá bản thân",lessons:[{id:"dd3-diem-manh-diem-yeu",title:"Điểm mạnh, điểm yếu của em",weeks:[23,24],learn:[{title:"Điểm mạnh",text:"Điểm mạnh là những điều em làm tốt hoặc nét tính cách tốt, như vẽ đẹp, hát hay, chăm chỉ, tốt bụng.",example:"🌟 🎨 🎵"},{title:"Điểm yếu",text:"Điểm yếu là những điều em chưa làm tốt, như hay quên, viết chữ chưa cẩn thận, còn nóng tính.",example:"🌱"},{title:"Ai cũng vậy",text:"Mỗi người đều có điểm mạnh và điểm yếu. Biết rõ bản thân giúp em tự tin và biết mình cần cố gắng ở đâu.",example:"🪞"}],practice:[{questions:[{id:"dd3-diem-manh-diem-yeu-01",type:"mc",q:"Điểm mạnh là gì?",emoji:"🌟",explain:"Điểm mạnh là những điều em làm tốt hoặc nét tính cách tốt.",options:["Những việc em còn làm chưa tốt, cần sửa thêm","Những điều em làm tốt hoặc nét tính cách tốt","Những điều em không thích làm nhất","Những điều bạn bè hay chê em"],answer:1},{id:"dd3-diem-manh-diem-yeu-02",type:"tf",q:"Ai cũng có điểm mạnh và điểm yếu.",explain:"Đúng rồi. Không ai hoàn hảo, ai cũng có điểm mạnh và điểm yếu.",answer:!0},{id:"dd3-diem-manh-diem-yeu-03",type:"multi",q:"Đâu có thể là điểm mạnh của một bạn?",explain:"Vẽ đẹp, tốt bụng là điểm mạnh. Hay nói leo, hay quên là điểm yếu cần sửa.",options:["Vẽ đẹp","Hay nói leo trong giờ học","Tốt bụng, hay giúp đỡ bạn","Hay quên đồ dùng học tập"],answers:[0,2]},{id:"dd3-diem-manh-diem-yeu-04",type:"tf",q:"Hay quên đồ dùng học tập là một điểm yếu cần khắc phục.",explain:"Đúng rồi. Em có thể khắc phục bằng cách chuẩn bị đồ dùng từ tối.",answer:!0},{id:"dd3-diem-manh-diem-yeu-05",type:"tf",q:"Có điểm yếu là điều đáng xấu hổ, cần giấu đi.",explain:"Sai. Ai cũng có điểm yếu. Nhận ra điểm yếu giúp em sửa và tiến bộ.",answer:!1},{id:"dd3-diem-manh-diem-yeu-06",type:"fill",q:"Những điều em làm tốt gọi là điểm …",explain:"Những điều em làm tốt gọi là điểm mạnh.",answer:["mạnh"]},{id:"dd3-diem-manh-diem-yeu-07",type:"mc",q:"Biết điểm mạnh của mình giúp em điều gì?",explain:"Biết điểm mạnh giúp em tự tin hơn.",options:["Coi thường bạn","Lười cố gắng","Buồn bã","Tự tin hơn"],answer:3},{id:"dd3-diem-manh-diem-yeu-08",type:"tf",q:"Chỉ những bạn học giỏi mới có điểm mạnh.",explain:"Sai. Bạn nào cũng có điểm mạnh riêng, như khéo tay, vui tính, tốt bụng.",answer:!1},{id:"dd3-diem-manh-diem-yeu-09",type:"mc",q:"Điểm yếu là gì?",explain:"Điểm yếu là những điều em chưa làm tốt và có thể cố gắng sửa.",options:["Những điều em làm giỏi nhất","Những điều em chưa làm tốt, cần cố gắng","Những món ăn em thích","Những điều không bao giờ thay đổi được"],answer:1}]},{questions:[{id:"dd3-diem-manh-diem-yeu-10",type:"match",q:"Nối sở thích với điểm mạnh có thể có.",explain:"Sở thích thường gắn với điểm mạnh của mỗi người.",pairs:[["Thích kể chuyện","Nói lưu loát"],["Thích vẽ tranh","Khéo tay, giàu tưởng tượng"],["Thích chạy nhảy","Khỏe mạnh, nhanh nhẹn"]]},{id:"dd3-diem-manh-diem-yeu-11",type:"tf",q:"Mỗi người có điểm mạnh khác nhau, không ai giống ai.",explain:"Đúng rồi. Mỗi bạn là một người đặc biệt.",answer:!0},{id:"dd3-diem-manh-diem-yeu-12",type:"mc",q:"Vì sao cần biết điểm mạnh, điểm yếu của mình?",explain:"Biết mình giúp em phát huy điểm mạnh và khắc phục điểm yếu.",options:["Để chê những bạn còn kém hơn mình","Để phát huy điều tốt và sửa điều chưa tốt","Để khoe với mọi người là mình giỏi","Để từ nay không phải cố gắng gì nữa"],answer:1},{id:"dd3-diem-manh-diem-yeu-13",type:"multi",q:"Em có thể tìm ra điểm mạnh, điểm yếu của mình bằng cách nào?",explain:"Tự nhìn lại và lắng nghe mọi người giúp em hiểu mình hơn.",options:["Tự nhìn lại việc mình đã làm","Hỏi ý kiến bố mẹ, thầy cô","Lắng nghe góp ý của bạn bè","Không cần suy nghĩ gì"],answers:[0,1,2]},{id:"dd3-diem-manh-diem-yeu-14",type:"tf",q:"Bạn nào hát chưa hay thì không có điểm mạnh nào.",explain:"Sai. Hát chưa hay nhưng bạn có thể giỏi việc khác.",answer:!1},{id:"dd3-diem-manh-diem-yeu-15",type:"mc",q:"Bạn nào nhận xét đúng về bản thân?",explain:"Chi nói được cả điểm mạnh và điểm yếu của mình, như vậy là biết mình.",options:["Chi: “Mình đọc to, rõ nhưng còn hay viết sai chính tả.”","Bình: “Mình chẳng có điểm gì tốt, làm gì cũng kém.”","Dũng: “Mình giỏi nhất lớp, không có điểm yếu nào.”","Vy: “Mình không cần biết mình giỏi hay kém thế nào.”"],answer:0},{id:"dd3-diem-manh-diem-yeu-16",type:"order",q:"Sắp xếp các bước tự khám phá bản thân.",explain:"Tự nghĩ, hỏi thêm người thân rồi ghi lại để nhớ.",items:["Nghĩ về những việc mình làm tốt","Nghĩ về những việc mình chưa làm tốt","Hỏi thêm ý kiến người thân","Ghi lại điểm mạnh, điểm yếu vào sổ"]},{id:"dd3-diem-manh-diem-yeu-17",type:"tf",q:"Khi bạn góp ý về điểm yếu của mình, em nên lắng nghe và cảm ơn bạn.",explain:"Đúng rồi. Góp ý chân thành giúp em tiến bộ.",answer:!0},{id:"dd3-diem-manh-diem-yeu-18",type:"mc",q:"Điểm yếu có thể thay đổi được không?",explain:"Kiên trì cố gắng, em có thể sửa được điểm yếu.",options:["Không bao giờ thay đổi được","Có, nếu em kiên trì cố gắng","Chỉ người lớn mới thay đổi được"],answer:1}]},{questions:[{id:"dd3-diem-manh-diem-yeu-19",type:"mc",q:"Lan vẽ rất đẹp nhưng ngại nói trước lớp. Lan nên nghĩ thế nào?",explain:"Lan tự tin với điểm mạnh và cố gắng khắc phục điểm yếu.",options:["Mình vẽ đẹp, và mình sẽ tập dần để mạnh dạn hơn","Mình kém lắm","Mình chỉ cần vẽ, không cần cố gắng gì khác","Mình sẽ không bao giờ nói được trước lớp"],answer:0},{id:"dd3-diem-manh-diem-yeu-20",type:"tf",q:"Khoa chạy nhanh nhất lớp nên hay chê các bạn chạy chậm. Khoa làm đúng.",explain:"Sai. Có điểm mạnh không có nghĩa là được chê bai người khác.",answer:!1},{id:"dd3-diem-manh-diem-yeu-21",type:"multi",q:"Những bạn nào biết nhìn nhận đúng về bản thân?",explain:"Hà và Tùng nhìn thấy cả điểm mạnh lẫn điểm yếu của mình.",options:["Hà: “Mình tính nhanh, nhưng chữ chưa đẹp.”","Tùng: “Mình hát hay, nhưng còn hay quên.”","Phúc: “Mình chẳng giỏi gì cả.”","Ngọc: “Mình hoàn hảo rồi.”"],answers:[0,1]},{id:"dd3-diem-manh-diem-yeu-22",type:"mc",q:"Cô nhận xét Minh làm bài nhanh nhưng hay sai vì vội. Minh nên làm gì?",explain:"Minh lắng nghe góp ý và sửa điểm yếu để tiến bộ.",options:["Cảm ơn cô và tập làm cẩn thận hơn","Giận cô vì cô chê mình","Cho rằng cô nhận xét sai về bài của mình","Không làm bài nữa cho khỏi sai"],answer:0},{id:"dd3-diem-manh-diem-yeu-23",type:"tf",q:"Thảo biết mình hay quên nên ghi lời nhắc vào sổ. Thảo đã biết khắc phục điểm yếu.",explain:"Đúng rồi. Thảo biết điểm yếu và tìm cách sửa.",answer:!0},{id:"dd3-diem-manh-diem-yeu-24",type:"mc",q:"Bạn mới vào lớp buồn vì nghĩ mình không giỏi gì. Em nên nói gì?",explain:"Lời động viên giúp bạn tự tin và nhận ra điểm mạnh của mình.",options:["Đúng rồi, bạn chẳng giỏi gì cả, buồn cũng phải thôi.","Kệ bạn, mình còn bận chơi với các bạn khác rồi.","Ai cũng có điểm mạnh, mình cùng tìm điểm mạnh của bạn nhé!","Bạn kém hơn mình nhiều lắm, chắc khó theo kịp đâu."],answer:2},{id:"dd3-diem-manh-diem-yeu-25",type:"order",q:"Sắp xếp việc Vy làm để viết “Bức thư gửi chính mình”.",explain:"Vy viết điểm mạnh, điểm yếu, đặt mục tiêu rồi đọc lại để xem mình tiến bộ.",items:["Viết về những điều mình làm tốt","Viết về những điều cần cố gắng","Đặt một mục tiêu nhỏ","Cất thư lại để đọc sau một tháng"]},{id:"dd3-diem-manh-diem-yeu-26",type:"fill",q:"Biết rõ điểm mạnh của mình giúp em tự … hơn.",explain:"Biết điểm mạnh giúp em tự tin hơn.",answer:["tin"]},{id:"dd3-diem-manh-diem-yeu-27",type:"match",q:"Nối câu nói với nhận xét phù hợp.",explain:"Em tự tin đúng mức, không kiêu căng, cũng không tự ti.",pairs:[["Mình giỏi nhất lớp!","Kiêu căng"],["Mình chẳng làm được gì!","Tự ti"],["Mình làm tốt việc này, cần cố gắng việc kia.","Biết mình, tự tin"]]}]}],challenge:{questions:[{id:"dd3-diem-manh-diem-yeu-28",type:"mc",q:"Dũng giỏi Toán nhưng đọc còn chậm. Cách làm nào đúng nhất?",explain:"Dũng vừa phát huy điểm mạnh, vừa luyện tập để sửa điểm yếu.",options:["Chỉ học Toán, bỏ luyện đọc","Buồn vì đọc chậm","Phát huy môn Toán và luyện đọc mỗi ngày","Nói với mọi người là mình đọc nhanh"],answer:2},{id:"dd3-diem-manh-diem-yeu-29",type:"tf",q:"Biết điểm yếu của mình là bước đầu để em tiến bộ.",explain:"Đúng rồi. Biết mình còn yếu ở đâu thì mới sửa được.",answer:!0},{id:"dd3-diem-manh-diem-yeu-30",type:"multi",q:"Những câu nói nào thể hiện sự tự tin đúng mức?",explain:"Tự tin đúng mức là dám thử và biết sửa, không kiêu căng, không tự ti.",options:["“Mình sẽ thử, nếu sai mình sửa.”","“Mình làm được việc này.”","“Mình hơn tất cả mọi người.”","“Mình không dám thử đâu.”"],answers:[0,1]},{id:"dd3-diem-manh-diem-yeu-19",type:"mc",q:"Lan vẽ rất đẹp nhưng ngại nói trước lớp. Lan nên nghĩ thế nào?",explain:"Lan tự tin với điểm mạnh và cố gắng khắc phục điểm yếu.",options:["Mình vẽ đẹp, và mình sẽ tập dần để mạnh dạn hơn","Mình kém lắm","Mình chỉ cần vẽ, không cần cố gắng gì khác","Mình sẽ không bao giờ nói được trước lớp"],answer:0},{id:"dd3-diem-manh-diem-yeu-21",type:"multi",q:"Những bạn nào biết nhìn nhận đúng về bản thân?",explain:"Hà và Tùng nhìn thấy cả điểm mạnh lẫn điểm yếu của mình.",options:["Hà: “Mình tính nhanh, nhưng chữ chưa đẹp.”","Tùng: “Mình hát hay, nhưng còn hay quên.”","Phúc: “Mình chẳng giỏi gì cả.”","Ngọc: “Mình hoàn hảo rồi.”"],answers:[0,1]},{id:"dd3-diem-manh-diem-yeu-15",type:"mc",q:"Bạn nào nhận xét đúng về bản thân?",explain:"Chi nói được cả điểm mạnh và điểm yếu của mình, như vậy là biết mình.",options:["Chi: “Mình đọc to, rõ nhưng còn hay viết sai chính tả.”","Bình: “Mình chẳng có điểm gì tốt, làm gì cũng kém.”","Dũng: “Mình giỏi nhất lớp, không có điểm yếu nào.”","Vy: “Mình không cần biết mình giỏi hay kém thế nào.”"],answer:0}]},summary:["Điểm mạnh là điều em làm tốt, điểm yếu là điều em chưa làm tốt.","Ai cũng có điểm mạnh và điểm yếu.","Biết rõ bản thân giúp em tự tin và biết cần cố gắng ở đâu."]},{id:"dd3-phat-huy-khac-phuc",title:"Phát huy điểm mạnh, khắc phục điểm yếu",weeks:[25,26],learn:[{title:"Phát huy điểm mạnh",text:"Em tiếp tục luyện tập điều mình làm tốt và dùng điểm mạnh để giúp đỡ mọi người.",example:"🌟 🤝"},{title:"Khắc phục điểm yếu",text:"Em chọn một điểm yếu, đặt mục tiêu nhỏ, kiên trì luyện tập và nhờ người khác nhắc nhở.",example:"🎯 📅"},{title:"Tôn trọng bạn bè",text:"Mỗi bạn có điểm mạnh riêng. Em không chê bai điểm yếu của bạn mà cùng nhau tiến bộ.",example:"👫"}],practice:[{questions:[{id:"dd3-phat-huy-khac-phuc-01",type:"tf",q:"Dùng điểm mạnh để giúp đỡ người khác là phát huy điểm mạnh.",emoji:"🤝",explain:"Đúng rồi. Điểm mạnh của em có thể giúp ích cho nhiều người.",answer:!0},{id:"dd3-phat-huy-khac-phuc-02",type:"mc",q:"Muốn khắc phục điểm yếu, em cần gì?",explain:"Kiên trì luyện tập giúp em khắc phục điểm yếu.",options:["Chờ điểm yếu tự hết","Kiên trì luyện tập","Giấu đi không cho ai biết","Đổ lỗi cho người khác"],answer:1},{id:"dd3-phat-huy-khac-phuc-03",type:"multi",q:"Cách nào giúp khắc phục tính hay quên?",explain:"Ghi sổ và chuẩn bị sớm giúp em bớt quên. Để đồ lung tung càng dễ quên.",options:["Ghi việc cần làm vào sổ","Chuẩn bị sách vở từ tối","Để đồ dùng mỗi nơi một thứ","Không cần làm gì"],answers:[0,1]},{id:"dd3-phat-huy-khac-phuc-04",type:"tf",q:"Thấy bạn có điểm yếu, em nên chê cười bạn.",explain:"Sai. Em tôn trọng và giúp bạn cùng tiến bộ.",answer:!1},{id:"dd3-phat-huy-khac-phuc-05",type:"fill",q:"Kiên trì tập luyện giúp em khắc … điểm yếu.",explain:"Kiên trì giúp em khắc phục điểm yếu.",answer:["phục"]},{id:"dd3-phat-huy-khac-phuc-06",type:"mc",q:"Bạn hát hay có thể phát huy điểm mạnh bằng cách nào?",explain:"Tham gia văn nghệ giúp bạn phát huy giọng hát và góp vui cho lớp.",options:["Không hát nữa","Tham gia văn nghệ của lớp","Chê bạn hát dở","Hát thật to trong giờ học"],answer:1},{id:"dd3-phat-huy-khac-phuc-07",type:"tf",q:"Muốn khắc phục điểm yếu, em nên đặt mục tiêu nhỏ và làm từng bước.",explain:"Đúng rồi. Mục tiêu nhỏ giúp em dễ làm và thấy mình tiến bộ.",answer:!0},{id:"dd3-phat-huy-khac-phuc-08",type:"mc",q:"Đâu là cách giúp chữ viết đẹp hơn?",explain:"Luyện viết cẩn thận mỗi ngày giúp chữ đẹp dần.",options:["Viết thật nhanh cho xong","Không viết nữa","Nhờ bạn viết hộ","Luyện viết cẩn thận mỗi ngày"],answer:3},{id:"dd3-phat-huy-khac-phuc-09",type:"tf",q:"Điểm mạnh không cần luyện tập thêm vì đã tốt rồi.",explain:"Sai. Điểm mạnh cũng cần luyện tập để ngày càng tốt hơn.",answer:!1}]},{questions:[{id:"dd3-phat-huy-khac-phuc-10",type:"match",q:"Nối điểm yếu với cách khắc phục.",explain:"Mỗi điểm yếu có cách khắc phục phù hợp.",pairs:[["Hay nóng giận","Hít thở sâu, đếm chậm"],["Ngại nói trước lớp","Tập nói trước người thân"],["Hay làm bài ẩu","Làm chậm lại, kiểm tra kĩ"]]},{id:"dd3-phat-huy-khac-phuc-11",type:"mc",q:"Vì sao nên đặt mục tiêu nhỏ khi sửa điểm yếu?",explain:"Mục tiêu nhỏ vừa sức giúp em kiên trì hơn.",options:["Để không phải cố gắng nhiều nữa","Để làm cho có với mọi người xung quanh","Để có cớ bỏ cuộc sớm hơn","Để dễ làm được và thấy mình tiến bộ"],answer:3},{id:"dd3-phat-huy-khac-phuc-12",type:"tf",q:"Khắc phục điểm yếu cần kiên trì, không thể xong ngay trong một ngày.",explain:"Đúng rồi. Mỗi ngày cố gắng một chút, em sẽ tiến bộ.",answer:!0},{id:"dd3-phat-huy-khac-phuc-13",type:"multi",q:"Những bạn nào biết phát huy điểm mạnh?",explain:"Chi, Nam, Hà dùng điểm mạnh để giúp ích cho lớp.",options:["Chi đọc hay nên giúp cô đọc truyện cho lớp nghe","Nam giỏi Toán nên giảng bài cho bạn","Bình chạy nhanh nên hay chạy xô đẩy bạn","Hà khéo tay nên giúp lớp trang trí"],answers:[0,1,3]},{id:"dd3-phat-huy-khac-phuc-14",type:"tf",q:"Đã cố gắng mà chưa tiến bộ ngay thì em nên bỏ cuộc.",explain:"Sai. Tiến bộ cần thời gian, em tiếp tục kiên trì.",answer:!1},{id:"dd3-phat-huy-khac-phuc-15",type:"mc",q:"Một bạn trong nhóm vẽ chưa đẹp nhưng nói rất hay. Nhóm nên chia việc thế nào?",explain:"Nhóm phát huy điểm mạnh của bạn và giúp bạn tiến bộ.",options:["Không cho bạn làm gì cả vì bạn vẽ chưa đẹp","Chê bạn vẽ xấu trước cả nhóm","Bắt bạn vẽ hết cả bức tranh một mình","Giao bạn thuyết trình và cùng giúp bạn tập vẽ"],answer:3},{id:"dd3-phat-huy-khac-phuc-16",type:"order",q:"Sắp xếp các bước khắc phục một điểm yếu.",explain:"Nhận ra, đặt mục tiêu, luyện tập rồi nhìn lại sự tiến bộ.",items:["Nhận ra điểm yếu của mình","Đặt mục tiêu nhỏ","Luyện tập mỗi ngày","Nhìn lại xem mình tiến bộ thế nào"]},{id:"dd3-phat-huy-khac-phuc-17",type:"tf",q:"Lời góp ý chân thành của bạn bè giúp em biết điều cần sửa.",explain:"Đúng rồi. Em lắng nghe và cảm ơn lời góp ý.",answer:!0},{id:"dd3-phat-huy-khac-phuc-18",type:"mc",q:"Khi thấy mình tiến bộ, em nên làm gì?",explain:"Em vui với tiến bộ của mình và tiếp tục cố gắng.",options:["Dừng lại, không cần cố gắng nữa","Chê những bạn chưa tiến bộ bằng mình","Tự khen mình và tiếp tục cố gắng","Đi khoe khoang khắp nơi với mọi người"],answer:2}]},{questions:[{id:"dd3-phat-huy-khac-phuc-19",type:"mc",q:"Phúc hay nóng giận khi thua trò chơi. Phúc nên làm gì?",explain:"Bình tĩnh và coi thua cuộc là dịp để cố gắng giúp Phúc bớt nóng giận.",options:["Ném đồ chơi đi thật xa cho bớt tức","Không chơi trò chơi với ai nữa cả","Cãi nhau với bạn thắng cuộc cho hả giận","Hít thở sâu và tự nhủ lần sau sẽ cố gắng hơn"],answer:3},{id:"dd3-phat-huy-khac-phuc-20",type:"tf",q:"Ngọc ngại phát biểu nên mỗi tuần đặt mục tiêu giơ tay phát biểu ít nhất một lần. Ngọc đang khắc phục điểm yếu.",explain:"Đúng rồi. Ngọc đặt mục tiêu nhỏ để mạnh dạn dần.",answer:!0},{id:"dd3-phat-huy-khac-phuc-21",type:"multi",q:"Tùng viết chính tả hay sai. Tùng có thể làm gì?",explain:"Đọc nhiều, ghi lại và luyện viết giúp Tùng viết đúng hơn.",options:["Đọc nhiều sách để quen mặt chữ","Ghi các từ hay viết sai vào sổ","Luyện viết lại những từ đó","Không viết chính tả nữa","Viết thật nhanh cho xong bài"],answers:[0,1,2]},{id:"dd3-phat-huy-khac-phuc-22",type:"mc",q:"Vy giỏi tiếng Anh, bạn cùng bàn còn yếu môn này. Vy nên làm gì?",explain:"Vy dùng điểm mạnh để giúp bạn cùng tiến bộ.",options:["Cười bạn kém","Khoe điểm cao của mình với bạn","Không chơi với bạn","Giúp bạn ôn từ mới khi có thời gian"],answer:3},{id:"dd3-phat-huy-khac-phuc-23",type:"tf",q:"Minh biết mình dễ nản, nên gặp bài khó Minh bỏ luôn cho đỡ mệt. Minh làm đúng.",explain:"Sai. Minh nên chia nhỏ bài và kiên trì để sửa tính dễ nản.",answer:!1},{id:"dd3-phat-huy-khac-phuc-24",type:"order",q:"Lan muốn bơi giỏi hơn. Sắp xếp các bước hợp lí.",explain:"Lan học bơi có người hướng dẫn để an toàn, luyện tập đều và theo dõi tiến bộ.",items:["Nhờ bố mẹ cho đi học bơi","Học bơi cùng người hướng dẫn","Luyện tập đều đặn","Ghi lại sự tiến bộ"]},{id:"dd3-phat-huy-khac-phuc-25",type:"mc",q:"Khoa vẽ đẹp nhưng làm toán chậm. Lớp có cuộc thi vẽ. Khoa nên làm gì?",explain:"Khoa phát huy điểm mạnh và vẫn cố gắng ở điểm còn yếu.",options:["Bỏ học toán để dành hết thời gian cho tập vẽ","Không thi vì sợ thua các bạn trong lớp","Tham gia thi vẽ và vẫn luyện toán đều đặn","Vẽ tranh dự thi trong giờ học toán"],answer:2},{id:"dd3-phat-huy-khac-phuc-26",type:"fill",q:"Điều em làm tốt, em cần tiếp tục phát …",explain:"Em tiếp tục phát huy điểm mạnh.",answer:["huy"]},{id:"dd3-phat-huy-khac-phuc-27",type:"match",q:"Nối điểm mạnh với việc giúp ích cho lớp.",explain:"Điểm mạnh của mỗi bạn đều giúp ích cho lớp.",pairs:[["Chữ viết đẹp","Viết khẩu hiệu cho lớp"],["Hát hay","Hát trong buổi văn nghệ"],["Giỏi tính toán","Giúp bạn ôn bài Toán"]]}]}],challenge:{questions:[{id:"dd3-phat-huy-khac-phuc-28",type:"mc",q:"Thảo học tốt nhiều môn nên có lúc coi thường bạn. Thảo cần làm gì?",explain:"Người có nhiều điểm mạnh càng cần khiêm tốn và biết giúp đỡ bạn.",options:["Tiếp tục coi thường bạn vì mình học giỏi hơn","Khiêm tốn, tôn trọng bạn và giúp bạn cùng tiến bộ","Không chơi với những bạn học chưa tốt bằng mình","Giấu bài không cho ai xem để giữ vị trí giỏi nhất"],answer:1},{id:"dd3-phat-huy-khac-phuc-29",type:"tf",q:"Biết tôn trọng điểm mạnh, điểm yếu của nhau giúp lớp đoàn kết hơn.",explain:"Đúng rồi. Tôn trọng nhau giúp cả lớp cùng tiến bộ.",answer:!0},{id:"dd3-phat-huy-khac-phuc-30",type:"multi",q:"Kế hoạch khắc phục điểm yếu nên có những gì?",explain:"Kế hoạch cần nêu rõ điểm yếu, việc làm hằng ngày và người giúp đỡ.",options:["Điểm yếu muốn sửa","Việc làm cụ thể mỗi ngày","Người có thể giúp đỡ","Tên những bạn có điểm yếu giống mình"],answers:[0,1,2]},{id:"dd3-phat-huy-khac-phuc-19",type:"mc",q:"Phúc hay nóng giận khi thua trò chơi. Phúc nên làm gì?",explain:"Bình tĩnh và coi thua cuộc là dịp để cố gắng giúp Phúc bớt nóng giận.",options:["Ném đồ chơi đi thật xa cho bớt tức","Không chơi trò chơi với ai nữa cả","Cãi nhau với bạn thắng cuộc cho hả giận","Hít thở sâu và tự nhủ lần sau sẽ cố gắng hơn"],answer:3},{id:"dd3-phat-huy-khac-phuc-21",type:"multi",q:"Tùng viết chính tả hay sai. Tùng có thể làm gì?",explain:"Đọc nhiều, ghi lại và luyện viết giúp Tùng viết đúng hơn.",options:["Đọc nhiều sách để quen mặt chữ","Ghi các từ hay viết sai vào sổ","Luyện viết lại những từ đó","Không viết chính tả nữa","Viết thật nhanh cho xong bài"],answers:[0,1,2]},{id:"dd3-phat-huy-khac-phuc-16",type:"order",q:"Sắp xếp các bước khắc phục một điểm yếu.",explain:"Nhận ra, đặt mục tiêu, luyện tập rồi nhìn lại sự tiến bộ.",items:["Nhận ra điểm yếu của mình","Đặt mục tiêu nhỏ","Luyện tập mỗi ngày","Nhìn lại xem mình tiến bộ thế nào"]}]},summary:["Em phát huy điểm mạnh bằng cách luyện tập và giúp đỡ mọi người.","Em khắc phục điểm yếu bằng mục tiêu nhỏ và sự kiên trì.","Em tôn trọng điểm mạnh, điểm yếu của bạn bè."]}]},{id:"bat-hoa-ban-be",title:"Xử lí bất hòa với bạn bè",lessons:[{id:"dd3-nhan-biet-bat-hoa",title:"Nhận biết bất hòa với bạn bè",weeks:[27,28],learn:[{title:"Bất hòa là gì?",text:"Bất hòa là khi em và bạn không vui với nhau, như cãi nhau, giận nhau, không nhường nhịn nhau.",example:"😠 😢"},{title:"Vì sao có bất hòa?",text:"Bất hòa thường do hiểu lầm, không chịu nhường nhau, trêu chọc nhau hoặc nói lời khó nghe.",example:"❓ 💬"},{title:"Vì sao cần xử lí?",text:"Bất hòa làm các bạn buồn, lớp mất đoàn kết. Xử lí sớm giúp tình bạn tốt đẹp trở lại.",example:"🤝"}],practice:[{questions:[{id:"dd3-nhan-biet-bat-hoa-01",type:"mc",q:"Bất hòa với bạn bè là gì?",emoji:"😠",explain:"Bất hòa là khi em và bạn giận nhau, cãi nhau.",options:["Khi em và bạn cùng chơi vui","Khi em giúp bạn học bài","Khi em và bạn giận nhau, cãi nhau","Khi em chia sẻ đồ chơi với bạn"],answer:2},{id:"dd3-nhan-biet-bat-hoa-02",type:"multi",q:"Đâu là biểu hiện của bất hòa?",explain:"Cãi nhau, không nói chuyện với nhau là biểu hiện của bất hòa.",options:["Cãi nhau","Không nói chuyện với nhau","Cùng nhau chơi vui vẻ","Cùng nhau làm bài"],answers:[0,1]},{id:"dd3-nhan-biet-bat-hoa-03",type:"tf",q:"Hiểu lầm có thể dẫn đến bất hòa giữa các bạn.",explain:"Đúng rồi. Nhiều lần bất hòa bắt đầu từ hiểu lầm.",answer:!0},{id:"dd3-nhan-biet-bat-hoa-04",type:"tf",q:"Bất hòa làm tình bạn thêm gắn bó.",explain:"Sai. Bất hòa làm các bạn buồn và xa nhau.",answer:!1},{id:"dd3-nhan-biet-bat-hoa-05",type:"mc",q:"Điều nào thường gây bất hòa?",explain:"Trêu chọc, nói lời khó nghe dễ làm bạn tức giận.",options:["Giúp đỡ nhau khi học bài khó","Khen ngợi khi bạn làm tốt","Trêu chọc nhau, nói lời khó nghe","Chia sẻ đồ dùng học tập với nhau"],answer:2},{id:"dd3-nhan-biet-bat-hoa-06",type:"fill",q:"Khi em và bạn giận nhau, cãi nhau, ta gọi là bất …",explain:"Đó là bất hòa.",answer:["hòa","hoà"]},{id:"dd3-nhan-biet-bat-hoa-07",type:"tf",q:"Không chịu nhường nhịn nhau dễ gây bất hòa.",explain:"Đúng rồi. Biết nhường nhịn giúp tránh được bất hòa.",answer:!0},{id:"dd3-nhan-biet-bat-hoa-08",type:"mc",q:"Khi có bất hòa, các bạn thường cảm thấy thế nào?",explain:"Bất hòa làm các bạn buồn và khó chịu.",options:["Vui vẻ, thoải mái","Buồn, khó chịu","Hào hứng","Tự hào"],answer:1},{id:"dd3-nhan-biet-bat-hoa-09",type:"tf",q:"Bất hòa với bạn thì cứ để vậy, không cần làm lành.",explain:"Sai. Em nên tìm cách làm lành để tình bạn tốt đẹp trở lại.",answer:!1}]},{questions:[{id:"dd3-nhan-biet-bat-hoa-10",type:"match",q:"Nối tình huống với nguyên nhân gây bất hòa.",explain:"Hiểu lầm, không nhường nhịn, trêu chọc đều có thể gây bất hòa.",pairs:[["Bình cầm nhầm bút, Dũng tưởng Bình lấy","Hiểu lầm"],["Hai bạn giành nhau xích đu","Không nhường nhịn"],["Chi đặt biệt danh xấu cho bạn","Trêu chọc"]]},{id:"dd3-nhan-biet-bat-hoa-11",type:"mc",q:"Vì sao cần xử lí bất hòa sớm?",explain:"Xử lí sớm giúp các bạn hết buồn và lại vui chơi cùng nhau.",options:["Để được thầy cô khen trước cả lớp","Để các bạn hết buồn và đoàn kết trở lại","Để mình thắng được bạn trong cuộc cãi","Để bạn sợ mình, không dám cãi lại mình nữa"],answer:1},{id:"dd3-nhan-biet-bat-hoa-12",type:"tf",q:"Nói xấu bạn sau lưng làm bất hòa thêm căng thẳng.",explain:"Đúng rồi. Nói xấu làm bạn buồn thêm và khó làm lành.",answer:!0},{id:"dd3-nhan-biet-bat-hoa-13",type:"multi",q:"Việc làm nào có thể gây bất hòa?",explain:"Tự ý lấy đồ, chê bai, thất hứa đều dễ gây bất hòa.",options:["Tự ý lấy đồ của bạn","Chê bai bạn","Nói lời cảm ơn","Không giữ lời hứa với bạn"],answers:[0,1,3]},{id:"dd3-nhan-biet-bat-hoa-14",type:"tf",q:"Khi bất hòa, luôn chỉ có một bạn sai, bạn kia hoàn toàn đúng.",explain:"Sai. Nhiều khi cả hai bạn đều có phần lỗi.",answer:!1},{id:"dd3-nhan-biet-bat-hoa-15",type:"mc",q:"Lan và Hà giận nhau vì hiểu lầm. Điều gì giúp hai bạn hết giận?",explain:"Bình tĩnh nói chuyện giúp hai bạn hiểu ra và hết giận.",options:["Không nói chuyện với nhau nữa","Bình tĩnh nói chuyện để hiểu nhau","Kể xấu nhau với cả lớp","Rủ thêm bạn để tẩy chay nhau"],answer:1},{id:"dd3-nhan-biet-bat-hoa-16",type:"order",q:"Sắp xếp diễn biến của một lần bất hòa.",explain:"Hiểu lầm dẫn đến cãi nhau, giận nhau và cả hai đều buồn.",items:["Hai bạn hiểu lầm nhau","Hai bạn cãi nhau","Hai bạn giận, không nói chuyện","Cả hai đều thấy buồn"]},{id:"dd3-nhan-biet-bat-hoa-17",type:"tf",q:"Biết nhận ra lỗi của mình là bước quan trọng để làm lành.",explain:"Đúng rồi. Nhận ra lỗi giúp em dễ xin lỗi và làm lành.",answer:!0},{id:"dd3-nhan-biet-bat-hoa-18",type:"mc",q:"Câu nói nào dễ gây bất hòa?",explain:"Lời chê bai làm bạn buồn và dễ gây bất hòa.",options:["“Cậu kém thế!”","“Mình giúp cậu nhé!”","“Cảm ơn cậu!”","“Mình xin lỗi.”"],answer:0}]},{questions:[{id:"dd3-nhan-biet-bat-hoa-19",type:"mc",q:"Nam đang chơi thì bị Tùng vô ý va ngã. Nam nghĩ Tùng cố ý. Nam nên làm gì?",explain:"Hỏi lại cho rõ giúp Nam tránh hiểu lầm bạn.",options:["Đẩy lại Tùng ngay","Bình tĩnh hỏi lại Tùng cho rõ","Mách cô là Tùng đánh mình","Không chơi với Tùng nữa"],answer:1},{id:"dd3-nhan-biet-bat-hoa-20",type:"tf",q:"Vy làm rách sách mượn của Ngọc mà không nói. Ngọc phát hiện và hai bạn giận nhau. Lí do là Vy không thật thà nhận lỗi.",explain:"Đúng rồi. Nếu Vy nhận lỗi ngay, hai bạn đã không giận nhau.",answer:!0},{id:"dd3-nhan-biet-bat-hoa-21",type:"multi",q:"Khoa và Phúc cãi nhau vì giành bóng. Các bạn xung quanh nên làm gì?",explain:"Các bạn giúp hai bạn bình tĩnh, gợi ý cách chơi công bằng và báo thầy cô khi cần.",options:["Khuyên hai bạn bình tĩnh","Gợi ý hai bạn thay phiên nhau chơi","Cổ vũ hai bạn cãi to hơn","Báo thầy cô nếu hai bạn xô đẩy nhau"],answers:[0,1,3]},{id:"dd3-nhan-biet-bat-hoa-22",type:"mc",q:"Hai bạn thân của Thảo giận nhau, mỗi bạn rủ Thảo về phe mình. Thảo nên làm gì?",explain:"Thảo giữ công bằng và giúp hai bạn làm lành.",options:["Theo phe bạn nào thân với mình hơn","Không đứng về phe nào, giúp hai bạn làm lành","Kể chuyện hai bạn giận nhau cho cả lớp nghe","Tránh mặt cả hai bạn cho khỏi phiền"],answer:1},{id:"dd3-nhan-biet-bat-hoa-23",type:"tf",q:"Dũng giận Minh nên rủ cả lớp không chơi với Minh. Dũng làm đúng.",explain:"Sai. Rủ cả lớp tẩy chay làm Minh tổn thương và bất hòa thêm lớn.",answer:!1},{id:"dd3-nhan-biet-bat-hoa-24",type:"order",q:"Hai bạn tranh nhau đọc một quyển truyện. Sắp xếp cách giải quyết hợp lí.",explain:"Dừng lại, nói ra mong muốn, thỏa thuận rồi làm theo.",items:["Dừng tranh giành","Bình tĩnh nói ra mong muốn của mình","Thỏa thuận ai đọc trước, ai đọc sau","Vui vẻ đọc theo thỏa thuận"]},{id:"dd3-nhan-biet-bat-hoa-25",type:"mc",q:"Bình hay trêu chọc làm bạn tức giận. Bình cần làm gì?",explain:"Trêu chọc làm bạn buồn. Bình cần dừng lại và xin lỗi.",options:["Dừng trêu chọc và xin lỗi bạn","Trêu bạn nhiều hơn cho vui","Bảo bạn là không biết đùa","Quay sang trêu một bạn khác trong lớp"],answer:0},{id:"dd3-nhan-biet-bat-hoa-26",type:"fill",q:"Bất hòa thường bắt đầu từ hiểu …",explain:"Nhiều lần bất hòa bắt đầu từ hiểu lầm.",answer:["lầm","nhầm"]},{id:"dd3-nhan-biet-bat-hoa-27",type:"match",q:"Nối câu nói với điều nó có thể gây ra.",explain:"Lời nói nhẹ nhàng giúp làm lành, lời chê bai gây bất hòa.",pairs:[["“Bạn thật vô dụng!”","Làm bạn buồn, dễ bất hòa"],["“Mình hiểu nhầm, xin lỗi bạn.”","Giúp hai bạn làm lành"],["“Mình thay phiên nhau nhé!”","Tránh được tranh giành"]]}]}],challenge:{questions:[{id:"dd3-nhan-biet-bat-hoa-28",type:"mc",q:"Chi nghe một bạn kể là Lan nói xấu mình. Chi nên làm gì trước tiên?",explain:"Nghe kể lại chưa chắc đúng. Chi hỏi rõ để tránh hiểu lầm.",options:["Nói xấu Lan lại","Giận Lan ngay, không nói chuyện","Kể với cả lớp","Bình tĩnh hỏi lại Lan cho rõ"],answer:3},{id:"dd3-nhan-biet-bat-hoa-29",type:"tf",q:"Lắng nghe ý kiến của bạn giúp tránh được nhiều hiểu lầm.",explain:"Đúng rồi. Lắng nghe giúp em hiểu bạn hơn.",answer:!0},{id:"dd3-nhan-biet-bat-hoa-30",type:"multi",q:"Những thói quen nào giúp tránh bất hòa?",explain:"Nói nhẹ nhàng, nhường nhịn, hỏi rõ giúp em tránh bất hòa.",options:["Nói năng nhẹ nhàng","Biết nhường nhịn","Hỏi rõ trước khi giận","Hay trêu chọc bạn","Giận ngay khi nghe người khác kể lại"],answers:[0,1,2]},{id:"dd3-nhan-biet-bat-hoa-19",type:"mc",q:"Nam đang chơi thì bị Tùng vô ý va ngã. Nam nghĩ Tùng cố ý. Nam nên làm gì?",explain:"Hỏi lại cho rõ giúp Nam tránh hiểu lầm bạn.",options:["Đẩy lại Tùng ngay","Bình tĩnh hỏi lại Tùng cho rõ","Mách cô là Tùng đánh mình","Không chơi với Tùng nữa"],answer:1},{id:"dd3-nhan-biet-bat-hoa-22",type:"mc",q:"Hai bạn thân của Thảo giận nhau, mỗi bạn rủ Thảo về phe mình. Thảo nên làm gì?",explain:"Thảo giữ công bằng và giúp hai bạn làm lành.",options:["Theo phe bạn nào thân với mình hơn","Không đứng về phe nào, giúp hai bạn làm lành","Kể chuyện hai bạn giận nhau cho cả lớp nghe","Tránh mặt cả hai bạn cho khỏi phiền"],answer:1},{id:"dd3-nhan-biet-bat-hoa-10",type:"match",q:"Nối tình huống với nguyên nhân gây bất hòa.",explain:"Hiểu lầm, không nhường nhịn, trêu chọc đều có thể gây bất hòa.",pairs:[["Bình cầm nhầm bút, Dũng tưởng Bình lấy","Hiểu lầm"],["Hai bạn giành nhau xích đu","Không nhường nhịn"],["Chi đặt biệt danh xấu cho bạn","Trêu chọc"]]}]},summary:["Bất hòa là khi em và bạn giận nhau, cãi nhau.","Bất hòa thường do hiểu lầm, không nhường nhịn hoặc trêu chọc nhau.","Cần xử lí bất hòa sớm để tình bạn tốt đẹp trở lại."]},{id:"dd3-xu-li-bat-hoa",title:"Cách xử lí bất hòa",weeks:[29,30],learn:[{title:"Các bước làm lành",text:"Em bình tĩnh, tìm hiểu nguyên nhân, nói chuyện cởi mở, xin lỗi nếu mình sai và tha thứ khi bạn biết lỗi.",example:"😌 💬 🤝"},{title:"Lời nói giúp làm lành",text:"Những câu nói chân thành giúp hai bạn hết giận và chơi lại với nhau.",example:"“Mình xin lỗi.” · “Mình chơi lại nhé!”"},{title:"Nhờ người lớn",text:"Nếu không tự giải quyết được, hoặc có bạn xô đẩy, đánh nhau, em nhờ thầy cô, bố mẹ giúp đỡ.",example:"👩‍🏫"}],practice:[{questions:[{id:"dd3-xu-li-bat-hoa-01",type:"mc",q:"Khi bất hòa với bạn, việc đầu tiên em nên làm là gì?",emoji:"😌",explain:"Bình tĩnh giúp em suy nghĩ và nói năng đúng mực.",options:["Nói to cho bạn sợ","Bình tĩnh lại","Bỏ đi mãi mãi","Xô đẩy bạn"],answer:1},{id:"dd3-xu-li-bat-hoa-02",type:"tf",q:"Khi mình có lỗi, em nên chân thành xin lỗi bạn.",explain:"Đúng rồi. Lời xin lỗi chân thành giúp bạn bớt giận.",answer:!0},{id:"dd3-xu-li-bat-hoa-03",type:"tf",q:"Bạn đã biết lỗi và xin lỗi, em vẫn nên giận bạn thật lâu.",explain:"Sai. Khi bạn đã biết lỗi, em nên tha thứ.",answer:!1},{id:"dd3-xu-li-bat-hoa-04",type:"multi",q:"Câu nói nào giúp làm lành với bạn?",explain:"Lời xin lỗi và lời rủ chơi lại giúp hai bạn làm lành.",options:["“Mình xin lỗi bạn.”","“Tại bạn hết!”","“Mình chơi lại với nhau nhé!”","“Kệ bạn!”"],answers:[0,2]},{id:"dd3-xu-li-bat-hoa-05",type:"fill",q:"Khi bạn biết lỗi, em nên tha … cho bạn.",explain:"Em nên tha thứ cho bạn.",answer:["thứ"]},{id:"dd3-xu-li-bat-hoa-06",type:"mc",q:"Nếu không tự làm lành được, em có thể nhờ ai?",explain:"Thầy cô, bố mẹ có thể giúp các em hiểu nhau và làm lành.",options:["Người lạ","Bạn hay trêu chọc","Thầy cô hoặc bố mẹ","Không nhờ ai"],answer:2},{id:"dd3-xu-li-bat-hoa-07",type:"tf",q:"Đánh nhau là cách tốt để giải quyết bất hòa.",explain:"Sai. Đánh nhau gây đau và làm bất hòa lớn hơn.",answer:!1},{id:"dd3-xu-li-bat-hoa-08",type:"mc",q:"Cách nào giúp em bình tĩnh khi đang giận?",explain:"Hít thở sâu, đếm chậm giúp cơn giận nguôi đi.",options:["Hít thở sâu và đếm chậm","Hét thật to cho hả giận","Ném đồ đạc","Đóng sầm cửa"],answer:0},{id:"dd3-xu-li-bat-hoa-09",type:"tf",q:"Nói chuyện cởi mở giúp hai bạn hiểu nhau hơn.",explain:"Đúng rồi. Nói ra điều mình nghĩ giúp hai bạn hiểu nhau.",answer:!0}]},{questions:[{id:"dd3-xu-li-bat-hoa-10",type:"order",q:"Sắp xếp các bước xử lí bất hòa với bạn.",explain:"Bình tĩnh, tìm nguyên nhân, nói chuyện rồi làm lành.",items:["Bình tĩnh lại","Tìm hiểu nguyên nhân","Nói chuyện với bạn","Xin lỗi hoặc tha thứ và làm lành"]},{id:"dd3-xu-li-bat-hoa-11",type:"mc",q:"Vì sao cần bình tĩnh trước khi nói chuyện với bạn?",explain:"Bình tĩnh giúp em nói năng nhẹ nhàng, không làm bạn buồn thêm.",options:["Để không nói lời làm bạn buồn thêm","Để bạn sợ mình mà nhường mình","Để cãi nhau với bạn được lâu hơn nữa","Để nghĩ ra cách nói thắng bạn"],answer:0},{id:"dd3-xu-li-bat-hoa-12",type:"match",q:"Nối tình huống với cách xử lí.",explain:"Mỗi tình huống cần một cách xử lí phù hợp.",pairs:[["Mình có lỗi","Xin lỗi bạn"],["Bạn đã xin lỗi","Tha thứ cho bạn"],["Hai bạn hiểu lầm","Nói chuyện để hiểu nhau"]]},{id:"dd3-xu-li-bat-hoa-13",type:"tf",q:"Khi làm lành, em lắng nghe cả ý kiến của bạn.",explain:"Đúng rồi. Lắng nghe giúp em hiểu bạn nghĩ gì.",answer:!0},{id:"dd3-xu-li-bat-hoa-14",type:"multi",q:"Việc nào KHÔNG nên làm khi xử lí bất hòa?",explain:"La hét, nói xấu, xô đẩy làm mọi việc tệ hơn.",options:["La hét","Nói xấu bạn","Bình tĩnh nói chuyện","Xô đẩy bạn"],answers:[0,1,3]},{id:"dd3-xu-li-bat-hoa-15",type:"tf",q:"Người xin lỗi trước là người thua cuộc.",explain:"Sai. Dám xin lỗi trước là người dũng cảm và biết quý tình bạn.",answer:!1},{id:"dd3-xu-li-bat-hoa-16",type:"mc",q:"Bạn nào biết cách xử lí bất hòa?",explain:"An chủ động, bình tĩnh mời bạn nói chuyện.",options:["Bình giật lại đồ của bạn cho bằng được rồi bỏ đi","An nói: “Mình nói chuyện nhé, mình không muốn giận nhau.”","Chi bỏ đi rồi nói xấu bạn với các bạn khác trong lớp","Dũng hét lên thật to và đẩy bạn ra"],answer:1},{id:"dd3-xu-li-bat-hoa-17",type:"tf",q:"Sau khi làm lành, em và bạn nên rút kinh nghiệm để không lặp lại.",explain:"Đúng rồi. Rút kinh nghiệm giúp tình bạn bền lâu.",answer:!0},{id:"dd3-xu-li-bat-hoa-18",type:"mc",q:"Thấy các bạn xô đẩy, đánh nhau, em nên làm gì?",explain:"Báo người lớn ngay để giữ an toàn cho các bạn.",options:["Lao vào cùng đánh nhau với các bạn","Đứng xem và cổ vũ các bạn","Quay video lại để trêu các bạn","Báo ngay thầy cô hoặc người lớn"],answer:3}]},{questions:[{id:"dd3-xu-li-bat-hoa-19",type:"mc",q:"Hà lỡ làm đổ nước vào vở của Lan, Lan rất giận. Hà nên làm gì?",explain:"Hà xin lỗi và sửa lỗi ngay để Lan bớt giận.",options:["Xin lỗi Lan và giúp lau khô vở","Bảo Lan là làm quá lên","Bỏ đi chỗ khác như không biết gì","Đổ lỗi cho bạn ngồi bên cạnh"],answer:0},{id:"dd3-xu-li-bat-hoa-20",type:"tf",q:"Minh và Khoa cãi nhau, Minh viết một lá thư nhỏ xin lỗi và rủ Khoa chơi lại. Minh đã biết cách làm lành.",explain:"Đúng rồi. Lá thư chân thành giúp hai bạn làm lành.",answer:!0},{id:"dd3-xu-li-bat-hoa-21",type:"multi",q:"Vy bị một bạn đặt biệt danh xấu nhiều lần. Vy nên làm gì?",explain:"Vy nói rõ, giữ bình tĩnh và nhờ thầy cô khi bạn không dừng.",options:["Nói rõ với bạn là mình không thích","Nếu bạn không dừng, nhờ thầy cô giúp","Đặt biệt danh xấu lại cho bạn","Giữ bình tĩnh, không đánh nhau"],answers:[0,1,3]},{id:"dd3-xu-li-bat-hoa-22",type:"order",q:"Tùng và Phúc giận nhau vì thua trò chơi. Sắp xếp cách làm lành.",explain:"Bình tĩnh, nói ra, nhận lỗi rồi làm lành.",items:["Hai bạn dừng chơi và hít thở sâu","Mỗi bạn kể lại điều mình thấy","Nhận ra phần lỗi của mình","Bắt tay làm lành và chơi tiếp"]},{id:"dd3-xu-li-bat-hoa-23",type:"mc",q:"Ngọc đã xin lỗi nhưng Thảo vẫn còn giận. Ngọc nên làm gì?",explain:"Có khi bạn cần thêm thời gian. Ngọc kiên nhẫn và thân thiện.",options:["Giận lại Thảo vì bạn không chịu tha thứ","Kiên nhẫn chờ bạn nguôi giận và vẫn thân thiện","Nói xấu Thảo với các bạn trong lớp","Bắt Thảo phải hết giận ngay lập tức"],answer:1},{id:"dd3-xu-li-bat-hoa-24",type:"tf",q:"Đang giận bạn, Nam nhắn tin chê bai bạn cho cả nhóm cùng đọc. Nam làm đúng.",explain:"Sai. Chê bai bạn trước nhiều người làm bạn tổn thương.",answer:!1},{id:"dd3-xu-li-bat-hoa-25",type:"mc",q:"Hai bạn trong nhóm tranh cãi vì mỗi bạn muốn vẽ một kiểu. Cách nào hợp lí?",explain:"Lắng nghe và cùng thống nhất giúp nhóm làm việc vui vẻ.",options:["Bạn nào nói to hơn thì bạn đó thắng","Mỗi bạn bỏ đi một nơi, không vẽ nữa","Xé bức tranh đi để không ai phải tranh cãi","Lắng nghe ý nhau rồi chọn cách cả nhóm đồng ý"],answer:3},{id:"dd3-xu-li-bat-hoa-26",type:"fill",q:"Muốn làm lành, em cần bình … , không la hét.",explain:"Em cần bình tĩnh.",answer:["tĩnh"]},{id:"dd3-xu-li-bat-hoa-27",type:"match",q:"Nối việc làm với kết quả của nó.",explain:"Mỗi việc làm đúng đều giúp xử lí bất hòa tốt hơn.",pairs:[["Xin lỗi chân thành","Bạn dễ tha thứ"],["Lắng nghe bạn nói","Hiểu được bạn"],["Báo thầy cô khi bạn đánh nhau","Mọi người được an toàn"]]}]}],challenge:{questions:[{id:"dd3-xu-li-bat-hoa-28",type:"mc",q:"Dũng và An đều có lỗi trong lần cãi nhau. Cách làm lành tốt nhất là gì?",explain:"Khi cả hai cùng có lỗi, cả hai cùng xin lỗi là công bằng nhất.",options:["Mỗi bạn chờ bạn kia xin lỗi trước","Chỉ một bạn kia phải xin lỗi thôi","Cả hai cùng nhận lỗi và xin lỗi nhau","Không ai cần xin lỗi ai cả"],answer:2},{id:"dd3-xu-li-bat-hoa-29",type:"tf",q:"Biết tha thứ giúp em nhẹ lòng và giữ được tình bạn.",explain:"Đúng rồi. Tha thứ giúp tình bạn tiếp tục tốt đẹp.",answer:!0},{id:"dd3-xu-li-bat-hoa-30",type:"multi",q:"Sau khi làm lành, em có thể làm gì để tình bạn tốt hơn?",explain:"Chơi cùng, nói nhẹ nhàng, giúp nhau học làm tình bạn thêm gắn bó.",options:["Cùng chơi trò chơi chung","Nói lời nhẹ nhàng với nhau","Giúp nhau trong học tập","Nhắc lại lỗi của bạn mãi"],answers:[0,1,2]},{id:"dd3-xu-li-bat-hoa-19",type:"mc",q:"Hà lỡ làm đổ nước vào vở của Lan, Lan rất giận. Hà nên làm gì?",explain:"Hà xin lỗi và sửa lỗi ngay để Lan bớt giận.",options:["Xin lỗi Lan và giúp lau khô vở","Bảo Lan là làm quá lên","Bỏ đi chỗ khác như không biết gì","Đổ lỗi cho bạn ngồi bên cạnh"],answer:0},{id:"dd3-xu-li-bat-hoa-21",type:"multi",q:"Vy bị một bạn đặt biệt danh xấu nhiều lần. Vy nên làm gì?",explain:"Vy nói rõ, giữ bình tĩnh và nhờ thầy cô khi bạn không dừng.",options:["Nói rõ với bạn là mình không thích","Nếu bạn không dừng, nhờ thầy cô giúp","Đặt biệt danh xấu lại cho bạn","Giữ bình tĩnh, không đánh nhau"],answers:[0,1,3]},{id:"dd3-xu-li-bat-hoa-10",type:"order",q:"Sắp xếp các bước xử lí bất hòa với bạn.",explain:"Bình tĩnh, tìm nguyên nhân, nói chuyện rồi làm lành.",items:["Bình tĩnh lại","Tìm hiểu nguyên nhân","Nói chuyện với bạn","Xin lỗi hoặc tha thứ và làm lành"]}]},summary:["Khi bất hòa, em bình tĩnh, tìm hiểu nguyên nhân và nói chuyện với bạn.","Em xin lỗi khi mình sai và tha thứ khi bạn biết lỗi.","Không tự giải quyết được hoặc có xô xát, em nhờ thầy cô, bố mẹ."]}]},{id:"an-toan-giao-thong",title:"Tuân thủ quy tắc an toàn giao thông",lessons:[{id:"dd3-an-toan-giao-thong",title:"Em tuân thủ quy tắc an toàn giao thông",weeks:[31,34],learn:[{title:"Đèn tín hiệu",text:"Đèn đỏ: dừng lại. Đèn vàng: chậm lại, chuẩn bị dừng. Đèn xanh: được đi.",example:"🚦"},{title:"Đi bộ an toàn",text:"Em đi trên vỉa hè, không có vỉa hè thì đi sát mép đường. Qua đường ở vạch kẻ cho người đi bộ, quan sát kĩ và đi cùng người lớn.",example:"🚸"},{title:"Ngồi trên xe",text:"Ngồi sau xe máy, em đội mũ bảo hiểm, cài quai. Đi ô tô, em thắt dây an toàn, không thò đầu, thò tay ra ngoài.",example:"🪖 🚗"},{title:"Biển báo",text:"Biển cấm hình tròn, viền đỏ. Biển nguy hiểm hình tam giác, viền đỏ. Biển hiệu lệnh hình tròn, nền xanh.",example:"⛔ ⚠️ 🔵"}],practice:[{questions:[{id:"dd3-an-toan-giao-thong-01",type:"mc",q:"Gặp đèn đỏ, người tham gia giao thông phải làm gì?",emoji:"🔴",explain:"Đèn đỏ là tín hiệu dừng lại.",options:["Đi thật nhanh","Dừng lại","Bấm còi liên tục","Rẽ ngang qua đường"],answer:1},{id:"dd3-an-toan-giao-thong-02",type:"mc",q:"Đèn tín hiệu màu nào cho phép đi?",emoji:"🚦",explain:"Đèn xanh là tín hiệu được đi.",options:["Đèn đỏ","Đèn xanh","Đèn vàng"],answer:1},{id:"dd3-an-toan-giao-thong-03",type:"tf",q:"Ngồi sau xe máy, em phải đội mũ bảo hiểm và cài quai.",emoji:"🪖",explain:"Đúng rồi. Mũ bảo hiểm cài quai chắc chắn giúp bảo vệ đầu em.",answer:!0},{id:"dd3-an-toan-giao-thong-04",type:"tf",q:"Lòng đường là nơi an toàn để chơi đá bóng.",explain:"Sai. Chơi dưới lòng đường rất nguy hiểm vì xe cộ qua lại.",answer:!1},{id:"dd3-an-toan-giao-thong-05",type:"multi",q:"Việc làm nào đúng khi đi bộ?",explain:"Đi trên vỉa hè, qua đường ở vạch kẻ và nắm tay người lớn là đúng.",options:["Đi trên vỉa hè","Qua đường ở vạch kẻ cho người đi bộ","Vừa đi vừa đùa nghịch dưới lòng đường","Nắm tay người lớn khi qua đường","Chạy vụt qua đường khi thấy xe còn xa"],answers:[0,1,3]},{id:"dd3-an-toan-giao-thong-06",type:"fill",q:"Khi đi ô tô, em cần thắt dây an …",explain:"Em thắt dây an toàn khi đi ô tô.",answer:["toàn"]},{id:"dd3-an-toan-giao-thong-07",type:"mc",q:"Nơi không có vỉa hè, em đi bộ thế nào?",explain:"Không có vỉa hè, em đi sát mép đường để tránh xe.",options:["Đi sát mép đường","Đi giữa lòng đường","Vừa đi vừa chạy nhảy ra giữa đường"],answer:0},{id:"dd3-an-toan-giao-thong-08",type:"tf",q:"Ngồi trên ô tô, em có thể thò đầu, thò tay ra ngoài cửa sổ.",explain:"Sai. Thò đầu, thò tay ra ngoài rất dễ bị va chạm.",answer:!1},{id:"dd3-an-toan-giao-thong-09",type:"match",q:"Nối màu đèn tín hiệu với ý nghĩa của nó.",explain:"Đỏ dừng, vàng chậm lại chuẩn bị dừng, xanh được đi.",pairs:[["Đèn đỏ","Dừng lại"],["Đèn vàng","Chậm lại, chuẩn bị dừng"],["Đèn xanh","Được đi"]]}]},{questions:[{id:"dd3-an-toan-giao-thong-10",type:"mc",q:"Vì sao phải tuân thủ quy tắc an toàn giao thông?",explain:"Tuân thủ quy tắc giao thông giúp mọi người tránh tai nạn.",options:["Để đi nhanh hơn tất cả những người khác trên đường","Để được chụp ảnh đẹp khi đi trên đường","Vì đèn giao thông có nhiều màu rất đẹp","Để bảo vệ bản thân và mọi người khỏi tai nạn"],answer:3},{id:"dd3-an-toan-giao-thong-11",type:"match",q:"Nối loại biển báo với đặc điểm của nó.",explain:"Mỗi nhóm biển báo có hình dạng và màu sắc riêng.",pairs:[["Biển báo cấm","Hình tròn, viền đỏ"],["Biển báo nguy hiểm","Hình tam giác, viền đỏ"],["Biển hiệu lệnh","Hình tròn, nền xanh"]]},{id:"dd3-an-toan-giao-thong-12",type:"tf",q:"Đội mũ bảo hiểm đúng cách giúp bảo vệ đầu khi có va chạm.",explain:"Đúng rồi. Vì thế em luôn đội mũ và cài quai cẩn thận.",answer:!0},{id:"dd3-an-toan-giao-thong-13",type:"order",q:"Sắp xếp các bước qua đường an toàn.",explain:"Dừng lại, quan sát kĩ rồi mới đi thẳng qua đường.",items:["Dừng lại ở mép đường","Quan sát kĩ xe cộ hai bên","Đi thẳng qua vạch kẻ khi đường an toàn"]},{id:"dd3-an-toan-giao-thong-14",type:"multi",q:"Hành vi nào nguy hiểm khi tham gia giao thông?",explain:"Chạy qua đường, chơi dưới lòng đường, đi dàn hàng ngang đều nguy hiểm.",options:["Chạy băng qua đường không quan sát","Đá bóng dưới lòng đường","Đội mũ bảo hiểm khi ngồi sau xe máy","Đi xe đạp dàn hàng ngang"],answers:[0,1,3]},{id:"dd3-an-toan-giao-thong-15",type:"tf",q:"Đèn vàng bật lên thì cần đi nhanh hơn để qua kịp.",explain:"Sai. Đèn vàng báo cần chậm lại và chuẩn bị dừng.",answer:!1},{id:"dd3-an-toan-giao-thong-16",type:"mc",q:"Ngồi sau xe máy, em nên ngồi thế nào?",explain:"Ngồi ngay ngắn, bám chắc giúp em không bị ngã.",options:["Đứng lên yên xe để nhìn đường cho rõ","Ngồi ngay ngắn, bám chắc người ngồi trước","Quay ngang quay ngửa nhìn xung quanh","Buông hai tay ra để vẫy chào bạn"],answer:1},{id:"dd3-an-toan-giao-thong-17",type:"tf",q:"Chơi đùa gần đường ray tàu hỏa rất nguy hiểm.",explain:"Đúng rồi. Tàu chạy nhanh và không thể dừng ngay, em tránh xa đường ray.",answer:!0},{id:"dd3-an-toan-giao-thong-18",type:"mc",q:"Khi đi đò, đi thuyền, em cần làm gì?",explain:"Mặc áo phao và ngồi yên giúp em an toàn trên sông nước.",options:["Đứng lên đung đưa thuyền","Nhoài người nghịch nước","Chạy nhảy trên thuyền","Mặc áo phao và ngồi yên"],answer:3}]},{questions:[{id:"dd3-an-toan-giao-thong-19",type:"mc",q:"Trên đường đi học, các bạn rủ Minh đá bóng dưới lòng đường. Minh nên làm gì?",explain:"Minh từ chối vì lòng đường rất nguy hiểm, nên chơi ở nơi an toàn.",options:["Từ chối và rủ các bạn chơi ở sân trường","Cùng các bạn đá bóng dưới lòng đường","Đứng giữa lòng đường để cổ vũ các bạn đá bóng","Đá bóng dưới đường một lúc rồi mới về"],answer:0},{id:"dd3-an-toan-giao-thong-20",type:"tf",q:"Bố chở Lan đi học bằng xe máy, Lan tự giác đội mũ bảo hiểm và cài quai. Lan làm đúng.",explain:"Đúng rồi. Lan có ý thức giữ an toàn cho mình.",answer:!0},{id:"dd3-an-toan-giao-thong-21",type:"multi",q:"Đi xe đạp đến trường, Khoa cần làm gì?",explain:"Khoa đi bên phải, đội mũ bảo hiểm, không buông tay, không đùa nghịch khi đạp xe.",options:["Đi bên phải đường","Đội mũ bảo hiểm","Vừa đạp xe vừa đùa với bạn","Buông hai tay khi đạp xe"],answers:[0,1]},{id:"dd3-an-toan-giao-thong-22",type:"mc",q:"Hà thấy bạn định chạy qua đường khi xe đang đến gần. Hà nên làm gì?",explain:"Hà nhắc bạn dừng lại để tránh tai nạn.",options:["Gọi bạn dừng lại, chờ đường an toàn","Chạy theo sau bạn qua đường","Đứng im, không nói gì với bạn","Cười vì thấy bạn chạy nhanh quá"],answer:0},{id:"dd3-an-toan-giao-thong-23",type:"order",q:"Sắp xếp việc em làm khi lên ô tô của gia đình.",explain:"Lên xe khi xe dừng hẳn, ngồi ngay ngắn, thắt dây an toàn và ngồi yên.",items:["Chờ xe dừng hẳn rồi mới lên","Ngồi ngay ngắn vào ghế","Thắt dây an toàn","Ngồi yên, không thò tay ra ngoài"]},{id:"dd3-an-toan-giao-thong-24",type:"tf",q:"Tùng đi trên vỉa hè nhưng vừa đi vừa cúi xem điện thoại. Như vậy là an toàn.",explain:"Sai. Vừa đi vừa xem điện thoại làm Tùng mất tập trung, dễ va vấp.",answer:!1},{id:"dd3-an-toan-giao-thong-25",type:"mc",q:"Gặp biển báo hình tam giác viền đỏ, em hiểu đó là biển gì?",emoji:"⚠️",explain:"Biển hình tam giác viền đỏ là biển báo nguy hiểm.",options:["Biển chỉ đường đến trường","Biển hiệu lệnh","Biển quảng cáo","Biển báo nguy hiểm, cần chú ý"],answer:3},{id:"dd3-an-toan-giao-thong-26",type:"fill",q:"Ngồi sau xe máy, em phải đội mũ bảo …",explain:"Em phải đội mũ bảo hiểm.",answer:["hiểm"]},{id:"dd3-an-toan-giao-thong-27",type:"tf",q:"Vy nhắc em trai không chạy ra đường khi chơi trước ngõ. Vy biết giữ an toàn cho em.",explain:"Đúng rồi. Vy quan tâm và giữ an toàn cho em mình.",answer:!0}]}],challenge:{questions:[{id:"dd3-an-toan-giao-thong-28",type:"mc",q:"Đi học về, Ngọc thấy một bạn nhỏ bị ngã xe đạp ven đường. Ngọc nên làm gì?",explain:"Ngọc gọi người lớn giúp vừa kịp thời vừa an toàn.",options:["Chạy ra giữa đường kéo xe","Đi tiếp như không thấy","Gọi người lớn gần đó đến giúp","Đứng cười"],answer:2},{id:"dd3-an-toan-giao-thong-29",type:"multi",q:"Những bạn nào chấp hành đúng luật giao thông?",explain:"An, Chi, Phúc làm đúng. Trèo qua dải phân cách rất nguy hiểm.",options:["An dừng lại khi đèn đỏ","Chi qua đường ở vạch kẻ cho người đi bộ","Dũng trèo qua dải phân cách","Phúc đội mũ bảo hiểm khi ngồi sau xe máy"],answers:[0,1,3]},{id:"dd3-an-toan-giao-thong-30",type:"tf",q:"Tuân thủ luật giao thông là trách nhiệm của tất cả mọi người, kể cả trẻ em.",explain:"Đúng rồi. Ai cũng cần chấp hành luật giao thông để cùng an toàn.",answer:!0},{id:"dd3-an-toan-giao-thong-19",type:"mc",q:"Trên đường đi học, các bạn rủ Minh đá bóng dưới lòng đường. Minh nên làm gì?",explain:"Minh từ chối vì lòng đường rất nguy hiểm, nên chơi ở nơi an toàn.",options:["Từ chối và rủ các bạn chơi ở sân trường","Cùng các bạn đá bóng dưới lòng đường","Đứng giữa lòng đường để cổ vũ các bạn đá bóng","Đá bóng dưới đường một lúc rồi mới về"],answer:0},{id:"dd3-an-toan-giao-thong-22",type:"mc",q:"Hà thấy bạn định chạy qua đường khi xe đang đến gần. Hà nên làm gì?",explain:"Hà nhắc bạn dừng lại để tránh tai nạn.",options:["Gọi bạn dừng lại, chờ đường an toàn","Chạy theo sau bạn qua đường","Đứng im, không nói gì với bạn","Cười vì thấy bạn chạy nhanh quá"],answer:0},{id:"dd3-an-toan-giao-thong-11",type:"match",q:"Nối loại biển báo với đặc điểm của nó.",explain:"Mỗi nhóm biển báo có hình dạng và màu sắc riêng.",pairs:[["Biển báo cấm","Hình tròn, viền đỏ"],["Biển báo nguy hiểm","Hình tam giác, viền đỏ"],["Biển hiệu lệnh","Hình tròn, nền xanh"]]}]},summary:["Đèn đỏ dừng lại, đèn vàng chậm lại chuẩn bị dừng, đèn xanh được đi.","Em đi trên vỉa hè, qua đường ở vạch kẻ cùng người lớn.","Em đội mũ bảo hiểm khi ngồi sau xe máy, thắt dây an toàn khi đi ô tô."]}]}],g={grade:3,subject:n,title:h,review:i,topics:t};export{g as default,c as grade,i as review,n as subject,h as title,t as topics};
